ActiveWinFspDriverProbeResult ProbeWinFspDriverForStartupTest(
    std::uint16_t& major,
    std::uint16_t& minor,
    std::uint16_t& build,
    std::uint16_t& revision,
    std::filesystem::path& binary_path,
    const std::filesystem::path& expected_binary_path)
{
    if (g_winfsp_probe_index >= g_winfsp_probe_results.size())
    {
        return ActiveWinFspDriverProbeResult::NotFound;
    }

    const auto result = g_winfsp_probe_results[g_winfsp_probe_index++];
    if (result == ActiveWinFspDriverProbeResult::Found)
    {
        major = 2;
        minor = 2;
        build = 26215;
        revision = 0;
        binary_path = expected_binary_path;
    }
    return result;
}

