bool PrepareUnitHydrationRoot(MountContext& context, const wchar_t* name)
{
    static std::atomic<std::uint64_t> unique_root{0};
    std::error_code ec;
    const auto suffix = name && *name ? std::wstring(name) : L"default";
    context.session_root = std::filesystem::temp_directory_path(ec) /
        "ApfsAccess" /
        "fs-host-semantics" /
        (suffix + L"-" + std::to_wstring(GetCurrentProcessId()) + L"-" +
            std::to_wstring(GetTickCount64()) + L"-" + std::to_wstring(unique_root.fetch_add(1)));
    if (ec)
    {
        return false;
    }

    context.cache_root = context.session_root / "hydrate";
    std::filesystem::create_directories(context.cache_root, ec);
    return !ec;
}

bool WriteFileBytes(const std::filesystem::path& path, const std::vector<std::byte>& bytes)
{
    std::error_code ec;
    std::filesystem::create_directories(path.parent_path(), ec);
    if (ec)
    {
        return false;
    }

    std::ofstream out(path, std::ios::binary | std::ios::trunc);
    if (!out.good())
    {
        return false;
    }

    if (!bytes.empty())
    {
        out.write(reinterpret_cast<const char*>(bytes.data()), static_cast<std::streamsize>(bytes.size()));
    }
    return out.good();
}

bool SeedResizableUnitFile(MountContext& context, std::shared_ptr<Node>& file)
{
    auto root = context.nodes.at(Key(L"\\"));
    AddChildName(root->children, L"resize.bin");

    file = MakeNode(L"\\resize.bin", false, false);
    file->file_size = 4;
    context.nodes.emplace(Key(file->path), file);
    return WriteFileBytes(
        HydrationPath(&context, *file),
        { std::byte{'A'}, std::byte{'B'}, std::byte{'C'}, std::byte{'D'} });
}

bool OpenResizableUnitFile(MountContext& context, const std::shared_ptr<Node>& file, OpenContext& open_context)
{
    if (!file)
    {
        return false;
    }

    open_context.node = file;
    open_context.allow_set_file_size = true;
    open_context.allow_write_data = true;
    open_context.file = CreateFileW(
        HydrationPath(&context, *file).wstring().c_str(),
        GENERIC_READ | GENERIC_WRITE,
        FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
        nullptr,
        OPEN_EXISTING,
        FILE_ATTRIBUTE_NORMAL,
        nullptr);
    return open_context.file != INVALID_HANDLE_VALUE;
}

bool WriteUnitContent(FSP_FILE_SYSTEM& fs, OpenContext* open_context, FSP_FSCTL_FILE_INFO& info)
{
    std::array<std::byte, 4> payload{std::byte{'W'}, std::byte{'R'}, std::byte{'I'}, std::byte{'T'}};
    ULONG done = 0;
    const auto status = CB_Write(
        &fs,
        open_context,
        payload.data(),
        0,
        static_cast<ULONG>(payload.size()),
        FALSE,
        FALSE,
        &done,
        &info);
    return status == STATUS_SUCCESS && done == payload.size();
}

struct SeededDirectoryTree
{
    std::shared_ptr<Node> root;
    std::shared_ptr<Node> source_dir;
    std::shared_ptr<Node> child_dir;
    std::shared_ptr<Node> file;
};

SeededDirectoryTree SeedCommittedDirectoryRenameTree(MountContext& context)
{
    SeededDirectoryTree tree{};
    tree.root = context.nodes.at(Key(L"\\"));
    AddChildName(tree.root->children, L"source");

    tree.source_dir = MakeNode(L"\\source", true, false);
    AddChildName(tree.source_dir->children, L"child");

    tree.child_dir = MakeNode(L"\\source\\child", true, false);
    AddChildName(tree.child_dir->children, L"file.bin");

    tree.file = MakeNode(L"\\source\\child\\file.bin", false, false);
    tree.file->file_size = 4;

    context.nodes.emplace(Key(tree.source_dir->path), tree.source_dir);
    context.nodes.emplace(Key(tree.child_dir->path), tree.child_dir);
    context.nodes.emplace(Key(tree.file->path), tree.file);
    return tree;
}

bool ConfigureUnitRecoveryMarker(MountContext& context, const wchar_t* name)
{
    std::error_code ec;
    const auto marker_root = std::filesystem::temp_directory_path(ec) / "ApfsAccess" / "fs-host-semantics";
    if (ec)
    {
        return false;
    }
    std::filesystem::create_directories(marker_root, ec);
    if (ec)
    {
        return false;
    }

    const auto suffix = name && *name ? std::wstring(name) : L"marker";
    context.recovery_marker_file = marker_root / (suffix + L"-" + std::to_wstring(GetTickCount64()) + L".state");
    return true;
}

std::vector<std::byte> ReadFileBytes(const std::filesystem::path& path)
{
    std::ifstream in(path, std::ios::binary);
    if (!in.good())
    {
        return {};
    }

    const std::vector<char> chars{
        std::istreambuf_iterator<char>(in),
        std::istreambuf_iterator<char>()};
    std::vector<std::byte> bytes;
    bytes.reserve(chars.size());
    for (const char ch : chars)
    {
        bytes.push_back(static_cast<std::byte>(static_cast<unsigned char>(ch)));
    }
    return bytes;
}

std::vector<std::byte> ReadHandleBytes(HANDLE handle, DWORD bytes_to_read)
{
    if (handle == INVALID_HANDLE_VALUE)
    {
        return {};
    }

    LARGE_INTEGER start{};
    if (!SetFilePointerEx(handle, start, nullptr, FILE_BEGIN))
    {
        return {};
    }

    std::vector<std::byte> buffer(bytes_to_read);
    DWORD read = 0;
    if (!ReadFile(handle, buffer.data(), bytes_to_read, &read, nullptr))
    {
        return {};
    }
    buffer.resize(read);
    return buffer;
}

