bool TestDeleteCloseDoesNotRevalidateSubtreeDuringRemoval()
{
    MountContext context{};
    context.overlay_write_enabled = true;
    SeedRoot(context);
    std::array<std::byte, 16> security{};
    SeedSecurity(context, security);

    auto root = context.nodes.at(Key(L"\\"));
    AddChildName(*root, L"delete-me");

    auto directory = MakeNode(L"\\delete-me", true, false);
    directory->open_handle_count = 1;
    context.nodes.emplace(Key(directory->path), directory);
    for (int i = 0; i < 32; ++i)
    {
        const auto child_name = L"child-" + std::to_wstring(i) + L".txt";
        AddChildName(*directory, child_name);
        const auto child = MakeNode(L"\\delete-me\\" + child_name, false, false);
        context.nodes.emplace(Key(child->path), child);
    }

    auto fs = BuildFileSystem(&context);
    auto* open_context = new OpenContext();
    open_context->node = directory;
    open_context->allow_delete = true;

    CB_Cleanup(
        &fs,
        open_context,
        const_cast<PWSTR>(L"\\delete-me"),
        FspCleanupDelete);
    ResetChildNameDebugCountersForTest();
    CB_Close(&fs, open_context);

    if (!Require(context.nodes.find(Key(L"\\delete-me")) == context.nodes.end(), "Delete close should remove the directory"))
    {
        return false;
    }
    constexpr std::uint64_t subtree_node_count = 33;
    constexpr std::uint64_t close_proof_count = 1;
    return Require(
        DebugCanRemoveNodeVisitCountForTest() == subtree_node_count * close_proof_count,
        "Delete close should reuse the validated postorder for local removal");
}

