bool TestDeferredWriteBackUsesSafeDefaultAndSupportsOptOut()
{
    SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
    SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", nullptr);
    SetEnvironmentVariableW(L"APFSACCESS_DISABLE_NAMESPACE_WRITEBACK", nullptr);
    SetEnvironmentVariableW(L"APFSACCESS_EXPERIMENTAL_NAMESPACE_WRITEBACK", nullptr);
    ScopeExit clear_env{[]()
    {
        SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_DISABLE_NAMESPACE_WRITEBACK", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_EXPERIMENTAL_NAMESPACE_WRITEBACK", nullptr);
    }};

    if (!Require(IsDeferCloseCommitsEnabled(), "Content write-back should be enabled by default when no override is present") ||
        !Require(!IsExperimentalNamespaceWriteBackEnabled(), "Namespace write-back should be disabled unless explicitly enabled"))
    {
        return false;
    }

    SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", L"0");
    if (!Require(!IsDeferCloseCommitsEnabled(), "Content write-back should support an explicit synchronous opt-out"))
    {
        return false;
    }

    SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", L"1");
    SetEnvironmentVariableW(L"APFSACCESS_EXPERIMENTAL_NAMESPACE_WRITEBACK", L"1");
    if (!Require(IsDeferCloseCommitsEnabled(), "Content write-back experiment switch should enable deferred close commits") ||
        !Require(IsExperimentalNamespaceWriteBackEnabled(), "Namespace write-back experiment switch should enable deferred namespace commits"))
    {
        return false;
    }

    SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", L"1");
    SetEnvironmentVariableW(L"APFSACCESS_DISABLE_NAMESPACE_WRITEBACK", L"1");
    return Require(!IsDeferCloseCommitsEnabled(), "Content write-back kill switch should override explicit opt-in") &&
           Require(!IsExperimentalNamespaceWriteBackEnabled(), "Namespace write-back kill switch should override explicit opt-in");
}

