bool TestDeferredCloseAllowsNewFileIngestBatch()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
    SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", L"1");
    SetEnvironmentVariableW(L"APFSACCESS_EXPERIMENTAL_NAMESPACE_WRITEBACK", L"1");
    ScopeExit clear_writeback_env{[]()
    {
        SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_EXPERIMENTAL_NAMESPACE_WRITEBACK", nullptr);
    }};

    MountContext context{};
    context.args.volume = L"Main";
    context.args.readwrite = true;
    context.args.write_backend = L"Native";
    context.args.write_require_canonical_commit = false;
    context.args.write_disallow_scaffold_commit_on_non_fixture = false;
    context.args.write_reject_scaffold_replay_blob_on_non_fixture = false;
    context.args.write_require_canonical_replay_candidate_on_non_fixture = false;
    context.native_write_enabled = true;
    context.overlay_write_enabled = false;
    SeedRoot(context);
    std::array<std::byte, 16> security{};
    SeedSecurity(context, security);
    if (!Require(PrepareUnitHydrationRoot(context, L"deferred-close-new-file-ingest"), "Deferred new-file ingest test should prepare cache root"))
    {
        return false;
    }
    if (!Require(ConfigureUnitRecoveryMarker(context, L"deferred-close-new-file-ingest"), "Deferred new-file ingest test should configure recovery marker"))
    {
        std::error_code ec;
        std::filesystem::remove_all(context.session_root, ec);
        return false;
    }

    std::error_code ec;
    ScopeExit cleanup{[&]()
    {
        StopDeferredCommitWorker(&context);
        std::filesystem::remove(context.recovery_marker_file, ec);
        std::filesystem::remove_all(context.session_root, ec);
    }};

    const auto image_path = context.session_root / "deferred-new-file-ingest.apfs.img";
    if (!Require(CreateSyntheticApfsContainerForTest(image_path), "Deferred new-file ingest test should create synthetic APFS image"))
    {
        return false;
    }
    context.args.device = image_path.wstring();

    apfsaccess::rw::MetadataStore::VolumeContext rw_context
    {
        image_path.wstring(),
        L"Main",
    };
    rw_context.allow_legacy_scaffold_for_fixtures = true;
    rw_context.disallow_scaffold_commit_on_non_fixture = false;
    rw_context.reject_scaffold_replay_blob_on_non_fixture = false;
    rw_context.require_canonical_replay_candidate_on_non_fixture = false;
    context.owned_metadata_store = std::make_unique<apfsaccess::rw::MetadataStore>(std::move(rw_context));
    context.metadata_store = context.owned_metadata_store.get();
    context.metadata_store->SetFilePayloadRangeProvider(
        [&context](
            const std::wstring& path,
            apfsaccess::rw::MetadataStore::PayloadIdentity identity,
            std::uint64_t offset,
            std::span<std::byte> destination) -> bool
        {
            return ReadHydratedPayloadRangeForPath(&context, path, identity, offset, destination);
        });
    {
        std::lock_guard<std::mutex> metadata_lock(context.metadata_mutex);
        if (!Require(context.metadata_store->LoadContainerSuperblocks(), "Deferred new-file ingest test should load container superblocks") ||
            !Require(context.metadata_store->LoadObjectMap(), "Deferred new-file ingest test should load object map") ||
            !Require(context.metadata_store->LoadSpacemanState(), "Deferred new-file ingest test should load spaceman state") ||
            !Require(context.metadata_store->PrepareNativeWritePath(), "Deferred new-file ingest test should prepare native write path"))
        {
            return false;
        }
    }

    context.payload_spool_volume_identity = "unit-deferred-new-file-ingest";
    context.payload_spool = std::make_unique<apfsaccess::rw::PayloadSpool>(
        apfsaccess::rw::PayloadSpool::Options{
            context.session_root / "payload-spool",
            context.payload_spool_volume_identity,
            1024 * 1024,
        });
    context.tx_manager = std::make_unique<apfsaccess::rw::TransactionManager>(L"Conservative");
    context.tx_manager->SetVolumeIdentity(L"unit-deferred-new-file-ingest");
    context.tx_manager->SetJournalPath((context.session_root / "new-file-ingest.wal").wstring());

    auto fs = BuildFileSystem(&context);
    PVOID out_ctx = nullptr;
    FSP_FSCTL_FILE_INFO info{};
    const auto create_status = CB_Create(
        &fs,
        const_cast<PWSTR>(L"\\fresh.bin"),
        FILE_NON_DIRECTORY_FILE,
        FILE_WRITE_DATA | FILE_WRITE_ATTRIBUTES,
        0,
        nullptr,
        0,
        &out_ctx,
        &info);
    if (!Require(create_status == STATUS_SUCCESS, "Deferred new-file ingest test should create file") ||
        !Require(out_ctx != nullptr, "Deferred new-file ingest test should return open context"))
    {
        return false;
    }

    auto* open_context = static_cast<OpenContext*>(out_ctx);
    const std::array<std::byte, 4> payload{
        std::byte{'N'},
        std::byte{'E'},
        std::byte{'W'},
        std::byte{'!'},
    };
    ULONG done = 0;
    const auto write_status = CB_Write(
        &fs,
        open_context,
        const_cast<std::byte*>(payload.data()),
        0,
        static_cast<ULONG>(payload.size()),
        FALSE,
        FALSE,
        &done,
        &info);
    if (!Require(write_status == STATUS_SUCCESS, "Deferred new-file ingest test should write payload") ||
        !Require(done == payload.size(), "Deferred new-file ingest test should report full write"))
    {
        CB_Close(&fs, open_context);
        return false;
    }

    bool hydration_stale_after_spool_write = false;
    {
        std::lock_guard<std::mutex> lock(context.mutex);
        hydration_stale_after_spool_write = IsHydrationStaleLocked(&context, open_context->node);
    }
    if (!Require(
            hydration_stale_after_spool_write,
            "A successful spool-backed write should leave the untouched hydration payload stale") ||
        !Require(
            ReadFileBytes(HydrationPath(&context, *open_context->node)).empty(),
            "A successful spool-backed write should not synchronously mirror payload bytes into hydration"))
    {
        CB_Close(&fs, open_context);
        return false;
    }

    constexpr std::uint64_t requested_timestamp = 116444736000000000ULL + 0x01DABEEF;
    const auto set_basic_status = CB_SetBasicInfo(
        &fs,
        open_context,
        INVALID_FILE_ATTRIBUTES,
        0,
        0,
        requested_timestamp,
        0,
        &info);
    if (!Require(set_basic_status == STATUS_SUCCESS && info.LastWriteTime == requested_timestamp,
            "Deferred new-file ingest test should set exact APFS-representable timestamp"))
    {
        std::cerr << "[INFO] legacy timestamp status=" << std::hex << static_cast<unsigned>(set_basic_status)
            << std::dec << " fixture=" << context.metadata_store->IsFixtureCompatibilityPathActive()
            << " actual=" << info.LastWriteTime << " expected=" << requested_timestamp << '\n';
        CB_Close(&fs, open_context);
        return false;
    }

    CB_Close(&fs, open_context);
    if (!Require(
        context.test_native_commit_attempt_count == 0 &&
            context.close_commit_deferred.load(std::memory_order_acquire) &&
            context.pending_native_writes &&
            context.native_write_enabled,
        "New file create-write-metadata close should defer native commit"))
    {
        return false;
    }

    PVOID reopen_ctx = nullptr;
    FSP_FSCTL_FILE_INFO reopen_info{};
    const auto reopen_status = CB_Open(
        &fs,
        const_cast<PWSTR>(L"\\fresh.bin"),
        FILE_NON_DIRECTORY_FILE,
        FILE_READ_DATA | FILE_WRITE_DATA,
        &reopen_ctx,
        &reopen_info);
    if (!Require(reopen_status == STATUS_SUCCESS, "Immediate payload-write reopen should hydrate from deferred fresh-file spool without draining") ||
        !Require(reopen_ctx != nullptr, "Immediate payload-write reopen should return an open context"))
    {
        return false;
    }

    auto* reopened = reinterpret_cast<OpenContext*>(reopen_ctx);
    if (!Require(context.test_native_commit_attempt_count == 0, "Immediate payload-write reopen should not force a native commit") ||
        !Require(context.close_commit_deferred.load(std::memory_order_acquire), "Immediate payload-write reopen should keep deferred close state pending") ||
        !Require(context.pending_native_writes, "Immediate payload-write reopen should keep native dirty state pending") ||
        !Require(reopened->file != INVALID_HANDLE_VALUE, "Immediate payload-write reopen should materialize a writable hydration handle") ||
        !Require(!reopened->metadata_read_fallback, "Immediate payload-write reopen should not use read-only metadata fallback"))
    {
        CB_Close(&fs, reopen_ctx);
        return false;
    }

    std::array<std::byte, 4> read_buffer{};
    ULONG read_done = 0;
    const auto read_status = CB_Read(
        &fs,
        reopened,
        read_buffer.data(),
        0,
        static_cast<ULONG>(read_buffer.size()),
        &read_done);
    const std::array<std::byte, 4> reopened_payload{
        std::byte{'O'},
        std::byte{'P'},
        std::byte{'E'},
        std::byte{'N'},
    };
    ULONG reopened_write_done = 0;
    const auto reopened_write_status = CB_Write(
        &fs,
        reopened,
        const_cast<std::byte*>(reopened_payload.data()),
        0,
        static_cast<ULONG>(reopened_payload.size()),
        FALSE,
        FALSE,
        &reopened_write_done,
        &reopen_info);
    CB_Close(&fs, reopen_ctx);

    if (!Require(read_status == STATUS_SUCCESS, "Immediate payload-write reopen should read staged payload") ||
        !Require(read_done == read_buffer.size(), "Immediate payload-write reopen should report full payload") ||
        !Require(std::equal(payload.begin(), payload.end(), read_buffer.begin()), "Immediate payload-write reopen should preserve deferred payload bytes") ||
        !Require(reopened_write_status == STATUS_SUCCESS, "Immediate payload-write reopen should accept a follow-up write") ||
        !Require(reopened_write_done == reopened_payload.size(), "Immediate payload-write reopen should report full follow-up write") ||
        !Require(context.test_native_commit_attempt_count == 0, "Immediate payload-write close should keep native commit attempts at zero") ||
        !Require(context.close_commit_deferred.load(std::memory_order_acquire), "Immediate payload-write close should keep the deferred batch active") ||
        !Require(context.pending_native_writes, "Immediate payload-write close should leave native dirty state pending"))
    {
        return false;
    }

    OpenContext flush_context{};
    flush_context.node = context.nodes.at(Key(L"\\"));
    FSP_FSCTL_FILE_INFO flush_info{};
    const auto flush_status = CB_Flush(&fs, &flush_context, &flush_info);
    if (!Require(flush_status == STATUS_SUCCESS, "Immediate payload-write flush should commit the deferred reopen batch") ||
        !Require(context.test_native_commit_attempt_count == 1, "Immediate payload-write flush should commit once") ||
        !Require(!context.close_commit_deferred.load(std::memory_order_acquire), "Immediate payload-write flush should clear deferred close state") ||
        !Require(!context.pending_native_writes, "Immediate payload-write flush should clear native dirty state"))
    {
        return false;
    }

    PVOID rewrite_ctx = nullptr;
    FSP_FSCTL_FILE_INFO rewrite_info{};
    const auto rewrite_open_status = CB_Open(
        &fs,
        const_cast<PWSTR>(L"\\fresh.bin"),
        FILE_NON_DIRECTORY_FILE,
        FILE_READ_DATA | FILE_WRITE_DATA,
        &rewrite_ctx,
        &rewrite_info);
    if (!Require(rewrite_open_status == STATUS_SUCCESS, "Immediate rewrite fixture should reopen committed file") ||
        !Require(rewrite_ctx != nullptr, "Immediate rewrite fixture should return write context"))
    {
        return false;
    }

    const std::array<std::byte, 4> second_payload{
        std::byte{'A'},
        std::byte{'G'},
        std::byte{'A'},
        std::byte{'N'},
    };
    ULONG rewrite_done = 0;
    auto* rewrite_open = reinterpret_cast<OpenContext*>(rewrite_ctx);
    const auto rewrite_status = CB_Write(
        &fs,
        rewrite_open,
        const_cast<std::byte*>(second_payload.data()),
        0,
        static_cast<ULONG>(second_payload.size()),
        FALSE,
        FALSE,
        &rewrite_done,
        &rewrite_info);
    CB_Close(&fs, rewrite_ctx);
    if (!Require(rewrite_status == STATUS_SUCCESS, "Immediate rewrite fixture should write second payload") ||
        !Require(rewrite_done == second_payload.size(), "Immediate rewrite fixture should report full second payload") ||
        !Require(context.close_commit_deferred.load(std::memory_order_acquire), "Immediate rewrite fixture should leave second close deferred") ||
        !Require(context.pending_native_writes, "Immediate rewrite fixture should keep second native dirty state"))
    {
        return false;
    }

    PVOID metadata_reopen_ctx = nullptr;
    FSP_FSCTL_FILE_INFO metadata_reopen_info{};
    const auto metadata_reopen_status = CB_Open(
        &fs,
        const_cast<PWSTR>(L"\\fresh.bin"),
        FILE_NON_DIRECTORY_FILE,
        FILE_WRITE_ATTRIBUTES,
        &metadata_reopen_ctx,
        &metadata_reopen_info);
    if (!Require(metadata_reopen_status == STATUS_SUCCESS, "Immediate metadata-write reopen should not require deferred fresh-file commit") ||
        !Require(metadata_reopen_ctx != nullptr, "Immediate metadata-write reopen should return an open context") ||
        !Require(context.close_commit_deferred.load(std::memory_order_acquire), "Immediate metadata-write reopen should leave deferred close state pending") ||
        !Require(context.pending_native_writes, "Immediate metadata-write reopen should leave native dirty state pending"))
    {
        if (metadata_reopen_ctx)
        {
            CB_Close(&fs, metadata_reopen_ctx);
        }
        return false;
    }
    CB_Close(&fs, metadata_reopen_ctx);
    return true;
#else
    return true;
#endif
}

bool TestDeferredCloseAllowsDirectoryCreateBatch()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", L"1");
    SetEnvironmentVariableW(L"APFSACCESS_EXPERIMENTAL_NAMESPACE_WRITEBACK", L"1");
    ScopeExit clear_writeback_env{[]()
    {
        SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_EXPERIMENTAL_NAMESPACE_WRITEBACK", nullptr);
    }};

    MountContext context{};
    context.args.volume = L"Main";
    context.args.readwrite = true;
    context.args.write_backend = L"Native";
    context.args.write_require_canonical_commit = false;
    context.args.write_disallow_scaffold_commit_on_non_fixture = false;
    context.args.write_reject_scaffold_replay_blob_on_non_fixture = false;
    context.args.write_require_canonical_replay_candidate_on_non_fixture = false;
    context.native_write_enabled = true;
    context.overlay_write_enabled = false;
    SeedRoot(context);
    std::array<std::byte, 16> security{};
    SeedSecurity(context, security);
    if (!Require(PrepareUnitHydrationRoot(context, L"deferred-close-directory-create"), "Deferred directory create test should prepare cache root") ||
        !Require(ConfigureUnitRecoveryMarker(context, L"deferred-close-directory-create"), "Deferred directory create test should configure recovery marker"))
    {
        return false;
    }

    std::error_code ec;
    ScopeExit cleanup{[&]()
    {
        StopDeferredCommitWorker(&context);
        std::filesystem::remove(context.recovery_marker_file, ec);
        std::filesystem::remove_all(context.session_root, ec);
    }};

    const auto image_path = context.session_root / "deferred-directory-create.apfs.img";
    if (!Require(CreateSyntheticApfsContainerForTest(image_path), "Deferred directory create test should create synthetic APFS image"))
    {
        return false;
    }
    context.args.device = image_path.wstring();

    apfsaccess::rw::MetadataStore::VolumeContext rw_context
    {
        image_path.wstring(),
        L"Main",
    };
    rw_context.allow_legacy_scaffold_for_fixtures = true;
    rw_context.disallow_scaffold_commit_on_non_fixture = false;
    rw_context.reject_scaffold_replay_blob_on_non_fixture = false;
    rw_context.require_canonical_replay_candidate_on_non_fixture = false;
    context.owned_metadata_store = std::make_unique<apfsaccess::rw::MetadataStore>(std::move(rw_context));
    context.metadata_store = context.owned_metadata_store.get();
    {
        std::lock_guard<std::mutex> metadata_lock(context.metadata_mutex);
        if (!Require(context.metadata_store->LoadContainerSuperblocks(), "Deferred directory create test should load container superblocks") ||
            !Require(context.metadata_store->LoadObjectMap(), "Deferred directory create test should load object map") ||
            !Require(context.metadata_store->LoadSpacemanState(), "Deferred directory create test should load spaceman state") ||
            !Require(context.metadata_store->PrepareNativeWritePath(), "Deferred directory create test should prepare native write path"))
        {
            return false;
        }
    }

    context.tx_manager = std::make_unique<apfsaccess::rw::TransactionManager>(L"Conservative");
    context.tx_manager->SetVolumeIdentity(L"unit-deferred-directory-create");
    context.tx_manager->SetJournalPath((context.session_root / "directory-create.wal").wstring());

    auto fs = BuildFileSystem(&context);
    PVOID out_ctx = nullptr;
    FSP_FSCTL_FILE_INFO info{};
    const auto create_status = CB_Create(
        &fs,
        const_cast<PWSTR>(L"\\batch-dir"),
        FILE_DIRECTORY_FILE,
        FILE_WRITE_ATTRIBUTES,
        0,
        nullptr,
        0,
        &out_ctx,
        &info);
    if (!Require(create_status == STATUS_SUCCESS, "Deferred directory create test should create directory") ||
        !Require(out_ctx != nullptr, "Deferred directory create test should return open context"))
    {
        return false;
    }

    CB_Close(&fs, out_ctx);
    if (!Require(
        context.test_native_commit_attempt_count == 0 &&
            context.close_commit_deferred.load(std::memory_order_acquire) &&
            context.pending_native_writes &&
            context.native_write_enabled,
        "Directory create close should defer native commit"))
    {
        return false;
    }

    const auto drain_status = DrainNativeMutationsByPolicy(&context, L"Shutdown");
    if (!Require(NT_SUCCESS(drain_status), "Deferred directory create should drain successfully at shutdown boundary"))
    {
        AbortMutationJournalBestEffort(&context, L"Shutdown");
        return false;
    }
    FinalizeMutationJournalBestEffort(&context, L"Shutdown");
    return Require(!context.pending_native_writes, "Deferred directory create drain should clear native dirty state");
#else
    return true;
#endif
}

bool TestReadOnlyReopenSeesDeferredSpoolWriteOnReadWriteMount()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
    SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", L"1");
    ScopeExit clear_writeback_env{[]()
    {
        SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", nullptr);
    }};

    MountContext context{};
    context.args.volume = L"Main";
    context.args.readwrite = true;
    context.args.write_backend = L"Native";
    context.args.write_require_canonical_commit = false;
    context.args.write_disallow_scaffold_commit_on_non_fixture = false;
    context.args.write_reject_scaffold_replay_blob_on_non_fixture = false;
    context.args.write_require_canonical_replay_candidate_on_non_fixture = false;
    context.native_write_enabled = true;
    context.overlay_write_enabled = false;
    SeedRoot(context);
    std::array<std::byte, 16> security{};
    SeedSecurity(context, security);
    if (!Require(PrepareUnitHydrationRoot(context, L"deferred-spool-readonly-reopen"), "Deferred spool read reopen test should prepare cache root") ||
        !Require(ConfigureUnitRecoveryMarker(context, L"deferred-spool-readonly-reopen"), "Deferred spool read reopen test should configure recovery marker"))
    {
        return false;
    }

    std::error_code ec;
    ScopeExit cleanup{[&]()
    {
        StopDeferredCommitWorker(&context);
        std::filesystem::remove(context.recovery_marker_file, ec);
        std::filesystem::remove_all(context.session_root, ec);
    }};

    const auto image_path = context.session_root / "deferred-spool-readonly-reopen.apfs.img";
    if (!Require(CreateSyntheticApfsContainerForTest(image_path), "Deferred spool read reopen test should create synthetic APFS image"))
    {
        return false;
    }
    context.args.device = image_path.wstring();

    apfsaccess::rw::MetadataStore::VolumeContext rw_context
    {
        image_path.wstring(),
        L"Main",
    };
    rw_context.allow_legacy_scaffold_for_fixtures = true;
    rw_context.disallow_scaffold_commit_on_non_fixture = false;
    rw_context.reject_scaffold_replay_blob_on_non_fixture = false;
    rw_context.require_canonical_replay_candidate_on_non_fixture = false;
    context.owned_metadata_store = std::make_unique<apfsaccess::rw::MetadataStore>(std::move(rw_context));
    context.metadata_store = context.owned_metadata_store.get();
    context.metadata_store->SetFilePayloadRangeProvider(
        [&context](
            const std::wstring& path,
            apfsaccess::rw::MetadataStore::PayloadIdentity identity,
            std::uint64_t offset,
            std::span<std::byte> destination) -> bool
        {
            return ReadHydratedPayloadRangeForPath(&context, path, identity, offset, destination);
        });
    {
        std::lock_guard<std::mutex> metadata_lock(context.metadata_mutex);
        if (!Require(context.metadata_store->LoadContainerSuperblocks(), "Deferred spool read reopen test should load container superblocks") ||
            !Require(context.metadata_store->LoadObjectMap(), "Deferred spool read reopen test should load object map") ||
            !Require(context.metadata_store->LoadSpacemanState(), "Deferred spool read reopen test should load spaceman state") ||
            !Require(context.metadata_store->PrepareNativeWritePath(), "Deferred spool read reopen test should prepare native write path"))
        {
            return false;
        }
    }

    context.payload_spool_volume_identity = "unit-deferred-spool-readonly-reopen";
    context.payload_spool = std::make_unique<apfsaccess::rw::PayloadSpool>(
        apfsaccess::rw::PayloadSpool::Options{
            context.session_root / "payload-spool",
            context.payload_spool_volume_identity,
            8 * 1024 * 1024,
        });
    context.tx_manager = std::make_unique<apfsaccess::rw::TransactionManager>(L"Conservative");
    context.tx_manager->SetVolumeIdentity(L"unit-deferred-spool-readonly-reopen");
    context.tx_manager->SetJournalPath((context.session_root / "deferred-spool-readonly-reopen.wal").wstring());

    auto fs = BuildFileSystem(&context);
    PVOID create_ctx = nullptr;
    FSP_FSCTL_FILE_INFO create_info{};
    const auto empty_create_status = CB_Create(
        &fs,
        const_cast<PWSTR>(L"\\hash-me.txt"),
        FILE_NON_DIRECTORY_FILE,
        FILE_WRITE_DATA | FILE_READ_DATA | FILE_WRITE_ATTRIBUTES,
        0,
        nullptr,
        0,
        &create_ctx,
        &create_info);
    if (!Require(empty_create_status == STATUS_SUCCESS, "Deferred spool read reopen test should create empty committed file") ||
        !Require(create_ctx != nullptr, "Deferred spool read reopen test should return empty create context"))
    {
        return false;
    }
    CB_Close(&fs, create_ctx);
    if (!Require(!context.pending_native_writes, "Deferred spool read reopen test should commit empty create before content write"))
    {
        return false;
    }

    PVOID write_ctx = nullptr;
    FSP_FSCTL_FILE_INFO info{};
    const auto open_for_write_status = CB_Open(
        &fs,
        const_cast<PWSTR>(L"\\hash-me.txt"),
        FILE_NON_DIRECTORY_FILE,
        FILE_WRITE_DATA | FILE_READ_DATA | FILE_WRITE_ATTRIBUTES,
        &write_ctx,
        &info);
    if (!Require(open_for_write_status == STATUS_SUCCESS, "Deferred spool read reopen test should reopen committed empty file for write") ||
        !Require(write_ctx != nullptr, "Deferred spool read reopen test should return write context"))
    {
        return false;
    }

    const auto payload = BuildPatternPayloadForTest(58, 0x31);
    ULONG write_done = 0;
    auto* write_open = reinterpret_cast<OpenContext*>(write_ctx);
    const auto write_status = CB_Write(
        &fs,
        write_open,
        const_cast<std::byte*>(payload.data()),
        0,
        static_cast<ULONG>(payload.size()),
        FALSE,
        FALSE,
        &write_done,
        &info);
    if (!Require(write_status == STATUS_SUCCESS, "Deferred spool read reopen test should write payload") ||
        !Require(write_done == payload.size(), "Deferred spool read reopen test should report full write"))
    {
        CB_Close(&fs, write_ctx);
        return false;
    }

    CB_Close(&fs, write_ctx);
    if (!Require(context.close_commit_deferred.load(std::memory_order_acquire), "Deferred spool read reopen test should leave close commit deferred") ||
        !Require(context.pending_native_writes, "Deferred spool read reopen test should keep native writes pending") ||
        !Require(
            PayloadSpoolLogicalEndBestEffort(&context, L"\\hash-me.txt") == payload.size(),
            "Deferred spool read reopen test should expose staged payload logical tail"))
    {
        return false;
    }

    PVOID read_ctx = nullptr;
    FSP_FSCTL_FILE_INFO read_info{};
    const auto open_status = CB_Open(
        &fs,
        const_cast<PWSTR>(L"\\hash-me.txt"),
        FILE_NON_DIRECTORY_FILE,
        FILE_READ_DATA,
        &read_ctx,
        &read_info);
    if (!Require(open_status == STATUS_SUCCESS, "Read-only reopen should succeed while deferred spool bytes are pending") ||
        !Require(read_ctx != nullptr, "Read-only reopen should return a read context"))
    {
        return false;
    }

    std::vector<std::byte> read_buffer(payload.size(), std::byte{0});
    ULONG read_done = 0;
    const auto read_status = CB_Read(
        &fs,
        read_ctx,
        read_buffer.data(),
        0,
        static_cast<ULONG>(read_buffer.size()),
        &read_done);
    CB_Close(&fs, read_ctx);

    if (!Require(read_status == STATUS_SUCCESS, "Read-only reopen should read deferred spool bytes") ||
        !Require(read_done == read_buffer.size(), "Read-only reopen should report full payload") ||
        !Require(read_buffer == payload, "Read-only reopen should preserve staged payload bytes"))
    {
        return false;
    }

    PVOID move_source_ctx = nullptr;
    FSP_FSCTL_FILE_INFO move_source_info{};
    const auto move_source_open_status = CB_Open(
        &fs,
        const_cast<PWSTR>(L"\\hash-me.txt"),
        FILE_NON_DIRECTORY_FILE,
        FILE_READ_DATA | DELETE,
        &move_source_ctx,
        &move_source_info);
    if (!Require(move_source_open_status == STATUS_SUCCESS, "Read-delete move source reopen should succeed while deferred spool bytes are pending") ||
        !Require(move_source_ctx != nullptr, "Read-delete move source reopen should return a context"))
    {
        return false;
    }

    std::vector<std::byte> move_source_buffer(payload.size(), std::byte{0});
    ULONG move_source_done = 0;
    const auto move_source_read_status = CB_Read(
        &fs,
        move_source_ctx,
        move_source_buffer.data(),
        0,
        static_cast<ULONG>(move_source_buffer.size()),
        &move_source_done);
    CB_Cleanup(
        &fs,
        move_source_ctx,
        const_cast<PWSTR>(L"\\hash-me.txt"),
        FspCleanupDelete);
    CB_Close(&fs, move_source_ctx);

    return Require(move_source_read_status == STATUS_SUCCESS, "Read-delete move source reopen should read deferred spool bytes") &&
           Require(move_source_done == move_source_buffer.size(), "Read-delete move source reopen should report full payload") &&
           Require(move_source_buffer == payload, "Read-delete move source reopen should preserve staged payload bytes");
#else
    return true;
#endif
}

bool TestFreshDeferredSpoolMoveOutSourceReadsPayload()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
    SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", L"1");
    ScopeExit clear_writeback_env{[]()
    {
        SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", nullptr);
    }};

    MountContext context{};
    context.args.volume = L"Main";
    context.args.readwrite = true;
    context.args.write_backend = L"Native";
    context.args.write_require_canonical_commit = false;
    context.args.write_disallow_scaffold_commit_on_non_fixture = false;
    context.args.write_reject_scaffold_replay_blob_on_non_fixture = false;
    context.args.write_require_canonical_replay_candidate_on_non_fixture = false;
    context.native_write_enabled = true;
    context.overlay_write_enabled = false;
    SeedRoot(context);
    std::array<std::byte, 16> security{};
    SeedSecurity(context, security);
    if (!Require(PrepareUnitHydrationRoot(context, L"fresh-deferred-spool-move-out"), "Fresh deferred move-out test should prepare cache root") ||
        !Require(ConfigureUnitRecoveryMarker(context, L"fresh-deferred-spool-move-out"), "Fresh deferred move-out test should configure recovery marker"))
    {
        return false;
    }

    std::error_code ec;
    ScopeExit cleanup{[&]()
    {
        StopDeferredCommitWorker(&context);
        std::filesystem::remove(context.recovery_marker_file, ec);
        std::filesystem::remove_all(context.session_root, ec);
    }};

    const auto image_path = context.session_root / "fresh-deferred-spool-move-out.apfs.img";
    if (!Require(CreateSyntheticApfsContainerForTest(image_path, 4096), "Fresh deferred move-out test should create synthetic APFS image"))
    {
        return false;
    }
    context.args.device = image_path.wstring();

    apfsaccess::rw::MetadataStore::VolumeContext rw_context
    {
        image_path.wstring(),
        L"Main",
    };
    rw_context.allow_legacy_scaffold_for_fixtures = true;
    rw_context.disallow_scaffold_commit_on_non_fixture = false;
    rw_context.reject_scaffold_replay_blob_on_non_fixture = false;
    rw_context.require_canonical_replay_candidate_on_non_fixture = false;
    context.owned_metadata_store = std::make_unique<apfsaccess::rw::MetadataStore>(std::move(rw_context));
    context.metadata_store = context.owned_metadata_store.get();
    context.metadata_store->SetFilePayloadRangeProvider(
        [&context](
            const std::wstring& path,
            apfsaccess::rw::MetadataStore::PayloadIdentity identity,
            std::uint64_t offset,
            std::span<std::byte> destination) -> bool
        {
            return ReadHydratedPayloadRangeForPath(&context, path, identity, offset, destination);
        });
    {
        std::lock_guard<std::mutex> metadata_lock(context.metadata_mutex);
        if (!Require(context.metadata_store->LoadContainerSuperblocks(), "Fresh deferred move-out test should load container superblocks") ||
            !Require(context.metadata_store->LoadObjectMap(), "Fresh deferred move-out test should load object map") ||
            !Require(context.metadata_store->LoadSpacemanState(), "Fresh deferred move-out test should load spaceman state") ||
            !Require(context.metadata_store->PrepareNativeWritePath(), "Fresh deferred move-out test should prepare native write path"))
        {
            return false;
        }
    }

    context.payload_spool_volume_identity = "unit-fresh-deferred-spool-move-out";
    context.payload_spool = std::make_unique<apfsaccess::rw::PayloadSpool>(
        apfsaccess::rw::PayloadSpool::Options{
            context.session_root / "payload-spool",
            context.payload_spool_volume_identity,
            8 * 1024 * 1024,
        });
    context.tx_manager = std::make_unique<apfsaccess::rw::TransactionManager>(L"Conservative");
    context.tx_manager->SetVolumeIdentity(L"unit-fresh-deferred-spool-move-out");
    context.tx_manager->SetJournalPath((context.session_root / "fresh-deferred-spool-move-out.wal").wstring());

    auto fs = BuildFileSystem(&context);
    PVOID dir_ctx = nullptr;
    FSP_FSCTL_FILE_INFO dir_info{};
    const auto dir_status = CB_Create(
        &fs,
        const_cast<PWSTR>(L"\\move-source"),
        FILE_DIRECTORY_FILE,
        FILE_WRITE_DATA | FILE_WRITE_ATTRIBUTES,
        0,
        nullptr,
        0,
        &dir_ctx,
        &dir_info);
    if (dir_ctx)
    {
        CB_Close(&fs, dir_ctx);
    }
    if (!Require(dir_status == STATUS_SUCCESS, "Fresh deferred move-out test should create source directory"))
    {
        return false;
    }

    const auto directory_commit_status = DrainNativeMutationsByPolicy(&context, L"Flush");
    if (!Require(directory_commit_status == STATUS_SUCCESS, "Fresh deferred move-out test should commit source directory"))
    {
        return false;
    }
    FinalizeMutationJournalBestEffort(&context, L"Flush");

    PVOID write_ctx = nullptr;
    FSP_FSCTL_FILE_INFO info{};
    const auto create_status = CB_Create(
        &fs,
        const_cast<PWSTR>(L"\\move-source\\cut-from-ntfs.bin"),
        FILE_NON_DIRECTORY_FILE,
        FILE_READ_DATA | FILE_WRITE_DATA | FILE_WRITE_ATTRIBUTES,
        0,
        nullptr,
        0,
        &write_ctx,
        &info);
    if (!Require(create_status == STATUS_SUCCESS, "Fresh deferred move-out test should create moved-in file") ||
        !Require(write_ctx != nullptr, "Fresh deferred move-out test should return write context"))
    {
        return false;
    }

    const auto payload = BuildPatternPayloadForTest(2 * 1024 * 1024, 121);
    auto* write_open = reinterpret_cast<OpenContext*>(write_ctx);
    std::size_t written_total = 0;
    while (written_total < payload.size())
    {
        const auto chunk = std::min<std::size_t>(1024 * 1024, payload.size() - written_total);
        ULONG write_done = 0;
        const auto write_status = CB_Write(
            &fs,
            write_open,
            const_cast<std::byte*>(payload.data() + static_cast<std::ptrdiff_t>(written_total)),
            static_cast<UINT64>(written_total),
            static_cast<ULONG>(chunk),
            FALSE,
            FALSE,
            &write_done,
            &info);
        if (!Require(write_status == STATUS_SUCCESS, "Fresh deferred move-out test should write payload chunk") ||
            !Require(write_done == chunk, "Fresh deferred move-out test should report full chunk write"))
        {
            CB_Close(&fs, write_ctx);
            return false;
        }
        written_total += write_done;
    }
    CB_Close(&fs, write_ctx);

    if (!Require(context.close_commit_deferred.load(std::memory_order_acquire), "Fresh deferred move-out test should leave close commit deferred") ||
        !Require(context.pending_native_writes, "Fresh deferred move-out test should keep native writes pending") ||
        !Require(PayloadSpoolLogicalEndBestEffort(&context, L"\\move-source\\cut-from-ntfs.bin") == payload.size(),
                 "Fresh deferred move-out test should expose staged payload logical tail"))
    {
        return false;
    }

    PVOID move_source_ctx = nullptr;
    FSP_FSCTL_FILE_INFO move_source_info{};
    const auto move_source_open_status = CB_Open(
        &fs,
        const_cast<PWSTR>(L"\\move-source\\cut-from-ntfs.bin"),
        FILE_NON_DIRECTORY_FILE,
        GENERIC_READ | GENERIC_WRITE | DELETE,
        &move_source_ctx,
        &move_source_info);
    if (!Require(move_source_open_status == STATUS_SUCCESS, "Fresh deferred move-out source open should succeed") ||
        !Require(move_source_ctx != nullptr, "Fresh deferred move-out source open should return a context"))
    {
        return false;
    }

    std::vector<std::byte> read_buffer(payload.size(), std::byte{0});
    ULONG read_done = 0;
    const auto read_status = CB_Read(
        &fs,
        move_source_ctx,
        read_buffer.data(),
        0,
        static_cast<ULONG>(read_buffer.size()),
        &read_done);

    if (!Require(read_status == STATUS_SUCCESS, "Fresh deferred move-out source should read deferred spool bytes") ||
        !Require(read_done == read_buffer.size(), "Fresh deferred move-out source should report full payload") ||
        !Require(read_buffer == payload, "Fresh deferred move-out source should preserve staged payload bytes"))
    {
        CB_Close(&fs, move_source_ctx);
        return false;
    }

    PVOID win32_move_source_ctx = nullptr;
    FSP_FSCTL_FILE_INFO win32_move_source_info{};
    const UINT32 win32_move_source_access =
        FILE_READ_DATA |
        FILE_WRITE_DATA |
        FILE_APPEND_DATA |
        FILE_READ_EA |
        FILE_WRITE_EA |
        FILE_READ_ATTRIBUTES |
        FILE_WRITE_ATTRIBUTES |
        READ_CONTROL |
        SYNCHRONIZE;
    const auto commit_attempts_before_win32_open = context.test_native_commit_attempt_count;
    const auto win32_move_source_open_status = CB_Open(
        &fs,
        const_cast<PWSTR>(L"\\move-source\\cut-from-ntfs.bin"),
        FILE_NON_DIRECTORY_FILE | FILE_SEQUENTIAL_ONLY,
        win32_move_source_access,
        &win32_move_source_ctx,
        &win32_move_source_info);
    if (!Require(win32_move_source_open_status == STATUS_SUCCESS, "Fresh deferred Win32 move source open should succeed without delete access") ||
        !Require(win32_move_source_ctx != nullptr, "Fresh deferred Win32 move source open should return a context"))
    {
        return false;
    }

    auto* win32_move_source_open = reinterpret_cast<OpenContext*>(win32_move_source_ctx);
    if (!Require(win32_move_source_open->metadata_read_fallback, "Fresh deferred Win32 move source open should use metadata/spool fallback") ||
        !Require(win32_move_source_open->file == INVALID_HANDLE_VALUE, "Fresh deferred Win32 move source open should not require hydration handle"))
    {
        CB_Close(&fs, win32_move_source_ctx);
        return false;
    }

    std::vector<std::byte> win32_move_source_buffer(payload.size(), std::byte{0});
    ULONG win32_move_source_done = 0;
    const auto win32_move_source_read_status = CB_Read(
        &fs,
        win32_move_source_ctx,
        win32_move_source_buffer.data(),
        0,
        static_cast<ULONG>(win32_move_source_buffer.size()),
        &win32_move_source_done);

    const auto commit_attempts_before_write = context.test_native_commit_attempt_count;
    ULONG lazy_write_done = 0;
    auto lazy_write_byte = std::byte{0x7f};
    const auto lazy_write_status = CB_Write(
        &fs,
        win32_move_source_ctx,
        &lazy_write_byte,
        0,
        1,
        FALSE,
        FALSE,
        &lazy_write_done,
        &win32_move_source_info);
    const bool lazy_handle_upgraded =
        win32_move_source_open->file != INVALID_HANDLE_VALUE &&
        !win32_move_source_open->metadata_read_fallback;
    std::byte lazy_read_byte{};
    ULONG lazy_read_done = 0;
    const auto lazy_read_status = CB_Read(
        &fs,
        win32_move_source_ctx,
        &lazy_read_byte,
        0,
        1,
        &lazy_read_done);
    const auto commit_attempts_after_write = context.test_native_commit_attempt_count;
    CB_Close(&fs, win32_move_source_ctx);
    CB_Cleanup(
        &fs,
        move_source_ctx,
        const_cast<PWSTR>(L"\\move-source\\cut-from-ntfs.bin"),
        FspCleanupDelete);
    CB_Close(&fs, move_source_ctx);

    return Require(win32_move_source_read_status == STATUS_SUCCESS, "Fresh deferred Win32 move source should read deferred spool bytes") &&
           Require(win32_move_source_done == win32_move_source_buffer.size(), "Fresh deferred Win32 move source should report full payload") &&
           Require(win32_move_source_buffer == payload, "Fresh deferred Win32 move source should preserve staged payload bytes") &&
           Require(commit_attempts_before_write == commit_attempts_before_win32_open, "Fresh deferred Win32 move source open and read should not drain pending work") &&
           Require(lazy_write_status == STATUS_SUCCESS, "Fresh deferred Win32 move source fallback should lazily accept authorized writes") &&
           Require(lazy_write_done == 1, "Fresh deferred Win32 move source lazy write should report one byte") &&
           Require(lazy_handle_upgraded, "Fresh deferred Win32 move source write should lazily acquire a hydration handle") &&
           Require(lazy_read_status == STATUS_SUCCESS && lazy_read_done == 1 && lazy_read_byte == lazy_write_byte,
                   "Fresh deferred Win32 move source lazy write should overlay the staged payload bytes") &&
           Require(commit_attempts_after_write == commit_attempts_before_write, "Fresh deferred Win32 move source lazy write should remain deferred before close");
#else
    return true;
#endif
}

bool TestMetadataOnlyReopenAfterDeferredSpoolWriteDoesNotHydrate()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
    SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", L"1");
    ScopeExit clear_writeback_env{[]()
    {
        SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", nullptr);
    }};

    MountContext context{};
    context.args.volume = L"Main";
    context.args.readwrite = true;
    context.args.write_backend = L"Native";
    context.args.write_require_canonical_commit = false;
    context.args.write_disallow_scaffold_commit_on_non_fixture = false;
    context.args.write_reject_scaffold_replay_blob_on_non_fixture = false;
    context.args.write_require_canonical_replay_candidate_on_non_fixture = false;
    context.native_write_enabled = true;
    context.overlay_write_enabled = false;
    SeedRoot(context);
    std::array<std::byte, 16> security{};
    SeedSecurity(context, security);
    if (!Require(PrepareUnitHydrationRoot(context, L"metadata-only-spool-reopen"), "Metadata-only spool reopen test should prepare cache root") ||
        !Require(ConfigureUnitRecoveryMarker(context, L"metadata-only-spool-reopen"), "Metadata-only spool reopen test should configure recovery marker"))
    {
        return false;
    }

    std::error_code ec;
    ScopeExit cleanup{[&]()
    {
        StopDeferredCommitWorker(&context);
        std::filesystem::remove(context.recovery_marker_file, ec);
        std::filesystem::remove_all(context.session_root, ec);
    }};

    const auto image_path = context.session_root / "metadata-only-spool-reopen.apfs.img";
    if (!Require(CreateSyntheticApfsContainerForTest(image_path), "Metadata-only spool reopen test should create synthetic APFS image"))
    {
        return false;
    }
    context.args.device = image_path.wstring();

    apfsaccess::rw::MetadataStore::VolumeContext rw_context
    {
        image_path.wstring(),
        L"Main",
    };
    rw_context.allow_legacy_scaffold_for_fixtures = true;
    rw_context.disallow_scaffold_commit_on_non_fixture = false;
    rw_context.reject_scaffold_replay_blob_on_non_fixture = false;
    rw_context.require_canonical_replay_candidate_on_non_fixture = false;
    context.owned_metadata_store = std::make_unique<apfsaccess::rw::MetadataStore>(std::move(rw_context));
    context.metadata_store = context.owned_metadata_store.get();
    context.metadata_store->SetFilePayloadRangeProvider(
        [&context](
            const std::wstring& path,
            apfsaccess::rw::MetadataStore::PayloadIdentity identity,
            std::uint64_t offset,
            std::span<std::byte> destination) -> bool
        {
            return ReadHydratedPayloadRangeForPath(&context, path, identity, offset, destination);
        });
    {
        std::lock_guard<std::mutex> metadata_lock(context.metadata_mutex);
        if (!Require(context.metadata_store->LoadContainerSuperblocks(), "Metadata-only spool reopen test should load container superblocks") ||
            !Require(context.metadata_store->LoadObjectMap(), "Metadata-only spool reopen test should load object map") ||
            !Require(context.metadata_store->LoadSpacemanState(), "Metadata-only spool reopen test should load spaceman state") ||
            !Require(context.metadata_store->PrepareNativeWritePath(), "Metadata-only spool reopen test should prepare native write path"))
        {
            return false;
        }
    }

    context.payload_spool_volume_identity = "unit-metadata-only-spool-reopen";
    context.payload_spool = std::make_unique<apfsaccess::rw::PayloadSpool>(
        apfsaccess::rw::PayloadSpool::Options{
            context.session_root / "payload-spool",
            context.payload_spool_volume_identity,
            1024 * 1024,
        });
    context.tx_manager = std::make_unique<apfsaccess::rw::TransactionManager>(L"Conservative");
    context.tx_manager->SetVolumeIdentity(L"unit-metadata-only-spool-reopen");
    context.tx_manager->SetJournalPath((context.session_root / "metadata-only-spool-reopen.wal").wstring());

    auto fs = BuildFileSystem(&context);
    PVOID write_ctx = nullptr;
    FSP_FSCTL_FILE_INFO info{};
    const auto create_status = CB_Create(
        &fs,
        const_cast<PWSTR>(L"\\image (2).png"),
        FILE_NON_DIRECTORY_FILE,
        FILE_WRITE_DATA | FILE_READ_DATA | FILE_WRITE_ATTRIBUTES,
        0,
        nullptr,
        0,
        &write_ctx,
        &info);
    if (!Require(create_status == STATUS_SUCCESS, "Metadata-only spool reopen test should create PNG-like file") ||
        !Require(write_ctx != nullptr, "Metadata-only spool reopen test should return write context"))
    {
        return false;
    }

    const auto payload = BuildPatternPayloadForTest(124378, 0x42);
    ULONG write_done = 0;
    auto* write_open = reinterpret_cast<OpenContext*>(write_ctx);
    const auto write_status = CB_Write(
        &fs,
        write_open,
        const_cast<std::byte*>(payload.data()),
        0,
        static_cast<ULONG>(payload.size()),
        FALSE,
        FALSE,
        &write_done,
        &info);
    if (!Require(write_status == STATUS_SUCCESS, "Metadata-only spool reopen test should write payload") ||
        !Require(write_done == payload.size(), "Metadata-only spool reopen test should report full write"))
    {
        CB_Close(&fs, write_ctx);
        return false;
    }

    PVOID metadata_ctx = nullptr;
    FSP_FSCTL_FILE_INFO metadata_info{};
    const auto metadata_open_status = CB_Open(
        &fs,
        const_cast<PWSTR>(L"\\image (2).png"),
        FILE_NON_DIRECTORY_FILE,
        FILE_WRITE_ATTRIBUTES,
        &metadata_ctx,
        &metadata_info);
    if (!Require(metadata_open_status == STATUS_SUCCESS, "Metadata-only reopen should not require payload hydration while spool bytes are pending") ||
        !Require(metadata_ctx != nullptr, "Metadata-only reopen should return a context"))
    {
        CB_Close(&fs, write_ctx);
        return false;
    }

    auto* metadata_open = reinterpret_cast<OpenContext*>(metadata_ctx);
    constexpr std::uint64_t requested_timestamp = 116444736000000000ULL + 0x01DABEEF;
    const auto set_basic_status = CB_SetBasicInfo(
        &fs,
        metadata_open,
        INVALID_FILE_ATTRIBUTES,
        0,
        0,
        requested_timestamp,
        0,
        &metadata_info);
    CB_Close(&fs, metadata_ctx);
    CB_Close(&fs, write_ctx);

    return Require(set_basic_status == STATUS_SUCCESS && metadata_info.LastWriteTime == requested_timestamp,
                   "Metadata-only reopen should set exact APFS-representable timestamp") &&
           Require(context.native_write_enabled, "Metadata-only reopen should keep native write enabled") &&
           Require(PayloadSpoolLogicalEndBestEffort(&context, L"\\image (2).png") == payload.size(),
                   "Metadata-only reopen should leave staged payload available");
#else
    return true;
#endif
}

bool TestImmediateRenameAfterDeferredFreshWriteBatchesBeforeFlush()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
    SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", L"1");
    SetEnvironmentVariableW(L"APFSACCESS_EXPERIMENTAL_NAMESPACE_WRITEBACK", L"1");
    ScopeExit clear_writeback_env{[]()
    {
        SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_EXPERIMENTAL_NAMESPACE_WRITEBACK", nullptr);
    }};

    MountContext context{};
    context.args.volume = L"Main";
    context.args.readwrite = true;
    context.args.write_backend = L"Native";
    context.args.write_require_canonical_commit = false;
    context.args.write_disallow_scaffold_commit_on_non_fixture = false;
    context.args.write_reject_scaffold_replay_blob_on_non_fixture = false;
    context.args.write_require_canonical_replay_candidate_on_non_fixture = false;
    context.native_write_enabled = true;
    context.overlay_write_enabled = false;
    SeedRoot(context);
    std::array<std::byte, 16> security{};
    SeedSecurity(context, security);
    if (!Require(PrepareUnitHydrationRoot(context, L"deferred-fresh-rename"), "Deferred fresh rename batch test should prepare cache root") ||
        !Require(ConfigureUnitRecoveryMarker(context, L"deferred-fresh-rename"), "Deferred fresh rename batch test should configure recovery marker"))
    {
        return false;
    }

    std::error_code ec;
    ScopeExit cleanup{[&]()
    {
        StopDeferredCommitWorker(&context);
        std::filesystem::remove(context.recovery_marker_file, ec);
        std::filesystem::remove_all(context.session_root, ec);
    }};

    const auto image_path = context.session_root / "deferred-fresh-rename.apfs.img";
    if (!Require(CreateSyntheticApfsContainerForTest(image_path), "Deferred fresh rename batch test should create synthetic APFS image"))
    {
        return false;
    }
    context.args.device = image_path.wstring();

    apfsaccess::rw::MetadataStore::VolumeContext rw_context
    {
        image_path.wstring(),
        L"Main",
    };
    rw_context.allow_legacy_scaffold_for_fixtures = true;
    rw_context.disallow_scaffold_commit_on_non_fixture = false;
    rw_context.reject_scaffold_replay_blob_on_non_fixture = false;
    rw_context.require_canonical_replay_candidate_on_non_fixture = false;
    context.owned_metadata_store = std::make_unique<apfsaccess::rw::MetadataStore>(std::move(rw_context));
    context.metadata_store = context.owned_metadata_store.get();
    context.metadata_store->SetFilePayloadRangeProvider(
        [&context](
            const std::wstring& path,
            apfsaccess::rw::MetadataStore::PayloadIdentity identity,
            std::uint64_t offset,
            std::span<std::byte> destination) -> bool
        {
            return ReadHydratedPayloadRangeForPath(&context, path, identity, offset, destination);
        });
    {
        std::lock_guard<std::mutex> metadata_lock(context.metadata_mutex);
        if (!Require(context.metadata_store->LoadContainerSuperblocks(), "Deferred fresh rename batch test should load container superblocks") ||
            !Require(context.metadata_store->LoadObjectMap(), "Deferred fresh rename batch test should load object map") ||
            !Require(context.metadata_store->LoadSpacemanState(), "Deferred fresh rename batch test should load spaceman state") ||
            !Require(context.metadata_store->PrepareNativeWritePath(), "Deferred fresh rename batch test should prepare native write path"))
        {
            return false;
        }
    }

    context.payload_spool_volume_identity = "unit-deferred-fresh-rename";
    context.payload_spool = std::make_unique<apfsaccess::rw::PayloadSpool>(
        apfsaccess::rw::PayloadSpool::Options{
            context.session_root / "payload-spool",
            context.payload_spool_volume_identity,
            1024 * 1024,
        });
    context.tx_manager = std::make_unique<apfsaccess::rw::TransactionManager>(L"Conservative");
    context.tx_manager->SetVolumeIdentity(L"unit-deferred-fresh-rename");
    context.tx_manager->SetJournalPath((context.session_root / "deferred-fresh-rename.wal").wstring());

    auto fs = BuildFileSystem(&context);
    PVOID create_ctx = nullptr;
    FSP_FSCTL_FILE_INFO info{};
    const auto create_status = CB_Create(
        &fs,
        const_cast<PWSTR>(L"\\fresh.txt"),
        FILE_NON_DIRECTORY_FILE,
        FILE_WRITE_DATA | FILE_READ_DATA | FILE_WRITE_ATTRIBUTES,
        0,
        nullptr,
        0,
        &create_ctx,
        &info);
    if (!Require(create_status == STATUS_SUCCESS, "Deferred fresh rename batch test should create file") ||
        !Require(create_ctx != nullptr, "Deferred fresh rename batch test should return create context"))
    {
        return false;
    }

    const auto payload = BuildPatternPayloadForTest(63, 0x51);
    ULONG write_done = 0;
    auto* create_open = reinterpret_cast<OpenContext*>(create_ctx);
    const auto write_status = CB_Write(
        &fs,
        create_open,
        const_cast<std::byte*>(payload.data()),
        0,
        static_cast<ULONG>(payload.size()),
        FALSE,
        FALSE,
        &write_done,
        &info);
    if (!Require(write_status == STATUS_SUCCESS, "Deferred fresh rename batch test should write payload") ||
        !Require(write_done == payload.size(), "Deferred fresh rename batch test should report full write"))
    {
        CB_Close(&fs, create_ctx);
        return false;
    }

    CB_Close(&fs, create_ctx);
    if (!Require(context.close_commit_deferred.load(std::memory_order_acquire), "Deferred fresh rename batch test should leave close commit deferred") ||
        !Require(context.pending_native_writes, "Deferred fresh rename batch test should have pending native writes before rename"))
    {
        return false;
    }

    ResetChildNameDebugCountersForTest();
    OpenContext parent_open{};
    parent_open.node = context.nodes[Key(L"\\")];
    parent_open.allow_delete_child = true;
    parent_open.allow_write_data = true;
    parent_open.allow_append_data = true;
    const auto rename_status = CB_Rename(
        &fs,
        &parent_open,
        const_cast<PWSTR>(L"\\fresh.txt"),
        const_cast<PWSTR>(L"\\fresh-renamed.txt"),
        FALSE);
    if (!Require(rename_status == STATUS_SUCCESS, "Immediate rename after deferred fresh write should batch and succeed"))
    {
        return false;
    }

    if (!Require(context.test_native_commit_attempt_count == 0, "Fresh rename should not force a pre-rename native commit") ||
        !Require(DebugExperimentalRenameCommittedSourceProbeCountForTest() == 0, "Fresh rename should skip the committed-source probe when it can join the pending batch") ||
        !Require(context.close_commit_deferred.load(std::memory_order_acquire), "Fresh rename should keep the deferred close batch active") ||
        !Require(context.pending_native_writes, "Fresh rename should leave native writes pending until a barrier"))
    {
        return false;
    }

    OpenContext flush_context{};
    flush_context.node = context.nodes.at(Key(L"\\"));
    FSP_FSCTL_FILE_INFO flush_info{};
    const auto flush_status = CB_Flush(&fs, &flush_context, &flush_info);
    if (!Require(flush_status == STATUS_SUCCESS, "Deferred fresh rename batch should flush successfully") ||
        !Require(context.test_native_commit_attempt_count == 1, "Deferred fresh rename batch should commit once at flush") ||
        !Require(!context.close_commit_deferred.load(std::memory_order_acquire), "Flush should clear deferred fresh rename state") ||
        !Require(!context.pending_native_writes, "Flush should leave no pending native writes"))
    {
        return false;
    }

    PVOID read_ctx = nullptr;
    FSP_FSCTL_FILE_INFO read_info{};
    const auto open_status = CB_Open(
        &fs,
        const_cast<PWSTR>(L"\\fresh-renamed.txt"),
        FILE_NON_DIRECTORY_FILE,
        FILE_READ_DATA,
        &read_ctx,
        &read_info);
    if (!Require(open_status == STATUS_SUCCESS, "Renamed file should reopen for read") ||
        !Require(read_ctx != nullptr, "Renamed file should return read context"))
    {
        return false;
    }

    std::vector<std::byte> read_buffer(payload.size(), std::byte{0});
    ULONG read_done = 0;
    const auto read_status = CB_Read(
        &fs,
        read_ctx,
        read_buffer.data(),
        0,
        static_cast<ULONG>(read_buffer.size()),
        &read_done);
    CB_Close(&fs, read_ctx);

    return Require(read_status == STATUS_SUCCESS, "Renamed file should read successfully after batched flush") &&
           Require(read_done == read_buffer.size(), "Renamed file should report full payload") &&
           Require(read_buffer == payload, "Renamed file should preserve payload bytes");
#else
    return true;
#endif
}

bool TestRepeatedDeferredCloseStatusWritesAreCoalesced()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    MountContext context{};
    context.args.readwrite = true;
    context.args.write_backend = L"Native";
    context.native_write_enabled = true;

    std::error_code ec;
    const auto status_root = std::filesystem::temp_directory_path(ec) /
        "ApfsAccess" /
        "fs-host-semantics" /
        (L"deferred-status-coalesce-" + std::to_wstring(GetTickCount64()));
    if (ec)
    {
        return Require(false, "Deferred status coalescing test should resolve temp directory");
    }
    std::filesystem::create_directories(status_root, ec);
    if (ec)
    {
        return Require(false, "Deferred status coalescing test should create status directory");
    }
    context.args.status_file = (status_root / "status.json").wstring();
    ScopeExit cleanup{[&]()
    {
        std::filesystem::remove_all(status_root, ec);
    }};

    context.tx_manager = std::make_unique<apfsaccess::rw::TransactionManager>(L"Conservative");
    const apfsaccess::rw::MetadataStore::PayloadIdentity staged_identity{ 1, 1 };
    if (!RecordMutationBestEffort(
            &context,
            apfsaccess::rw::TransactionManager::MutationKind::Write,
            L"\\deferred-status.bin",
            L"",
            0,
            4096,
            false,
            0,
            0,
            &staged_identity))
    {
        return Require(false, "Deferred status coalescing test should stage dirty work");
    }

    RequestDeferredCloseCommit(&context);
    if (!Require(
            context.deferred_close_status_publish_pending.load(std::memory_order_acquire),
            "First deferred close should queue worker-side status publication") ||
        !Require(
            !std::filesystem::exists(std::filesystem::path(context.args.status_file)),
            "First deferred close should not write status on the foreground callback path"))
    {
        return false;
    }

    (void)context.deferred_close_status_publish_pending.exchange(false, std::memory_order_acq_rel);
    if (!Require(
            WriteHostStatusFile(context, context.recovery_active, context.runtime_last_commit_xid),
            "Worker-side deferred close status publish should succeed"))
    {
        return false;
    }
    const auto read_status_file = [&]() -> std::string
    {
        std::ifstream in(context.args.status_file, std::ios::binary);
        return std::string{
            std::istreambuf_iterator<char>(in),
            std::istreambuf_iterator<char>()};
    };
    const auto first_status = read_status_file();
    if (!Require(first_status.find("\"closeCommitDeferred\":true") != std::string::npos, "First deferred close should publish deferred state") ||
        !Require(first_status.find("\"deferredCloseCommitCount\":1") != std::string::npos, "First deferred close should publish initial deferred count"))
    {
        return false;
    }

    RequestDeferredCloseCommit(&context);
    if (!Require(
            context.deferred_close_status_publish_pending.load(std::memory_order_acquire),
            "Repeated deferred close should queue worker-side status publication"))
    {
        return false;
    }
    (void)context.deferred_close_status_publish_pending.exchange(false, std::memory_order_acq_rel);
    if (!Require(
            WriteHostStatusFile(context, context.recovery_active, context.runtime_last_commit_xid),
            "Repeated deferred close worker-side status publish should succeed"))
    {
        return false;
    }
    const auto second_status = read_status_file();
    return Require(
        context.deferred_close_commit_count.load(std::memory_order_acquire) == 2,
        "Repeated deferred close should still update the in-memory counter") &&
        Require(
            second_status.find("\"closeCommitDeferred\":true") != std::string::npos,
            "Repeated deferred close worker-side publish should keep deferred state visible") &&
        Require(
            second_status.find("\"deferredCloseCommitCount\":2") != std::string::npos,
            "Repeated deferred close worker-side publish should expose updated deferred count") &&
        Require(
            second_status != first_status,
            "Repeated deferred close worker-side publish should update the deferred count outside the foreground path");
#else
    return true;
#endif
}

bool TestDeferredBarrierCompletionPublishesIdleStatus()
{
    MountContext context{};
    context.args.readwrite = true;
    context.args.write_backend = L"Overlay";
    context.overlay_write_enabled = true;
    context.close_commit_deferred.store(true, std::memory_order_release);
    context.deferred_commit_in_flight = true;

    std::error_code ec;
    const auto status_root = std::filesystem::temp_directory_path(ec) /
        "ApfsAccess" /
        "fs-host-semantics" /
        (L"deferred-barrier-idle-status-" + std::to_wstring(GetTickCount64()));
    if (ec)
    {
        return Require(false, "Deferred barrier idle-status test should resolve temp directory");
    }
    std::filesystem::create_directories(status_root, ec);
    if (ec)
    {
        return Require(false, "Deferred barrier idle-status test should create status directory");
    }
    context.args.status_file = (status_root / "status.json").wstring();
    ScopeExit cleanup{[&]()
    {
        std::filesystem::remove_all(status_root, ec);
    }};

    if (!Require(
            WriteHostStatusFile(context, context.recovery_active, context.runtime_last_commit_xid),
            "Deferred barrier idle-status test should publish in-flight state"))
    {
        return false;
    }

    CompleteDeferredCommitBarrier(&context, true, STATUS_SUCCESS);

    std::ifstream in(context.args.status_file, std::ios::binary);
    if (!Require(in.good(), "Deferred barrier idle-status test should open completed status file"))
    {
        return false;
    }
    const std::string status_json{
        std::istreambuf_iterator<char>(in),
        std::istreambuf_iterator<char>()};
    return Require(
               status_json.find("\"deferredCommitInFlight\":false") != std::string::npos,
               "Deferred barrier completion should publish the idle in-flight state") &&
           Require(
               status_json.find("\"closeCommitDeferred\":false") != std::string::npos,
               "Deferred barrier completion should publish cleared deferred-close state");
}

bool TestTargetlessDeferredBarrierFailureRemainsVisible()
{
    MountContext context{};
    context.deferred_commit_in_flight = true;

    if (!Require(
            CompleteDeferredCommitBarrier(&context, false, STATUS_UNSUCCESSFUL),
            "targetless failure fixture should complete its in-flight barrier"))
    {
        return false;
    }

    const bool prior_failure_observed = !BeginDeferredCommitBarrier(&context, false, 0);
    RequestDeferredCloseCommit(&context, 0);
    const bool retry_started = BeginDeferredCommitBarrier(&context, false, 0);
    bool retry_effective_success = false;
    const bool retry_completed = retry_started && CompleteDeferredCommitBarrier(
        &context,
        true,
        STATUS_SUCCESS,
        &retry_effective_success);

    return Require(
               prior_failure_observed,
               "a later targetless observer must not forget the prior targetless failure") &&
           Require(retry_started, "an explicit later request should be allowed to retry the failed barrier") &&
           Require(
               retry_completed && retry_effective_success,
               "a successful explicit retry should replace the prior targetless failure state");
}

bool TestStrictFinalizationScanFailureFailsClosed()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    std::error_code ec;
    const auto run_root = std::filesystem::temp_directory_path(ec) /
        "ApfsAccess" /
        "fs-host-semantics" /
        (L"strict-finalization-scan-failure-" + std::to_wstring(GetTickCount64()));
    std::filesystem::create_directories(run_root, ec);
    if (!Require(!ec, "strict finalization failure test should create its temp directory"))
    {
        return false;
    }

    MountContext context{};
    context.args.readwrite = true;
    context.args.write_backend = L"Overlay";
    context.args.write_recovery_policy = L"FailClosed";
    context.native_write_enabled = true;
    context.overlay_write_enabled = true;
    context.args.status_file = (run_root / "status.json").wstring();
    context.recovery_marker_file = run_root / "recovery.marker";
    const auto wal_path = run_root / "write-ahead.wal";
    context.tx_manager = std::make_unique<apfsaccess::rw::TransactionManager>(L"DeferredContent");
    context.tx_manager->SetVolumeIdentity(L"strict-finalization-scan-volume");
    context.tx_manager->SetJournalPath(wal_path.wstring());
    ScopeExit cleanup{[&]()
    {
        SetEnvironmentVariableW(L"APFSACCESS_DISABLE_FINALIZATION_COVERAGE_CACHE", nullptr);
        context.tx_manager.reset();
        std::filesystem::remove_all(run_root, ec);
    }};

    apfsaccess::rw::TransactionManager::MutationIntent mutation{};
    mutation.kind = apfsaccess::rw::TransactionManager::MutationKind::SetBasicInfo;
    mutation.path = L"\\strict-finalization.txt";
    mutation.timestamp_utc = 1;
    if (!Require(context.tx_manager->Begin(), "strict finalization failure fixture should begin") ||
        !Require(
            context.tx_manager->RecordMutation(mutation),
            "strict finalization failure fixture should record metadata"))
    {
        return false;
    }

    context.tx_manager->SetJournalFaultInjectionHook([](std::string_view stage)
    {
        return stage == "read-all-exclusive";
    });
    SetEnvironmentVariableW(L"APFSACCESS_DISABLE_FINALIZATION_COVERAGE_CACHE", L"1");
    const auto finalized = FinalizeMutationJournalBestEffort(
        &context,
        L"StrictFinalizationScanFailure");
    context.tx_manager->SetJournalFaultInjectionHook({});
    const auto snapshot = apfsaccess::rw::WriteAheadLog::ReadAll(
        wal_path,
        "strict-finalization-scan-volume");

    std::lock_guard<std::recursive_mutex> runtime_lock(context.runtime_state_mutex);
    return Require(!finalized, "a strict WAL scan failure must fail the user-facing finalization boundary") &&
           Require(
               !context.tx_manager->RecoveryStateValid(),
               "strict WAL scan failure must retain poisoned recovery state") &&
           Require(
               context.tx_manager->CurrentState() == apfsaccess::rw::TransactionManager::State::Active,
               "strict WAL scan failure must not append a terminal marker to invalid evidence") &&
           Require(
               snapshot.status == apfsaccess::rw::WriteAheadLog::ReadStatus::Ok &&
                   snapshot.records.empty(),
               "strict WAL scan failure must preserve the original empty durable WAL prefix") &&
           Require(
               context.recovery_active && context.pending_native_writes && context.write_degraded &&
                   !context.native_write_enabled && !context.overlay_write_enabled,
               "strict WAL scan failure must latch fail-closed runtime state");
#else
    return true;
#endif
}

bool TestDeferredCloseBurstExtendsQuietWindowWhileWriterOpen()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    MountContext context{};
    context.args.readwrite = true;
    context.args.write_backend = L"Native";
    context.native_write_enabled = true;
    context.open_write_handle_count.store(1, std::memory_order_release);

    for (std::uint64_t request_index = 1; request_index < kDeferredCloseCommitBurstThreshold; ++request_index)
    {
        RequestDeferredCloseCommit(&context);
    }
    std::chrono::steady_clock::time_point before_threshold_deadline{};
    {
        std::lock_guard<std::mutex> lock(context.deferred_commit_mutex);
        before_threshold_deadline = context.deferred_commit_deadline;
    }

    RequestDeferredCloseCommit(&context);
    std::chrono::steady_clock::time_point burst_deadline{};
    std::uint64_t burst_count = 0;
    {
        std::lock_guard<std::mutex> lock(context.deferred_commit_mutex);
        burst_deadline = context.deferred_commit_deadline;
        burst_count = context.deferred_commit_burst_count;
    }

    const auto extension_ms = std::chrono::duration_cast<std::chrono::milliseconds>(
        burst_deadline - before_threshold_deadline).count();
    return Require(
        burst_count == kDeferredCloseCommitBurstThreshold &&
            extension_ms >=
                (kDeferredCloseCommitBurstQuietPeriod - kDeferredCloseCommitBaseQuietPeriod).count() / 2,
        "Deferred close bursts should use the longer quiet window only while write handles remain open");
#else
    return true;
#endif
}

