bool TestDeferredCloseRecentActivityCutoffAvoidsSecondQuietWindow()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    MountContext context{};
    context.args.readwrite = true;
    context.args.write_backend = L"Native";
    context.native_write_enabled = true;

    RequestDeferredCloseCommit(&context);
    std::uint64_t deadline_tick_ms = 0;
    {
        std::lock_guard<std::mutex> lock(context.deferred_commit_mutex);
        deadline_tick_ms = context.deferred_commit_deadline_tick_ms;
    }
    if (!Require(deadline_tick_ms != 0, "Deferred close cutoff test should capture a scheduled deadline tick"))
    {
        return false;
    }

    context.last_foreground_mutation_tick_ms.store(
        deadline_tick_ms - 1,
        std::memory_order_release);
    if (!Require(
            !HasActiveOrRecentForegroundMutationsAfter(&context, deadline_tick_ms),
            "Deferred close cutoff should ignore activity already covered by the scheduled quiet window"))
    {
        return false;
    }

    context.active_foreground_mutation_callbacks.store(1, std::memory_order_release);
    if (!Require(
            HasActiveOrRecentForegroundMutationsAfter(&context, deadline_tick_ms),
            "Deferred close cutoff should still block while a foreground callback is active"))
    {
        return false;
    }
    context.active_foreground_mutation_callbacks.store(0, std::memory_order_release);

    const auto now_tick = static_cast<std::uint64_t>(GetTickCount64());
    context.last_foreground_mutation_tick_ms.store(now_tick, std::memory_order_release);
    return Require(
        HasActiveOrRecentForegroundMutationsAfter(&context, now_tick - 1),
        "Deferred close cutoff should still extend for foreground activity after the scheduled deadline");
#else
    return true;
#endif
}

bool TestDeferredWorkerCarriesAcceptedTargetThroughCleanup()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
    SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", L"1");
    ScopeExit clear_writeback_env{[]()
    {
        SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", nullptr);
    }};

    std::error_code ec;
    const auto run_root = std::filesystem::temp_directory_path(ec) /
        "ApfsAccess" /
        "fs-host-semantics" /
        (L"deferred-target-worker-" + std::to_wstring(GetTickCount64()));
    if (ec)
    {
        return Require(false, "Deferred target test should resolve temp directory");
    }
    std::filesystem::create_directories(run_root, ec);
    if (ec)
    {
        return Require(false, "Deferred target test should create temp directory");
    }

    MountContext context{};
    context.args.readwrite = true;
    context.args.write_backend = L"Native";
    context.args.write_recovery_policy = L"FailClosed";
    context.native_write_enabled = true;
    context.overlay_write_enabled = false;
    context.pending_native_writes = true;
    context.test_force_native_mutation_staging_success = true;
    context.test_forced_native_commit_status =
        apfsaccess::rw::MetadataStore::CommitStatus::Committed;
    context.tx_manager = std::make_unique<apfsaccess::rw::TransactionManager>(L"DeferredContent");
    context.tx_manager->SetVolumeIdentity(L"deferred-target-volume");
    context.tx_journal_file = run_root / "write-ahead.wal";
    context.tx_manager->SetJournalPath(context.tx_journal_file.wstring());

    ScopeExit cleanup{[&]()
    {
        StopDeferredCommitWorker(&context);
        std::filesystem::remove_all(run_root, ec);
    }};

    const apfsaccess::rw::MetadataStore::PayloadIdentity staged_identity{ 1, 1 };
    if (!Require(
            RecordMutationBestEffort(
                &context,
                apfsaccess::rw::TransactionManager::MutationKind::Write,
                L"\\deferred-target.bin",
                L"",
                0,
                4096,
                false,
                0,
                0,
                &staged_identity),
            "Deferred target test should stage a transaction"))
    {
        return false;
    }

    std::uint64_t accepted_target = 0;
    if (!Require(
            AcceptMutationJournalForDeferredCommitBestEffort(
                &context,
                L"DeferredTargetAccept",
                &accepted_target),
            "Deferred target test should accept the transaction") ||
        !Require(accepted_target != 0, "Deferred target test should receive a nonzero accepted sequence"))
    {
        return false;
    }

    StartDeferredCommitWorker(&context);
    RequestDeferredCloseCommit(&context, accepted_target);

    bool completed = false;
    const auto wait_started = std::chrono::steady_clock::now();
    while (std::chrono::steady_clock::now() - wait_started < std::chrono::seconds(3))
    {
        {
            std::lock_guard<std::mutex> lock(context.deferred_commit_mutex);
            completed = !context.deferred_commit_in_flight &&
                context.deferred_commit_completed_target >= accepted_target;
        }
        if (completed)
        {
            break;
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
    }

    apfsaccess::rw::TransactionManager::DurabilityWatermarks watermarks{};
    {
        std::lock_guard<std::mutex> lock(context.tx_mutex);
        watermarks = context.tx_manager->Watermarks();
    }
    std::uint64_t completed_target = 0;
    std::uint64_t failed_target = 0;
    NTSTATUS last_status = STATUS_UNSUCCESSFUL;
    {
        std::lock_guard<std::mutex> lock(context.deferred_commit_mutex);
        completed_target = context.deferred_commit_completed_target;
        failed_target = context.deferred_commit_failed_target;
        last_status = context.deferred_commit_last_status;
    }

    return Require(completed, "Deferred worker should finish the accepted target") &&
           Require(completed_target >= accepted_target, "Deferred worker should record the accepted target as completed") &&
           Require(failed_target < accepted_target, "Deferred worker should not record the accepted target as failed") &&
           Require(last_status == STATUS_SUCCESS, "Deferred worker should publish successful completion status") &&
           Require(watermarks.accepted_sequence == accepted_target, "Deferred worker should preserve the accepted watermark") &&
           Require(watermarks.apfs_durable_sequence == accepted_target, "Deferred worker should advance the APFS-durable watermark") &&
           Require(watermarks.cleanup_sequence == accepted_target, "Deferred worker should advance the cleanup watermark");
#else
    return true;
#endif
}

bool TestDeferredWorkerExceptionFailsClosedWithoutTerminatingHost()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", L"1");
    ScopeExit clear_defer_env{[]()
    {
        SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", nullptr);
    }};

    std::error_code ec;
    const auto run_root = std::filesystem::temp_directory_path(ec) /
        "ApfsAccess" /
        "fs-host-semantics" /
        (L"deferred-worker-exception-" + std::to_wstring(GetTickCount64()));
    if (ec)
    {
        return Require(false, "Deferred worker exception test should resolve temp directory");
    }
    std::filesystem::create_directories(run_root, ec);
    if (ec)
    {
        return Require(false, "Deferred worker exception test should create temp directory");
    }

    MountContext context{};
    context.args.readwrite = true;
    context.args.write_backend = L"Native";
    context.args.write_recovery_policy = L"FailClosed";
    context.args.status_file = (run_root / "status.json").wstring();
    context.recovery_marker_file = run_root / "recovery.marker";
    context.native_write_enabled = true;
    context.pending_native_writes = true;
    context.test_force_native_mutation_staging_success = true;
    context.test_forced_native_commit_status =
        apfsaccess::rw::MetadataStore::CommitStatus::Committed;
    context.test_throw_deferred_worker_exception_after_claim = true;
    context.tx_manager = std::make_unique<apfsaccess::rw::TransactionManager>(L"DeferredContent");
    context.tx_manager->SetVolumeIdentity(L"deferred-worker-exception-volume");
    context.tx_journal_file = run_root / "write-ahead.wal";
    context.tx_manager->SetJournalPath(context.tx_journal_file.wstring());

    ScopeExit cleanup{[&]()
    {
        StopDeferredCommitWorker(&context);
        std::filesystem::remove_all(run_root, ec);
    }};

    const apfsaccess::rw::MetadataStore::PayloadIdentity staged_identity{2, 1};
    if (!Require(
            RecordMutationBestEffort(
                &context,
                apfsaccess::rw::TransactionManager::MutationKind::Write,
                L"\\deferred-worker-exception.bin",
                L"",
                0,
                4096,
                false,
                0,
                0,
                &staged_identity),
            "Deferred worker exception test should stage a transaction"))
    {
        return false;
    }

    std::uint64_t accepted_target = 0;
    if (!Require(
            AcceptMutationJournalForDeferredCommitBestEffort(
                &context,
                L"DeferredWorkerExceptionAccept",
                &accepted_target),
            "Deferred worker exception test should accept the transaction") ||
        !Require(accepted_target != 0, "Deferred worker exception test should receive an accepted target"))
    {
        return false;
    }

    StartDeferredCommitWorker(&context);
    RequestDeferredCloseCommit(&context, accepted_target);

    bool exception_handled = false;
    const auto wait_deadline = std::chrono::steady_clock::now() + std::chrono::seconds(3);
    while (std::chrono::steady_clock::now() < wait_deadline)
    {
        {
            std::lock_guard<std::mutex> lock(context.deferred_commit_mutex);
            exception_handled =
                context.deferred_commit_failed_target == accepted_target &&
                !context.deferred_commit_in_flight;
        }
        if (exception_handled)
        {
            break;
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
    }

    const auto barrier_started = BeginDeferredCommitBarrier(&context, false, accepted_target);
    StopDeferredCommitWorker(&context);

    apfsaccess::rw::TransactionManager::DurabilityWatermarks watermarks{};
    {
        std::lock_guard<std::mutex> lock(context.tx_mutex);
        watermarks = context.tx_manager->Watermarks();
    }
    std::ifstream status_in(context.args.status_file, std::ios::binary);
    const std::string status_json{
        std::istreambuf_iterator<char>(status_in),
        std::istreambuf_iterator<char>()};

    return Require(exception_handled, "Deferred worker exception must fail its claimed target") &&
           Require(!barrier_started, "Deferred worker exception must fail the target barrier") &&
           Require(!context.deferred_commit_thread.joinable(), "Deferred worker exception must allow clean join") &&
           Require(context.recovery_active, "Deferred worker exception must activate recovery") &&
           Require(context.write_degraded, "Deferred worker exception must publish degraded state") &&
           Require(!context.native_write_enabled && !context.overlay_write_enabled,
                   "Deferred worker exception must block further writes") &&
           Require(context.runtime_recovery_reason == L"DeferredCommitWorkerException",
                   "Deferred worker exception must publish a specific recovery reason") &&
           Require(watermarks.accepted_sequence == accepted_target &&
                       watermarks.apfs_durable_sequence < accepted_target &&
                       watermarks.cleanup_sequence < accepted_target,
                   "Deferred worker exception must retain accepted recovery evidence") &&
           Require(status_json.find("\"recoveryReason\":\"DeferredCommitWorkerException\"") != std::string::npos,
                   "Deferred worker exception must publish truthful host status");
#else
    return true;
#endif
}

