bool TestDeferredPressureCountsObjectsNotRanges()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    std::error_code ec;
    const auto run_root = std::filesystem::temp_directory_path(ec) /
        "ApfsAccess" /
        "fs-host-semantics" /
        (L"deferred-pressure-objects-" + std::to_wstring(GetTickCount64()));
    if (ec)
    {
        return Require(false, "Deferred object-pressure test should resolve temp directory");
    }

    MountContext context{};
    context.payload_spool_volume_identity = "deferred-pressure-volume";
    context.payload_spool = std::make_unique<apfsaccess::rw::PayloadSpool>(
        apfsaccess::rw::PayloadSpool::Options{
            run_root,
            context.payload_spool_volume_identity,
            1024 * 1024,
            1024 * 1024,
            1024,
        });
    ScopeExit cleanup{[&]()
    {
        if (context.payload_spool)
        {
            (void)context.payload_spool->CleanupThroughSequence(
                (std::numeric_limits<std::uint64_t>::max)());
            context.payload_spool.reset();
        }
        std::filesystem::remove_all(run_root, ec);
    }};

    const std::array<std::byte, 1> payload{std::byte{0x5a}};
    for (std::uint64_t range = 0; range < kDeferredCloseCommitBurstThreshold; ++range)
    {
        if (!Require(
                context.payload_spool->Append({
                    context.payload_spool_volume_identity,
                    100,
                    1,
                    range * 128 * 1024,
                    range + 1,
                    payload,
                }),
                "Deferred object-pressure test should append same-object ranges"))
        {
            return false;
        }
    }

    const auto same_object = context.payload_spool->SnapshotCounters();
    if (!Require(
            same_object.dirty_range_count == kDeferredCloseCommitBurstThreshold &&
                same_object.dirty_object_count == 1,
            "Same-object pressure fixture should contain many ranges but one dirty object") ||
        !Require(
            !DeferredCommitPressureReached(&context),
            "Many ranges in one sequential file should not hit the many-file pressure threshold"))
    {
        return false;
    }

    for (std::uint64_t object = 1; object < kDeferredCloseCommitBurstThreshold; ++object)
    {
        if (!Require(
                context.payload_spool->Append({
                    context.payload_spool_volume_identity,
                    100 + object,
                    1,
                    0,
                    kDeferredCloseCommitBurstThreshold + object,
                    payload,
                }),
                "Deferred object-pressure test should append distinct objects"))
        {
            return false;
        }
    }

    const auto many_objects = context.payload_spool->SnapshotCounters();
    return Require(
               many_objects.dirty_object_count == kDeferredCloseCommitBurstThreshold,
               "Distinct-object pressure fixture should reach the file threshold") &&
           Require(
               DeferredCommitPressureReached(&context),
               "Thirty-two dirty objects should hit deferred pressure");
#else
    return true;
#endif
}

