bool TestDeleteCloseHardBoundaryFailureRestoresLocalNode()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
    SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", L"0");
    ScopeExit clear_writeback_env{[]()
    {
        SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", nullptr);
    }};

    MountContext context{};
    if (!ConfigureNativeCommitFailureForUnitTest(context))
    {
        return true;
    }
    if (!Require(PrepareUnitHydrationRoot(context, L"deferred-close-delete-boundary"), "Deferred delete-boundary test should prepare cache root"))
    {
        return false;
    }
    if (!Require(ConfigureUnitRecoveryMarker(context, L"deferred-close-delete-boundary"), "Deferred delete-boundary test should configure a recovery marker"))
    {
        return false;
    }
    ScopeExit cleanup{[&]()
    {
        StopDeferredCommitWorker(&context);
        std::error_code ec;
        std::filesystem::remove(context.recovery_marker_file, ec);
        std::filesystem::remove_all(context.session_root, ec);
    }};
    context.tx_manager = std::make_unique<apfsaccess::rw::TransactionManager>(L"Conservative");

    SeedRoot(context);
    std::array<std::byte, 16> security{};
    SeedSecurity(context, security);

    auto root = context.nodes.at(Key(L"\\"));
    AddChildName(root->children, L"victim.txt");
    auto file = MakeNode(L"\\victim.txt", false, false);
    file->open_handle_count = 1;
    file->file_size = 4;
    context.nodes.emplace(Key(file->path), file);
    const std::vector<std::byte> payload{std::byte{'K'}, std::byte{'E'}, std::byte{'E'}, std::byte{'P'}};
    const auto hydration_path = HydrationPath(&context, *file);
    if (!Require(WriteFileBytes(hydration_path, payload), "Deferred delete-boundary test should seed hydration bytes"))
    {
        return false;
    }

    auto fs = BuildFileSystem(&context);
    auto* open_context = new OpenContext();
    open_context->node = file;
    open_context->allow_delete = true;
    CB_Cleanup(
        &fs,
        open_context,
        const_cast<PWSTR>(L"\\victim.txt"),
        FspCleanupDelete);
    CB_Close(&fs, open_context);

    if (!Require(
            context.test_native_commit_attempt_count == 1 &&
                !context.close_commit_deferred.load(std::memory_order_acquire) &&
                context.recovery_active,
            "Delete close should synchronously surface its hard-boundary commit failure"))
    {
        return false;
    }

    auto restored_it = context.nodes.find(Key(L"\\victim.txt"));
    if (!Require(restored_it != context.nodes.end(), "Delete hard-boundary failure should restore the deleted node"))
    {
        return false;
    }
    const auto restored = restored_it->second;
    return Require(HasChildName(root->children, L"victim.txt"), "Delete failure should restore the parent child entry") &&
           Require(!restored->delete_pending && !restored->delete_latched && restored->delete_intent_count == 0, "Restored delete node should be visible") &&
           Require(std::filesystem::exists(HydrationPath(&context, *restored)), "Delete failure should keep the restored hydration file") &&
           Require(ReadFileBytes(HydrationPath(&context, *restored)) == payload, "Delete failure should restore hydrated bytes") &&
           Require(context.tx_manager->PendingMutationCount() == 0, "Delete failure should abort the journal");
#else
    return true;
#endif
}

