bool TestPlainCloseDoesNotDeferMixedPendingTransaction()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
    SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", L"1");
    ScopeExit clear_writeback_env{[]()
    {
        SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", nullptr);
    }};

    MountContext context{};
    context.args.readwrite = true;
    context.args.write_backend = L"Native";
    context.args.write_recovery_policy = L"FailClosed";
    context.native_write_enabled = true;
    context.overlay_write_enabled = false;
    context.pending_native_writes = true;
    context.test_force_native_mutation_staging_success = true;
    context.test_forced_native_mutation_count = 1;
    context.test_forced_native_mutations_content_only = false;
    context.test_forced_native_mutations_continue_deferred_close = false;
    context.test_forced_native_commit_status = apfsaccess::rw::MetadataStore::CommitStatus::PersistFailed;
    context.test_forced_native_commit_recovery_reason = L"UnexpectedForegroundCloseCommit";
    context.test_forced_native_commit_recovery_required = true;

    SeedRoot(context);
    std::array<std::byte, 16> security{};
    SeedSecurity(context, security);

    auto file = MakeNode(L"\\plain-close.txt", false);
    file->open_handle_count = 1;
    file->write_handle_count = 1;
    context.nodes.emplace(Key(file->path), file);
    auto root = context.nodes[Key(L"\\")];
    AddChildName(root->children, L"plain-close.txt");

    auto* open_context = new OpenContext();
    open_context->node = file;
    open_context->write_open = true;

    auto fs = BuildFileSystem(&context);
    RequestDeferredCloseCommit(&context);
    open_context->mutation_observed.store(true, std::memory_order_release);
    CB_Close(&fs, open_context);

    return Require(
        context.test_native_commit_attempt_count == 1 &&
            !context.close_commit_deferred.load(std::memory_order_acquire) &&
            context.pending_native_writes &&
            context.recovery_active &&
            !context.native_write_enabled &&
            context.nodes.find(Key(L"\\plain-close.txt")) != context.nodes.end(),
        "Plain close should synchronously drain a mixed transaction instead of using queue-only acceptance");
#else
    return true;
#endif
}

