bool TestExperimentalDeferredRenameImmediateReadUsesCommittedSourcePath()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
    SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", L"1");
    SetEnvironmentVariableW(L"APFSACCESS_EXPERIMENTAL_NAMESPACE_WRITEBACK", L"1");
    SetEnvironmentVariableW(L"APFSACCESS_DISABLE_NAMESPACE_WRITEBACK", nullptr);
    ScopeExit clear_env{[]()
    {
        SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_EXPERIMENTAL_NAMESPACE_WRITEBACK", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_DISABLE_NAMESPACE_WRITEBACK", nullptr);
    }};

    MountContext context{};
    context.args.volume = L"Main";
    context.args.readwrite = true;
    context.args.write_backend = L"Native";
    context.args.write_require_canonical_commit = false;
    context.args.write_disallow_scaffold_commit_on_non_fixture = false;
    context.args.write_reject_scaffold_replay_blob_on_non_fixture = false;
    context.args.write_require_canonical_replay_candidate_on_non_fixture = false;
    context.native_write_enabled = true;
    context.overlay_write_enabled = false;
    SeedRoot(context);
    std::array<std::byte, 16> security{};
    SeedSecurity(context, security);
    if (!Require(PrepareUnitHydrationRoot(context, L"deferred-rename-immediate-read"), "Deferred rename immediate-read test should prepare cache root") ||
        !Require(ConfigureUnitRecoveryMarker(context, L"deferred-rename-immediate-read"), "Deferred rename immediate-read test should configure recovery marker"))
    {
        return false;
    }

    std::error_code ec;
    ScopeExit cleanup{[&]()
    {
        StopDeferredCommitWorker(&context);
        std::filesystem::remove(context.recovery_marker_file, ec);
        std::filesystem::remove_all(context.session_root, ec);
    }};

    const auto image_path = context.session_root / "deferred-rename-immediate-read.apfs.img";
    if (!Require(CreateSyntheticApfsContainerForTest(image_path, 4096), "Deferred rename immediate-read test should create synthetic APFS image"))
    {
        return false;
    }
    context.args.device = image_path.wstring();

    apfsaccess::rw::MetadataStore::VolumeContext rw_context
    {
        image_path.wstring(),
        L"Main",
    };
    rw_context.allow_legacy_scaffold_for_fixtures = true;
    rw_context.disallow_scaffold_commit_on_non_fixture = false;
    rw_context.reject_scaffold_replay_blob_on_non_fixture = false;
    rw_context.require_canonical_replay_candidate_on_non_fixture = false;
    context.owned_metadata_store = std::make_unique<apfsaccess::rw::MetadataStore>(std::move(rw_context));
    context.metadata_store = context.owned_metadata_store.get();

    const auto committed_payload = BuildPatternPayloadForTest(128 * 1024, 0x47);
    std::unordered_map<std::wstring, std::vector<std::byte>> staged_payloads;
    context.metadata_store->SetFilePayloadProvider(
        [&staged_payloads](const std::wstring& path, std::uint64_t logical_size) -> std::optional<std::vector<std::byte>>
        {
            auto pending = staged_payloads.find(path);
            if (pending == staged_payloads.end())
            {
                return std::nullopt;
            }
            auto payload = pending->second;
            payload.resize(static_cast<std::size_t>(logical_size), std::byte{0});
            return payload;
        });

    {
        std::lock_guard<std::mutex> metadata_lock(context.metadata_mutex);
        if (!Require(context.metadata_store->LoadContainerSuperblocks(), "Deferred rename immediate-read test should load container superblocks") ||
            !Require(context.metadata_store->LoadObjectMap(), "Deferred rename immediate-read test should load object map") ||
            !Require(context.metadata_store->LoadSpacemanState(), "Deferred rename immediate-read test should load spaceman state") ||
            !Require(context.metadata_store->PrepareNativeWritePath(), "Deferred rename immediate-read test should prepare native write path"))
        {
            return false;
        }

        apfsaccess::rw::MetadataStore::MutationRequest create_file{};
        create_file.operation = apfsaccess::rw::MetadataStore::MutationOperation::CreateFile;
        create_file.path = L"\\source.bin";
        if (!Require(
                context.metadata_store->ApplyMutation(create_file) == apfsaccess::rw::MetadataStore::MutationStatus::Applied,
                "Deferred rename immediate-read test should create committed file"))
        {
            return false;
        }

        staged_payloads[L"\\source.bin"] = committed_payload;
        apfsaccess::rw::MetadataStore::MutationRequest write_file{};
        write_file.operation = apfsaccess::rw::MetadataStore::MutationOperation::Write;
        write_file.path = L"\\source.bin";
        write_file.length = committed_payload.size();
        if (!Require(
                context.metadata_store->ApplyMutation(write_file) == apfsaccess::rw::MetadataStore::MutationStatus::Applied,
                "Deferred rename immediate-read test should stage committed payload") ||
            !Require(
                context.metadata_store->CommitPendingMutations() == apfsaccess::rw::MetadataStore::CommitStatus::Committed,
                "Deferred rename immediate-read test should commit payload"))
        {
            return false;
        }
    }

    if (!Require(MergeCommittedInodeStateIntoNodeIndex(&context), "Deferred rename immediate-read test should merge committed inode state"))
    {
        return false;
    }

    auto source = FindNode(&context, L"\\source.bin");
    if (!Require(source != nullptr, "Deferred rename immediate-read test should expose committed source"))
    {
        return false;
    }
    std::filesystem::remove(HydrationPath(&context, *source), ec);
    ec.clear();

    auto fs = BuildFileSystem(&context);
    const auto rename_status = CB_Rename(
        &fs,
        nullptr,
        const_cast<PWSTR>(L"\\source.bin"),
        const_cast<PWSTR>(L"\\renamed.bin"),
        FALSE);
    auto renamed = FindNode(&context, L"\\renamed.bin");
    if (!Require(
            rename_status == STATUS_SUCCESS &&
                renamed != nullptr &&
                context.test_native_commit_attempt_count == 0 &&
                context.close_commit_deferred.load(std::memory_order_acquire) &&
                renamed->committed_read_path == L"\\source.bin",
            "Experimental deferred rename should keep the committed read path until flush"))
    {
        return false;
    }

    PVOID read_ctx = nullptr;
    FSP_FSCTL_FILE_INFO read_info{};
    const auto open_status = CB_Open(
        &fs,
        const_cast<PWSTR>(L"\\renamed.bin"),
        FILE_NON_DIRECTORY_FILE,
        FILE_READ_DATA,
        &read_ctx,
        &read_info);
    if (!Require(open_status == STATUS_SUCCESS && read_ctx != nullptr, "Deferred renamed file should open for immediate read"))
    {
        return false;
    }
    auto* read_open_context = reinterpret_cast<OpenContext*>(read_ctx);
    if (!Require(
            context.test_native_commit_attempt_count == 0 &&
                context.close_commit_deferred.load(std::memory_order_acquire) &&
                renamed->committed_read_path == L"\\source.bin" &&
                read_open_context->metadata_read_fallback,
            "Deferred renamed read-open should use committed-path fallback without draining the pending rename"))
    {
        CB_Close(&fs, read_ctx);
        return false;
    }

    std::array<char, 96> buffer{};
    ULONG read_done = 0;
    const auto read_offset = static_cast<UINT64>(4096);
    const auto read_status = CB_Read(
        &fs,
        read_ctx,
        buffer.data(),
        read_offset,
        static_cast<ULONG>(buffer.size()),
        &read_done);
    CB_Close(&fs, read_ctx);
    if (!Require(read_status == STATUS_SUCCESS, "Deferred renamed file should read through the old committed path") ||
        !Require(read_done == buffer.size(), "Deferred renamed file should return the requested immediate-read bytes"))
    {
        return false;
    }
    for (std::size_t index = 0; index < buffer.size(); ++index)
    {
        const auto expected = committed_payload[static_cast<std::size_t>(read_offset) + index];
        if (!Require(static_cast<std::byte>(static_cast<unsigned char>(buffer[index])) == expected, "Deferred renamed file immediate-read bytes should match committed source bytes"))
        {
            return false;
        }
    }

    OpenContext flush_context{};
    flush_context.node = context.nodes.at(Key(L"\\"));
    FSP_FSCTL_FILE_INFO flush_info{};
    const auto flush_status = CB_Flush(&fs, &flush_context, &flush_info);
    return Require(
        flush_status == STATUS_SUCCESS &&
            !context.close_commit_deferred.load(std::memory_order_acquire) &&
            context.deferred_rename_rollback_plans.empty() &&
            renamed->committed_read_path.empty(),
        "Flush should commit deferred rename and clear the temporary committed read path");
#else
    return true;
#endif
}

bool TestDefaultDeferredRenameWorkerFailureRestoresLocalNamespace()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
    SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", L"1");
    SetEnvironmentVariableW(L"APFSACCESS_EXPERIMENTAL_NAMESPACE_WRITEBACK", L"1");
    SetEnvironmentVariableW(L"APFSACCESS_DISABLE_NAMESPACE_WRITEBACK", nullptr);
    ScopeExit clear_env{[]()
    {
        SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_EXPERIMENTAL_NAMESPACE_WRITEBACK", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_DISABLE_NAMESPACE_WRITEBACK", nullptr);
    }};

    MountContext context{};
    if (!ConfigureNativeCommitFailureForUnitTest(context))
    {
        return true;
    }
    if (!Require(PrepareUnitHydrationRoot(context, L"deferred-rename-worker-rollback"), "Deferred rename worker rollback test should prepare cache root") ||
        !Require(ConfigureUnitRecoveryMarker(context, L"deferred-rename-worker-rollback"), "Deferred rename worker rollback test should configure recovery marker"))
    {
        return false;
    }
    ScopeExit cleanup{[&]()
    {
        StopDeferredCommitWorker(&context);
        std::error_code ec;
        std::filesystem::remove(context.recovery_marker_file, ec);
        std::filesystem::remove_all(context.session_root, ec);
    }};
    context.tx_manager = std::make_unique<apfsaccess::rw::TransactionManager>(L"Conservative");

    SeedRoot(context);
    std::array<std::byte, 16> security{};
    SeedSecurity(context, security);
    auto root = context.nodes.at(Key(L"\\"));
    AddChildName(root->children, L"source.txt");
    auto source = MakeNode(L"\\source.txt", false, false);
    context.nodes.emplace(Key(source->path), source);

    auto fs = BuildFileSystem(&context);
    const auto rename_status = CB_Rename(
        &fs,
        nullptr,
        const_cast<PWSTR>(L"\\source.txt"),
        const_cast<PWSTR>(L"\\renamed.txt"),
        FALSE);
    if (!Require(
            rename_status == STATUS_SUCCESS &&
                context.test_native_commit_attempt_count == 0 &&
                context.close_commit_deferred.load(std::memory_order_acquire) &&
                context.nodes.find(Key(L"\\source.txt")) == context.nodes.end() &&
                context.nodes.find(Key(L"\\renamed.txt")) != context.nodes.end(),
            "Default deferred rename should return before the worker drains"))
    {
        return false;
    }

    // Inspect the queued rename before allowing the worker to change its state.
    StartDeferredCommitWorker(&context);
    {
        std::unique_lock<std::mutex> lock(context.deferred_commit_mutex);
        if (!Require(context.deferred_commit_cv.wait_for(lock, std::chrono::seconds(60), [&]()
            {
                return !context.deferred_commit_requested &&
                    !context.deferred_commit_in_flight &&
                    !NT_SUCCESS(context.deferred_commit_last_status);
            }), "Deferred rename worker should publish failed completion"))
        {
            return false;
        }
    }

    // Namespace rollback precedes the recovery latch and journal abort. Join
    // the actual worker before inspecting their final state or its containers.
    if (!Require(StopDeferredCommitWorker(&context), "Deferred rename failure worker should finish")) return false;
    return Require(context.recovery_active, "Deferred worker failure should latch recovery-active state") &&
           Require(context.deferred_rename_rollback_plans.empty(), "Deferred worker failure should clear rename rollback plans") &&
           Require(context.nodes.find(Key(L"\\source.txt")) != context.nodes.end(), "Deferred worker failure should restore source path") &&
           Require(context.nodes.find(Key(L"\\renamed.txt")) == context.nodes.end(), "Deferred worker failure should remove transient destination path") &&
           Require(HasChildName(root->children, L"source.txt"), "Deferred worker failure should restore source child entry") &&
           Require(!HasChildName(root->children, L"renamed.txt"), "Deferred worker failure should remove destination child entry") &&
           Require(context.tx_manager->PendingMutationCount() == 0, "Deferred worker failure should abort the journal");
#else
    return true;
#endif
}

