bool TestDeferredRenameChainCoalescesAcrossInterleavedFileRename()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
    SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", L"1");
    SetEnvironmentVariableW(L"APFSACCESS_EXPERIMENTAL_NAMESPACE_WRITEBACK", L"1");
    SetEnvironmentVariableW(L"APFSACCESS_DISABLE_NAMESPACE_WRITEBACK", nullptr);
    ScopeExit clear_env{[]()
    {
        SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_EXPERIMENTAL_NAMESPACE_WRITEBACK", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_DISABLE_NAMESPACE_WRITEBACK", nullptr);
    }};

    MountContext context{};
    if (!ConfigureNativeCommitFailureForUnitTest(context))
    {
        return true;
    }
    if (!Require(PrepareUnitHydrationRoot(context, L"deferred-rename-interleaved-chain-rollback"), "Interleaved rename rollback test should prepare cache root") ||
        !Require(ConfigureUnitRecoveryMarker(context, L"deferred-rename-interleaved-chain-rollback"), "Interleaved rename rollback test should configure recovery marker"))
    {
        return false;
    }
    ScopeExit cleanup{[&]()
    {
        StopDeferredCommitWorker(&context);
        std::error_code ec;
        std::filesystem::remove(context.recovery_marker_file, ec);
        std::filesystem::remove_all(context.session_root, ec);
    }};
    context.tx_manager = std::make_unique<apfsaccess::rw::TransactionManager>(L"Conservative");

    SeedRoot(context);
    std::array<std::byte, 16> security{};
    SeedSecurity(context, security);
    auto root = context.nodes.at(Key(L"\\"));
    AddChildName(root->children, L"source.txt");
    AddChildName(root->children, L"other.txt");
    auto source = MakeNode(L"\\source.txt", false, false);
    auto other = MakeNode(L"\\other.txt", false, false);
    context.nodes.emplace(Key(source->path), source);
    context.nodes.emplace(Key(other->path), other);

    auto fs = BuildFileSystem(&context);
    const auto first_source_rename_status = CB_Rename(
        &fs,
        nullptr,
        const_cast<PWSTR>(L"\\source.txt"),
        const_cast<PWSTR>(L"\\renamed.txt"),
        FALSE);
    const auto unrelated_rename_status = CB_Rename(
        &fs,
        nullptr,
        const_cast<PWSTR>(L"\\other.txt"),
        const_cast<PWSTR>(L"\\other-renamed.txt"),
        FALSE);
    const auto second_source_rename_status = CB_Rename(
        &fs,
        nullptr,
        const_cast<PWSTR>(L"\\renamed.txt"),
        const_cast<PWSTR>(L"\\second.txt"),
        FALSE);

    const auto source_plan = std::find_if(
        context.deferred_rename_rollback_plans.begin(),
        context.deferred_rename_rollback_plans.end(),
        [](const RenameLocalSnapshot& plan)
        {
            return plan.old_path == L"\\source.txt";
        });
    const auto other_plan = std::find_if(
        context.deferred_rename_rollback_plans.begin(),
        context.deferred_rename_rollback_plans.end(),
        [](const RenameLocalSnapshot& plan)
        {
            return plan.old_path == L"\\other.txt";
        });
    auto second = FindNode(&context, L"\\second.txt");
    auto other_renamed = FindNode(&context, L"\\other-renamed.txt");
    if (!Require(
            first_source_rename_status == STATUS_SUCCESS &&
            unrelated_rename_status == STATUS_SUCCESS &&
            second_source_rename_status == STATUS_SUCCESS &&
            context.test_native_commit_attempt_count == 0 &&
            !context.recovery_active &&
            context.close_commit_deferred.load(std::memory_order_acquire) &&
            context.deferred_rename_rollback_plans.size() == 2 &&
            source_plan != context.deferred_rename_rollback_plans.end() &&
            source_plan->new_path == L"\\second.txt" &&
            other_plan != context.deferred_rename_rollback_plans.end() &&
            other_plan->new_path == L"\\other-renamed.txt" &&
            second != nullptr &&
            second->committed_read_path == L"\\source.txt" &&
            other_renamed != nullptr &&
            other_renamed->committed_read_path == L"\\other.txt" &&
            context.nodes.find(Key(L"\\source.txt")) == context.nodes.end() &&
            context.nodes.find(Key(L"\\renamed.txt")) == context.nodes.end() &&
            context.nodes.find(Key(L"\\second.txt")) != context.nodes.end() &&
            context.nodes.find(Key(L"\\other.txt")) == context.nodes.end() &&
            context.nodes.find(Key(L"\\other-renamed.txt")) != context.nodes.end(),
        "Interleaved deferred rename chains should coalesce per source object before flush"))
    {
        return false;
    }

    OpenContext flush_context{};
    flush_context.node = root;
    FSP_FSCTL_FILE_INFO info{};
    const auto flush_status = CB_Flush(&fs, &flush_context, &info);
    return Require(
        flush_status == STATUS_MEDIA_WRITE_PROTECTED &&
            context.test_native_commit_attempt_count == 1 &&
            context.recovery_active &&
            context.deferred_rename_rollback_plans.empty() &&
            context.nodes.find(Key(L"\\source.txt")) != context.nodes.end() &&
            context.nodes.find(Key(L"\\renamed.txt")) == context.nodes.end() &&
            context.nodes.find(Key(L"\\second.txt")) == context.nodes.end() &&
            context.nodes.find(Key(L"\\other.txt")) != context.nodes.end() &&
            context.nodes.find(Key(L"\\other-renamed.txt")) == context.nodes.end() &&
            HasChildName(root->children, L"source.txt") &&
            HasChildName(root->children, L"other.txt") &&
            !HasChildName(root->children, L"renamed.txt") &&
            !HasChildName(root->children, L"second.txt") &&
            !HasChildName(root->children, L"other-renamed.txt"),
        "Interleaved deferred rename chain flush failure should restore each original namespace");
#else
    return true;
#endif
}

