bool TestDeferredAcceptanceFlushesSpoolBeforeWalMarker()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
    SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", L"1");
    SetEnvironmentVariableW(L"APFSACCESS_DISABLE_DEFERRED_INDEX_PERSISTENCE", nullptr);
    SetEnvironmentVariableW(L"APFSACCESS_DISABLE_INLINE_ACCEPTANCE_PAYLOAD", L"1");
    ScopeExit clear_deferred_env{[]()
    {
        SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_DISABLE_DEFERRED_INDEX_PERSISTENCE", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_DISABLE_INLINE_ACCEPTANCE_PAYLOAD", nullptr);
    }};

    std::error_code ec;
    const auto run_root = std::filesystem::temp_directory_path(ec) /
        "ApfsAccess" /
        "fs-host-semantics" /
        (L"durable-acceptance-" + std::to_wstring(GetTickCount64()));
    if (ec)
    {
        return Require(false, "Deferred acceptance test should resolve temp directory");
    }
    std::filesystem::create_directories(run_root, ec);
    if (ec)
    {
        return Require(false, "Deferred acceptance test should create temp directory");
    }
    ScopeExit cleanup{[&]()
    {
        std::filesystem::remove_all(run_root, ec);
    }};

    MountContext context{};
    context.payload_spool_volume_identity = "durable-acceptance-volume";
    context.payload_spool = std::make_unique<apfsaccess::rw::PayloadSpool>(
        apfsaccess::rw::PayloadSpool::Options{
            run_root / "spool",
            context.payload_spool_volume_identity,
            1024 * 1024,
            1024 * 1024,
            1024,
        });
    context.tx_journal_file = run_root / "write-ahead.wal";
    context.args.status_file = (run_root / "status.json").wstring();
    context.tx_manager = std::make_unique<apfsaccess::rw::TransactionManager>(L"DeferredContent");
    context.tx_manager->SetVolumeIdentity(L"durable-acceptance-volume");
    context.tx_manager->SetJournalPath(context.tx_journal_file.wstring());

    bool spool_durable_before_accept = false;
    context.tx_manager->SetFaultInjectionHook([&](const std::string& stage)
    {
        if (stage == "accept-start")
        {
            const auto counters = context.payload_spool->SnapshotCounters();
            spool_durable_before_accept =
                counters.index_dirty &&
                counters.bytes_since_sync == 0 &&
                counters.appends_since_sync == 0 &&
                counters.payload_only_flush_count == 1 &&
                counters.index_persist_count == 0;
        }
    });

    const std::array<std::byte, 8> payload{
        std::byte{0x10}, std::byte{0x20}, std::byte{0x30}, std::byte{0x40},
        std::byte{0x50}, std::byte{0x60}, std::byte{0x70}, std::byte{0x80},
    };
    const apfsaccess::rw::MetadataStore::PayloadIdentity identity{7001, 12};
    if (!Require(
            RecordPayloadWriteMutationBestEffort(
                &context,
                L"\\accepted.bin",
                4096,
                payload.data(),
                static_cast<std::uint32_t>(payload.size()),
                &identity),
            "Deferred acceptance test should stage payload and WAL intent"))
    {
        return false;
    }

    const auto before = context.payload_spool->SnapshotCounters();
    if (!Require(before.index_dirty, "Deferred acceptance should begin with an unflushed spool index"))
    {
        return false;
    }

    std::uint64_t accepted_sequence = 0;
    if (!Require(
            AcceptMutationJournalForDeferredCommitBestEffort(
                &context,
                L"CloseDeferredAccept",
                &accepted_sequence),
            "Deferred acceptance should persist payload-first acceptance"))
    {
        return false;
    }

    const auto journal = apfsaccess::rw::WriteAheadLog::ReadAll(
        context.tx_journal_file,
        context.payload_spool_volume_identity);
    if (!Require(spool_durable_before_accept, "Spool payload must be durable while its reconstructible index remains deferred before WAL acceptance") ||
        !Require(journal.status == apfsaccess::rw::WriteAheadLog::ReadStatus::Ok, "Accepted WAL should read cleanly") ||
        !Require(journal.records.size() == 2, "Accepted WAL should contain payload record and accepted marker"))
    {
        return false;
    }

    const auto& payload_record = journal.records[0];
    const auto& accepted_marker = journal.records[1];
    constexpr std::array<std::uint8_t, 32> expected_sha256{
        0xa5, 0x1f, 0x32, 0x55, 0x1a, 0xae, 0x34, 0x6e,
        0xd4, 0x94, 0x8a, 0x0d, 0xba, 0x69, 0xcf, 0x40,
        0x6b, 0xdc, 0xfd, 0x3d, 0xb5, 0x7f, 0x30, 0xc2,
        0xc9, 0xbf, 0x0f, 0x5d, 0x29, 0x45, 0xf2, 0xc4,
    };
    const auto watermarks = context.tx_manager->Watermarks();
    if (!Require(payload_record.object_id == identity.object_id, "Accepted WAL should bind payload object id") ||
        !Require(payload_record.parent_object_id == identity.generation, "Accepted WAL should bind payload generation") ||
        !Require(payload_record.payload_spool_id == payload_record.sequence, "Accepted WAL should bind spool and WAL sequence") ||
        !Require(payload_record.payload_offset == 0, "Accepted WAL should bind physical spool offset") ||
        !Require(payload_record.payload_length == payload.size(), "Accepted WAL should bind payload length") ||
        !Require(payload_record.logical_offset == 4096, "Accepted WAL should bind logical offset") ||
        !Require(payload_record.payload_sha256 == expected_sha256, "Accepted WAL should bind payload SHA-256") ||
        !Require(accepted_marker.state == apfsaccess::rw::WriteAheadLog::RecordState::Accepted, "Accepted WAL should end with accepted marker") ||
        !Require(accepted_sequence == accepted_marker.sequence, "Acceptance helper should return accepted marker sequence") ||
        !Require(watermarks.accepted_sequence == accepted_sequence, "Transaction manager should publish accepted watermark") ||
        !Require(watermarks.apfs_durable_sequence == 0, "Accepted transaction should remain distinct from APFS durability") ||
        !Require(context.tx_manager->CurrentState() == apfsaccess::rw::TransactionManager::State::Idle, "Accepted batch should release transaction slot"))
    {
        return false;
    }

    context.close_commit_deferred.store(true, std::memory_order_release);
    {
        std::lock_guard<std::mutex> lock(context.deferred_commit_mutex);
        context.deferred_commit_in_flight = true;
        context.deferred_commit_in_flight_target = accepted_sequence;
    }
    g_host_status_file_build_count_for_test = 0;
    if (!Require(
            FinalizeMutationJournalBestEffort(&context, L"AcceptedCheckpoint"),
            "Successful APFS checkpoint should advance accepted work through cleanup"))
    {
        return false;
    }
    const auto finalized = context.tx_manager->Watermarks();
    const auto cleaned_spool = context.payload_spool->SnapshotCounters();
    const auto finalized_journal = apfsaccess::rw::WriteAheadLog::ReadAll(
        context.tx_journal_file,
        context.payload_spool_volume_identity);
    const auto finalization_status_builds = g_host_status_file_build_count_for_test;
    return Require(finalized.accepted_sequence == accepted_sequence, "Finalization should preserve accepted watermark") &&
           Require(finalized.apfs_durable_sequence == accepted_sequence, "Finalization should advance APFS-durable watermark") &&
           Require(finalized.cleanup_sequence == accepted_sequence, "Finalization should advance cleanup watermark after spool cleanup") &&
           Require(cleaned_spool.dirty_range_count == 0, "Cleanup watermark should follow removal of accepted spool ranges") &&
           Require(finalized_journal.status == apfsaccess::rw::WriteAheadLog::ReadStatus::Ok, "Finalized WAL should remain readable") &&
           Require(finalized_journal.records.size() == 4, "Finalized WAL should append APFS-durable and cleanup watermarks") &&
           Require(finalized_journal.records[2].state == apfsaccess::rw::WriteAheadLog::RecordState::Checkpointed, "APFS-durable watermark should precede cleanup") &&
           Require(finalized_journal.records[3].state == apfsaccess::rw::WriteAheadLog::RecordState::Cleaned, "Cleanup watermark should be last") &&
           Require(finalization_status_builds == 1, "Deferred finalization should publish only the post-barrier idle status");
#else
    return true;
#endif
}

