struct OwnedTeardownEvents
{
    OwnedTeardownEvents()
    {
        g_teardown_stop_entered = CreateEventW(nullptr, TRUE, FALSE, nullptr);
        g_teardown_stop_release = CreateEventW(nullptr, TRUE, FALSE, nullptr);
        g_teardown_remove_entered = CreateEventW(nullptr, TRUE, FALSE, nullptr);
        g_teardown_remove_release = CreateEventW(nullptr, TRUE, FALSE, nullptr);
        g_teardown_delete_entered = CreateEventW(nullptr, TRUE, FALSE, nullptr);
        g_teardown_delete_release = CreateEventW(nullptr, TRUE, FALSE, nullptr);
    }

    ~OwnedTeardownEvents()
    {
        CloseHandle(g_teardown_stop_entered);
        CloseHandle(g_teardown_stop_release);
        CloseHandle(g_teardown_remove_entered);
        CloseHandle(g_teardown_remove_release);
        CloseHandle(g_teardown_delete_entered);
        CloseHandle(g_teardown_delete_release);
        g_teardown_stop_entered = nullptr;
        g_teardown_stop_release = nullptr;
        g_teardown_remove_entered = nullptr;
        g_teardown_remove_release = nullptr;
        g_teardown_delete_entered = nullptr;
        g_teardown_delete_release = nullptr;
    }

    bool Valid() const
    {
        return g_teardown_stop_entered && g_teardown_stop_release &&
            g_teardown_remove_entered && g_teardown_remove_release &&
            g_teardown_delete_entered && g_teardown_delete_release;
    }
};

void ResetOwnedTeardownObservations()
{
    g_shutdown_teardown_sequence.store(0, std::memory_order_release);
    g_shutdown_stop_return_order.store(0, std::memory_order_release);
    g_shutdown_remove_order.store(0, std::memory_order_release);
    g_shutdown_delete_order.store(0, std::memory_order_release);
    g_teardown_stop_user_context.store(nullptr, std::memory_order_release);
    g_teardown_remove_user_context.store(nullptr, std::memory_order_release);
    g_teardown_delete_user_context.store(nullptr, std::memory_order_release);
}

std::unique_ptr<MountContext> BuildOwnedTeardownContext(FSP_FILE_SYSTEM& fs)
{
    auto context = std::make_unique<MountContext>();
    context->args.winfsp_teardown_timeout_ms = 25;
    context->fs = &fs;
    context->fs->UserContext = context.get();
    context->winfsp_lifecycle_phase.store(
        WinFspLifecyclePhase::Dispatching,
        std::memory_order_release);
    context->api.Stop = StopDispatcherForOwnedTeardownTest;
    context->api.RemoveMount = RemoveMountForOwnedTeardownTest;
    context->api.Delete = DeleteFileSystemForOwnedTeardownTest;
    return context;
}

bool TestWinFspTeardownTimeoutPinsOwnershipAtEachPhase()
{
    bool ok = true;
    for (int blocked_phase = 0; blocked_phase < 3; ++blocked_phase)
    {
        OwnedTeardownEvents events;
        if (!Require(events.Valid(), "Owned teardown test should create synchronization events"))
        {
            return false;
        }
        ResetOwnedTeardownObservations();
        if (blocked_phase > 0)
        {
            SetEvent(g_teardown_stop_release);
        }
        if (blocked_phase > 1)
        {
            SetEvent(g_teardown_remove_release);
        }

        FSP_FILE_SYSTEM fs{};
        auto owner = BuildOwnedTeardownContext(fs);
        auto* const original_context = owner.get();
        const auto result = StartBoundedWinFspTeardown(
            owner,
            owner->args.winfsp_teardown_timeout_ms);
        const HANDLE entered[] = {
            g_teardown_stop_entered,
            g_teardown_remove_entered,
            g_teardown_delete_entered,
        };
        const HANDLE releases[] = {
            g_teardown_stop_release,
            g_teardown_remove_release,
            g_teardown_delete_release,
        };

        ok &= Require(
            result.status == WinFspTeardownStatus::TimedOut,
            "Blocked WinFsp teardown should report its bounded timeout");
        ok &= Require(owner == nullptr, "Timed-out teardown should remove the caller's ownership");
        ok &= Require(
            result.task && result.task->context.get() == original_context,
            "Timed-out teardown task should retain the exact MountContext");
        ok &= Require(
            WaitForSingleObject(entered[blocked_phase], 0) == WAIT_OBJECT_0,
            "The selected teardown phase should have entered before timeout");
        ok &= Require(
            result.task->context->fs == &fs && fs.UserContext == original_context,
            "Timed-out teardown should keep WinFsp UserContext valid");
        for (int later = blocked_phase + 1; later < 3; ++later)
        {
            ok &= Require(
                WaitForSingleObject(entered[later], 0) == WAIT_TIMEOUT,
                "A blocked teardown phase must prevent later phases from starting");
        }

        SetEvent(g_teardown_stop_release);
        SetEvent(g_teardown_remove_release);
        SetEvent(g_teardown_delete_release);
        ok &= Require(
            WaitForSingleObject(result.task->worker_thread, 2'000) == WAIT_OBJECT_0,
            "Released teardown worker should exit through its real thread handle");
        ok &= Require(
            ReclaimCompletedWinFspTeardown(result.task, owner),
            "Completed teardown should restore MountContext ownership");
        ok &= Require(
            owner.get() == original_context && owner->fs == nullptr,
            "Delete completion should be the only point that clears fs");
        ok &= Require(
            owner->winfsp_lifecycle_phase.load(std::memory_order_acquire) ==
                WinFspLifecyclePhase::Destroyed,
            "Completed teardown should publish the destroyed lifecycle phase");
        ok &= Require(
            g_teardown_stop_user_context.load(std::memory_order_acquire) == original_context &&
                g_teardown_remove_user_context.load(std::memory_order_acquire) == original_context &&
                g_teardown_delete_user_context.load(std::memory_order_acquire) == original_context,
            "Every teardown phase should observe the pinned MountContext");
        ok &= Require(
            g_shutdown_stop_return_order.load(std::memory_order_acquire) == 1 &&
                g_shutdown_remove_order.load(std::memory_order_acquire) == 2 &&
                g_shutdown_delete_order.load(std::memory_order_acquire) == 3,
            "Owned teardown should serialize Stop, RemoveMount, and Delete exactly");
    }
    return ok;
}

bool TestDiagnosticWatchdogDuringTeardownOwnerTransfer()
{
    std::error_code ec;
    const auto temp_root = std::filesystem::temp_directory_path(ec);
    if (!Require(!ec && (temp_root.root_name() == L"D:" || temp_root.root_name() == L"d:"),
            "Diagnostic owner-transfer test requires TEMP/TMP on D:")) return false;
    std::array<wchar_t, MAX_PATH> unique_path{};
    if (!Require(GetTempFileNameW(temp_root.c_str(), L"ado", 0, unique_path.data()) != 0,
            "Diagnostic owner-transfer test should reserve a unique D: TEMP path")) return false;
    const std::wstring diagnostic_base = unique_path.data();
    ScopeExit remove_diagnostics{[&]()
    {
        std::filesystem::remove(diagnostic_base + L".callback.json.tmp", ec);
        std::filesystem::remove(diagnostic_base + L".callback.json", ec);
        std::filesystem::remove(diagnostic_base, ec);
    }};

    bool ok = true;
    for (int blocked_phase = 0; blocked_phase < 3; ++blocked_phase)
    {
        OwnedTeardownEvents events;
        if (!Require(events.Valid(), "Diagnostic owner-transfer test should create events")) return false;
        ResetOwnedTeardownObservations();
        const HANDLE entered[] = {g_teardown_stop_entered, g_teardown_remove_entered,
            g_teardown_delete_entered};
        const HANDLE releases[] = {g_teardown_stop_release, g_teardown_remove_release,
            g_teardown_delete_release};
        // Keep only the selected fake phase blocked. No WinFsp API is called.
        for (int phase = 0; phase < 3; ++phase)
            if (phase != blocked_phase) SetEvent(releases[phase]);

        FSP_FILE_SYSTEM fs{};
        std::vector<std::unique_ptr<MountContext>> contexts;
        contexts.push_back(BuildOwnedTeardownContext(fs));
        static std::atomic<bool> phase_wait_failed{false};
        phase_wait_failed.store(false, std::memory_order_release);
        // The existing fixture uses infinite waits; this regression bounds each
        // fake callback too, and reports an expired barrier as a test failure.
        contexts[0]->api.Stop = [](FSP_FILE_SYSTEM*)
        {
            SetEvent(g_teardown_stop_entered);
            if (WaitForSingleObject(g_teardown_stop_release, 10'000) != WAIT_OBJECT_0)
                phase_wait_failed.store(true, std::memory_order_release);
        };
        contexts[0]->api.RemoveMount = [](FSP_FILE_SYSTEM*)
        {
            SetEvent(g_teardown_remove_entered);
            if (WaitForSingleObject(g_teardown_remove_release, 10'000) != WAIT_OBJECT_0)
                phase_wait_failed.store(true, std::memory_order_release);
        };
        contexts[0]->api.Delete = [](FSP_FILE_SYSTEM*)
        {
            SetEvent(g_teardown_delete_entered);
            if (WaitForSingleObject(g_teardown_delete_release, 10'000) != WAIT_OBJECT_0)
                phase_wait_failed.store(true, std::memory_order_release);
        };
        auto* const original_context = contexts[0].get();
        {
            std::lock_guard<std::mutex> lock(original_context->callback_activity_mutex);
            original_context->active_callback_name = "owner-transfer-active";
            original_context->last_callback_name = "owner-transfer-last";
            MountContext::OperationActivity operation{};
            operation.kind = 7;
            operation.waiting = false;
            operation.started_tick_ms = 101;
            operation.acquired_tick_ms = 102;
            operation.callback = "owner-transfer-operation";
            original_context->operation_activity.emplace(123, std::move(operation));
        }
        original_context->active_callback_count.store(1, std::memory_order_release);
        original_context->peak_callback_count.store(2, std::memory_order_release);
        original_context->active_callback_started_tick_ms.store(101, std::memory_order_release);

        // Match the manifest writer's capture before launch. The writer below
        // never reads the unique_ptr source; only this test thread moves it.
        const std::vector<MountContext*> observers{original_context};
        WinFspTeardownResult result{};
        bool joined = false;
        ScopeExit finish_worker{[&]()
        {
            for (const auto release : releases) SetEvent(release);
            if (result.task && result.task->worker_thread && !joined)
            {
                // Never unwind stack-owned fs/events under a live worker, even
                // if an assertion or diagnostic allocation throws.
                if (WaitForSingleObject(result.task->worker_thread, 5'000) != WAIT_OBJECT_0)
                {
                    Require(false, "Diagnostic teardown worker did not exit after release");
                    std::abort();
                }
                joined = true;
            }
            if (result.task && !contexts[0])
                (void)ReclaimCompletedWinFspTeardown(result.task, contexts[0]);
        }};
        result = StartBoundedWinFspTeardown(contexts[0], 25);
        if (!Require(result.task && result.task->worker_thread,
                "Diagnostic owner-transfer test should launch a teardown worker")) return false;
        ok &= Require(result.status == WinFspTeardownStatus::TimedOut,
            "Selected fake teardown phase should exceed the bounded owner-transfer timeout");
        if (!Require(WaitForSingleObject(entered[blocked_phase], 2'000) == WAIT_OBJECT_0,
                "Selected fake teardown phase should reach its barrier")) return false;
        ok &= Require(!contexts[0] && result.task->context.get() == observers[0],
            "Original manifest owner should be empty while the worker owns the captured observer");
        ok &= Require(WaitForSingleObject(result.task->worker_thread, 0) == WAIT_TIMEOUT,
            "Teardown worker must remain blocked during diagnostic publication");

        // Remove the previous phase's output so stale data cannot pass this phase.
        std::filesystem::remove(diagnostic_base + L".callback.json", ec);
        if (!Require(!ec, "Diagnostic fixture should remove any previous phase output")) return false;
        for (auto* const observer : observers)
            WriteCallbackWatchdogFile(*observer, diagnostic_base);
        std::ifstream in(diagnostic_base + L".callback.json", std::ios::binary);
        const std::string json{std::istreambuf_iterator<char>(in), std::istreambuf_iterator<char>()};
        ok &= Require(in.is_open() && json.find("\"activeCallbacks\":1,") != std::string::npos &&
                json.find("\"peakCallbacks\":2,") != std::string::npos &&
                json.find("\"activeCallbackStartedTickMs\":101,") != std::string::npos &&
                json.find("\"activeCallback\":\"owner-transfer-active\"") != std::string::npos &&
                json.find("\"lastCallback\":\"owner-transfer-last\"") != std::string::npos,
            "Real watchdog writer should emit captured callback fields during owner transfer");
        ok &= Require(json.find("\"operations\":[{\"thread\":123,\"kind\":7,"
                "\"waitingForGuard\":false,\"startedTickMs\":101,\"acquiredTickMs\":102,"
                "\"callback\":\"owner-transfer-operation\"}]") != std::string::npos,
            "Real watchdog writer should emit the captured operation fields during owner transfer");
        ok &= Require(!contexts[0] && result.task->context.get() == original_context &&
                WaitForSingleObject(result.task->worker_thread, 0) == WAIT_TIMEOUT &&
                !phase_wait_failed.load(std::memory_order_acquire),
            "Diagnostic publication must finish while the selected phase still pins ownership");
        for (const auto release : releases) SetEvent(release);
        joined = WaitForSingleObject(result.task->worker_thread, 2'000) == WAIT_OBJECT_0;
        if (!Require(joined, "Released diagnostic teardown worker should exit")) return false;
        ok &= Require(!phase_wait_failed.load(std::memory_order_acquire),
            "Every fake teardown callback should be released before its deadline");
        ok &= Require(ReclaimCompletedWinFspTeardown(result.task, contexts[0]),
            "Diagnostic fixture should reclaim ownership after joining the worker");
        ok &= Require(contexts[0].get() == original_context && contexts[0].get() == observers[0] &&
                !result.task->context && contexts[0]->fs == nullptr &&
                contexts[0]->winfsp_lifecycle_phase.load(std::memory_order_acquire) ==
                    WinFspLifecyclePhase::Destroyed,
            "Captured observer identity should survive owner transfer and completed teardown reclaim");
    }
    return ok;
}

bool TestWinFspTeardownTimeoutStopsManifestSiblingCleanup()
{
    OwnedTeardownEvents events;
    if (!Require(events.Valid(), "Manifest timeout test should create synchronization events"))
    {
        return false;
    }
    ResetOwnedTeardownObservations();
    FSP_FILE_SYSTEM first_fs{};
    FSP_FILE_SYSTEM second_fs{};
    std::vector<std::unique_ptr<MountContext>> contexts;
    contexts.push_back(BuildOwnedTeardownContext(first_fs));
    contexts.push_back(BuildOwnedTeardownContext(second_fs));
    contexts[0]->container_volume_oid = 101;
    contexts[1]->container_volume_oid = 202;
    contexts[0]->manifest_mount_attached.store(true, std::memory_order_release);
    contexts[1]->manifest_mount_attached.store(true, std::memory_order_release);
    auto* const first_context = contexts[0].get();
    auto* const second_context = contexts[1].get();
    std::shared_ptr<WinFspTeardownTask> pinned_task;
    g_winfsp_teardown_fail_stop_hook_for_test =
        [&](const std::shared_ptr<WinFspTeardownTask>& task)
        {
            pinned_task = task;
            throw std::runtime_error("expected-winfsp-teardown-fail-stop");
        };
    ScopeExit clear_hook{[]() { g_winfsp_teardown_fail_stop_hook_for_test = {}; }};

    bool fail_stop_observed = false;
    try
    {
        (void)DrainManifestContextsAfterServe(contexts, 7);
    }
    catch (const std::runtime_error& error)
    {
        fail_stop_observed = std::string(error.what()) ==
            "expected-winfsp-teardown-fail-stop";
    }

    bool ok = Require(fail_stop_observed, "Timed-out manifest teardown should enter fail-stop") &&
        Require(contexts[0] == nullptr, "Timed-out first manifest context should remain task-owned") &&
        Require(
            pinned_task && pinned_task->context.get() == first_context &&
                pinned_task->context->container_volume_oid == 101,
            "Fail-stop should retain the first session context and binding") &&
        Require(
            contexts[1].get() == second_context && contexts[1]->fs == &second_fs &&
                contexts[1]->container_volume_oid == 202,
            "First teardown timeout should prevent sibling teardown and session cleanup") &&
        Require(
            WaitForSingleObject(g_teardown_remove_entered, 0) == WAIT_TIMEOUT &&
                g_shutdown_teardown_sequence.load(std::memory_order_acquire) == 0,
            "Timed-out first Stop must not begin later teardown phases");

    SetEvent(g_teardown_stop_release);
    SetEvent(g_teardown_remove_release);
    SetEvent(g_teardown_delete_release);
    ok &= Require(
        pinned_task && WaitForSingleObject(pinned_task->worker_thread, 2'000) == WAIT_OBJECT_0,
        "Released manifest teardown worker should exit");
    ok &= Require(
        pinned_task && ReclaimCompletedWinFspTeardown(pinned_task, contexts[0]),
        "Manifest timeout test should reclaim ownership only after worker exit");
    return ok;
}

bool TestWinFspTeardownWorkerStartFailurePinsOwnership()
{
    FSP_FILE_SYSTEM fs{};
    auto owner = std::make_unique<MountContext>();
    auto* const original_context = owner.get();
    owner->fs = &fs;
    fs.UserContext = original_context;
    owner->winfsp_lifecycle_phase.store(
        WinFspLifecyclePhase::Created,
        std::memory_order_release);
    owner->api.Delete = DeleteFileSystemForManifestPartialStartupTest;
    g_winfsp_teardown_force_worker_start_failure_for_test = true;
    ScopeExit clear_failure{[]()
    {
        g_winfsp_teardown_force_worker_start_failure_for_test = false;
    }};

    auto result = StartBoundedWinFspTeardown(owner, 25);
    const bool ok = Require(
            result.status == WinFspTeardownStatus::StartFailed,
            "Injected teardown worker-start failure should be reported") &&
        Require(owner == nullptr, "Worker-start failure should transfer caller ownership") &&
        Require(
            result.task && result.task->context.get() == original_context &&
                result.task->context->fs == &fs && fs.UserContext == original_context,
            "Worker-start failure should pin context, API, and WinFsp identity") &&
        Require(
            result.task->context->winfsp_lifecycle_phase.load(std::memory_order_acquire) ==
                WinFspLifecyclePhase::TeardownOwned,
            "Worker-start failure should remain in teardown-owned state");
    owner = std::move(result.task->context);
    owner->fs = nullptr;
    owner->winfsp_lifecycle_phase.store(
        WinFspLifecyclePhase::Destroyed,
        std::memory_order_release);
    return ok;
}

bool TestWinFspRuntimeVersionRejectsKnownDeadlockBuilds()
{
    const auto candidates = WinFspRuntimeDllCandidates();
    std::array<wchar_t, 32768> windows_directory{};
    const auto windows_directory_length = GetWindowsDirectoryW(
        windows_directory.data(),
        static_cast<UINT>(windows_directory.size()));
    const auto expected_system_driver =
        std::filesystem::path(windows_directory.data()) /
        L"System32" /
        L"drivers" /
        L"winfsp-x64.sys";
    return Require(
               !IsSafeWinFspRuntimeVersion(2, 1, 25156),
               "WinFsp 2.1 must be rejected because its driver has known forced-shutdown deadlocks") &&
           Require(
               !IsSafeWinFspRuntimeVersion(2, 2, 26214),
               "WinFsp 2.2 builds before Beta 4 must be rejected because they predate the teardown fix") &&
           Require(
               IsSafeWinFspRuntimeVersion(2, 2, 26215),
               "WinFsp 2.2 Beta 4 must satisfy the minimum safe runtime floor") &&
           Require(
               IsSafeWinFspRuntimeVersion(3, 0, 0),
               "A newer WinFsp major version should satisfy the runtime floor") &&
           Require(
               !IsSafeWinFspRuntimePair(2, 2, 26215, 2, 2, 26214, 2, 2),
               "A safe DLL must not authorize a pre-Beta-4 driver binary") &&
           Require(
               IsSafeWinFspRuntimePair(2, 2, 26215, 2, 2, 26215, 2, 2),
               "Matching WinFsp 2.2 Beta 4 DLL and driver files should satisfy the floor") &&
           Require(
               IsSafeWinFspRuntimeFilePair(
                   2, 2, 26215, 0,
                   2, 2, 26215, 0),
               "Matching WinFsp 2.2 Beta 4 files should pass before any driver API call") &&
           Require(
               !IsSafeWinFspRuntimeFilePair(
                   2, 2, 26215, 0,
                   2, 2, 26214, 0),
               "A pre-fix driver file must fail before any driver API call") &&
           Require(
               !IsSafeWinFspRuntimeFilePair(
                   2, 2, 26215, 0,
                   2, 2, 26215, 1),
               "A driver-file revision mismatch must fail before any driver API call") &&
           Require(
               IsExactWinFspBinarySet(
                   2, 2, 26215, 0,
                   2, 2, 26215, 0,
                   2, 2, 26215, 0),
               "Matching DLL, installed driver, and active driver versions should be accepted") &&
           Require(
               !IsExactWinFspBinarySet(
                   2, 2, 26215, 0,
                   2, 2, 26215, 0,
                   2, 2, 26214, 0),
               "A pre-fix active driver must not be authorized by newer files on disk") &&
           Require(
               !IsExactWinFspBinarySet(
                   2, 2, 26215, 1,
                   2, 2, 26215, 1,
                   2, 2, 26215, 0),
               "The active driver revision must exactly match the selected runtime") &&
           Require(
               IsPreexistingActiveWinFspDriverSafe(
                   ActiveWinFspDriverProbeResult::NotFound,
                   2, 2, 26215, 0,
                   2, 2, 26215, 0,
                   0, 0, 0, 0),
               "A clean boot with no active WinFsp driver should allow the verified driver to start") &&
           Require(
               IsPreexistingActiveWinFspDriverSafe(
                   ActiveWinFspDriverProbeResult::Found,
                   2, 2, 26215, 0,
                   2, 2, 26215, 0,
                   2, 2, 26215, 0),
               "A matching preexisting active WinFsp driver should be reusable") &&
           Require(
               !IsPreexistingActiveWinFspDriverSafe(
                   ActiveWinFspDriverProbeResult::Found,
                   2, 2, 26215, 0,
                   2, 2, 26215, 0,
                   2, 1, 25156, 0),
               "An old preexisting active WinFsp driver must be rejected before any driver API call") &&
           Require(
               !IsPreexistingActiveWinFspDriverSafe(
                   ActiveWinFspDriverProbeResult::Failed,
                   2, 2, 26215, 0,
                   2, 2, 26215, 0,
                   0, 0, 0, 0),
               "An indeterminate active-driver probe must fail closed") &&
           Require(
               !RequiresRestartForWinFspRuntimeFileTimes(999, 999, 1000) &&
                   RequiresRestartForWinFspRuntimeFileTimes(1000, 999, 1000) &&
                   RequiresRestartForWinFspRuntimeFileTimes(999, 1001, 1000),
               "WinFsp runtime files created during the current boot must require a restart") &&
           Require(
               candidates[0] == L"C:\\Program Files\\WinFsp\\bin\\winfsp-x64.dll" &&
                   candidates[1] == L"C:\\Program Files (x86)\\WinFsp\\bin\\winfsp-x64.dll",
               "FsHost should use Bootstrap's WinFsp locations and must not load a working-directory DLL") &&
           Require(
               NormalizeDriverBinaryPath(L"\\??\\D:\\WinFsp\\winfsp-x64.sys") ==
                   std::filesystem::path(L"D:\\WinFsp\\winfsp-x64.sys"),
               "SCM NT-path driver names should resolve to a normal drive path") &&
           Require(
               windows_directory_length > 0 &&
                   windows_directory_length < windows_directory.size() &&
                   NormalizeDriverBinaryPath(
                       L"\\SystemRoot\\System32\\drivers\\winfsp-x64.sys") ==
                       expected_system_driver,
               "SCM SystemRoot driver names should resolve beneath the Windows directory") &&
           Require(
               NormalizeDriverBinaryPath(L"\"\\??\\D:\\WinFsp\\winfsp-x64.sys\"") ==
                   std::filesystem::path(L"D:\\WinFsp\\winfsp-x64.sys"),
               "Quoted SCM driver paths should be normalized before version inspection") &&
           Require(
               NormalizeDriverBinaryPath(L"\"unterminated").empty(),
               "Malformed quoted SCM driver paths must fail closed") &&
           Require(
               IsWinFspDriverServiceName(L"WinFsp+20260210T063018Z") &&
                   IsWinFspDriverServiceName(L"winfsp+candidate") &&
                   !IsWinFspDriverServiceName(L"WinFs") &&
                   !IsWinFspDriverServiceName(L"OtherDriver"),
               "Only WinFsp filesystem-driver service names should be inspected");
}

bool TestWinFspCleanStartupStartsVerifiedDriver()
{
    const auto expected_driver_path = std::filesystem::path(L"D:\\WinFsp\\winfsp-x64.sys");
    std::uint16_t major = 0;
    std::uint16_t minor = 0;
    std::uint16_t build = 0;
    std::uint16_t revision = 0;
    std::filesystem::path active_driver_path;

    g_winfsp_probe_results = { ActiveWinFspDriverProbeResult::Found };
    g_winfsp_probe_index = 0;
    g_winfsp_start_calls = 0;
    g_winfsp_start_status = STATUS_SUCCESS;
    const auto started_result = EnsureActiveWinFspDriverAvailable(
        ActiveWinFspDriverProbeResult::NotFound,
        ProbeWinFspDriverForStartupTest,
        StartWinFspServiceForStartupTest,
        expected_driver_path,
        major,
        minor,
        build,
        revision,
        active_driver_path,
        2,
        std::chrono::milliseconds{0});
    if (!Require(
            started_result == ActiveWinFspDriverProbeResult::Found &&
                g_winfsp_start_calls == 1 &&
                g_winfsp_probe_index == 1,
            "A clean WinFsp startup should explicitly start the service once and verify the active driver"))
    {
        return false;
    }

    g_winfsp_probe_results.clear();
    g_winfsp_probe_index = 0;
    g_winfsp_start_calls = 0;
    g_winfsp_start_status = STATUS_UNSUCCESSFUL;
    const auto failed_start_result = EnsureActiveWinFspDriverAvailable(
        ActiveWinFspDriverProbeResult::NotFound,
        ProbeWinFspDriverForStartupTest,
        StartWinFspServiceForStartupTest,
        expected_driver_path,
        major,
        minor,
        build,
        revision,
        active_driver_path,
        2,
        std::chrono::milliseconds{0});
    if (!Require(
            failed_start_result == ActiveWinFspDriverProbeResult::Failed &&
                g_winfsp_start_calls == 1 &&
                g_winfsp_probe_index == 0,
            "A failed WinFsp service start must fail closed without probing an unstarted driver"))
    {
        return false;
    }

    g_winfsp_probe_results = {
        ActiveWinFspDriverProbeResult::NotFound,
        ActiveWinFspDriverProbeResult::NotFound,
    };
    g_winfsp_probe_index = 0;
    g_winfsp_start_calls = 0;
    g_winfsp_start_status = STATUS_SUCCESS;
    return Require(
        EnsureActiveWinFspDriverAvailable(
            ActiveWinFspDriverProbeResult::NotFound,
            ProbeWinFspDriverForStartupTest,
            StartWinFspServiceForStartupTest,
            expected_driver_path,
            major,
            minor,
            build,
            revision,
            active_driver_path,
            2,
            std::chrono::milliseconds{0}) == ActiveWinFspDriverProbeResult::Failed,
        "A WinFsp service that never publishes a verified active driver must fail closed");
}

bool TestWinFspActiveDriverRequiresExactBinaryIdentity()
{
    std::error_code ec;
    const auto run_root = std::filesystem::temp_directory_path(ec) /
        "ApfsAccess" /
        "fs-host-semantics" /
        (L"winfsp-driver-identity-" + std::to_wstring(GetTickCount64()));
    std::filesystem::create_directories(run_root, ec);
    if (!Require(!ec, "WinFsp identity test should create its temporary directory"))
    {
        return false;
    }
    ScopeExit cleanup{[&]() { std::filesystem::remove_all(run_root, ec); }};

    const auto installed_path = run_root / "installed.sys";
    const auto active_copy_path = run_root / "active-copy.sys";
    const auto mismatched_path = run_root / "mismatched.sys";
    {
        std::ofstream installed(installed_path, std::ios::binary);
        std::ofstream active_copy(active_copy_path, std::ios::binary);
        std::ofstream mismatched(mismatched_path, std::ios::binary);
        installed << "verified-winfsp-driver";
        active_copy << "verified-winfsp-driver";
        mismatched << "different-winfsp-driver";
    }

    return Require(
               AreWinFspDriverBinariesIdentical(installed_path, active_copy_path),
               "An active SxS copy should match an identical verified installed driver") &&
           Require(
               !AreWinFspDriverBinariesIdentical(installed_path, mismatched_path),
               "A same-version active driver with different bytes must fail identity validation") &&
           Require(
               !AreWinFspDriverBinariesIdentical(installed_path, run_root / "missing.sys"),
               "An unreadable active driver identity must fail closed");
}

bool LaunchSelectedShutdownChildAndExpectExit(
    const wchar_t* selected_test,
    DWORD expected_exit_code,
    DWORD timeout_ms,
    const char* failure_message)
{
    std::array<wchar_t, 32768> executable_buffer{};
    const auto executable_length = GetModuleFileNameW(
        nullptr,
        executable_buffer.data(),
        static_cast<DWORD>(executable_buffer.size()));
    if (executable_length == 0 || executable_length >= executable_buffer.size())
    {
        return Require(false, "Shutdown subprocess test should resolve its executable path");
    }

    const std::wstring executable(executable_buffer.data(), executable_length);
    auto command_line = QuoteAcceptedWriteKillArgument(executable) + L" " + selected_test;
    std::vector<wchar_t> mutable_command_line(command_line.begin(), command_line.end());
    mutable_command_line.push_back(L'\0');

    STARTUPINFOW startup_info{};
    startup_info.cb = sizeof(startup_info);
    PROCESS_INFORMATION process_info{};
    auto process_job = TakeWinHandle(CreateJobObjectW(nullptr, nullptr));
    JOBOBJECT_EXTENDED_LIMIT_INFORMATION job_limits{};
    job_limits.BasicLimitInformation.LimitFlags = JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;
    if (!process_job ||
        !SetInformationJobObject(
            static_cast<HANDLE>(process_job.get()),
            JobObjectExtendedLimitInformation,
            &job_limits,
            sizeof(job_limits)))
    {
        return Require(false, "Shutdown subprocess test should create its child job");
    }

    if (!CreateProcessW(
            executable.c_str(),
            mutable_command_line.data(),
            nullptr,
            nullptr,
            FALSE,
            CREATE_NO_WINDOW | CREATE_SUSPENDED,
            nullptr,
            nullptr,
            &startup_info,
            &process_info))
    {
        return Require(false, "Shutdown subprocess test should create its child process");
    }

    ScopeExit cleanup{[&]()
    {
        process_job.reset();
        if (WaitForSingleObject(process_info.hProcess, 0) == WAIT_TIMEOUT)
        {
            (void)TerminateProcess(process_info.hProcess, 0xEF);
            (void)WaitForSingleObject(process_info.hProcess, 5'000);
        }
        CloseHandle(process_info.hThread);
        CloseHandle(process_info.hProcess);
    }};

    if (!AssignProcessToJobObject(
            static_cast<HANDLE>(process_job.get()),
            process_info.hProcess) ||
        ResumeThread(process_info.hThread) == static_cast<DWORD>(-1))
    {
        return Require(false, "Shutdown subprocess test should contain and resume its child");
    }

    if (WaitForSingleObject(process_info.hProcess, timeout_ms) != WAIT_OBJECT_0)
    {
        return Require(false, failure_message);
    }

    DWORD exit_code = STILL_ACTIVE;
    return Require(
        GetExitCodeProcess(process_info.hProcess, &exit_code) && exit_code == expected_exit_code,
        failure_message);
}

