bool WaitForGroupedAcceptanceParticipants(
    const MountContext& context,
    std::uint32_t participants,
    std::chrono::milliseconds timeout = std::chrono::seconds(2))
{
    const auto deadline = std::chrono::steady_clock::now() + timeout;
    while (context.grouped_acceptance_waiting_participants.load(std::memory_order_acquire) != participants &&
           std::chrono::steady_clock::now() < deadline)
    {
        std::this_thread::yield();
    }
    return context.grouped_acceptance_waiting_participants.load(std::memory_order_acquire) == participants;
}

bool TestGroupedDeferredAcceptanceIsAbsorbedByHardBoundary()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
    SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", L"1");
    SetEnvironmentVariableW(L"APFSACCESS_ENABLE_GROUPED_DEFERRED_ACCEPTANCE", L"1");
    SetEnvironmentVariableW(L"APFSACCESS_DISABLE_GROUPED_DEFERRED_ACCEPTANCE", nullptr);
    SetEnvironmentVariableW(L"APFSACCESS_DISABLE_DEFERRED_INDEX_PERSISTENCE", nullptr);
    ScopeExit clear_grouped_env{[]()
    {
        SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_ENABLE_GROUPED_DEFERRED_ACCEPTANCE", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_DISABLE_GROUPED_DEFERRED_ACCEPTANCE", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_DISABLE_DEFERRED_INDEX_PERSISTENCE", nullptr);
    }};

    std::error_code ec;
    const auto run_root = std::filesystem::temp_directory_path(ec) /
        "ApfsAccess" /
        "fs-host-semantics" /
        (L"grouped-hard-boundary-" + std::to_wstring(GetTickCount64()));
    std::filesystem::create_directories(run_root, ec);
    if (!Require(!ec, "Grouped hard-boundary test should create temp directory"))
    {
        return false;
    }

    MountContext context{};
    ConfigureGroupedAcceptanceTestContext(
        context,
        run_root,
        "grouped-hard-boundary-volume",
        1,
        5000);
    context.test_forced_native_commit_status =
        apfsaccess::rw::MetadataStore::CommitStatus::Committed;
    ScopeExit cleanup{[&]()
    {
        RequestGroupedDeferredAcceptanceFinish(&context);
        StopDeferredCommitWorker(&context);
        context.tx_manager.reset();
        context.payload_spool.reset();
        std::filesystem::remove_all(run_root, ec);
    }};

    if (!Require(
            StageGroupedAcceptancePayloadForTest(
                context,
                L"\\grouped-hard-boundary.bin",
                7201,
                std::byte{0x31}),
            "Grouped hard-boundary test should stage payload"))
    {
        return false;
    }

    auto grouped = std::async(std::launch::async, [&]()
    {
        return RunGroupedAcceptanceForTest(context);
    });
    if (!Require(
            WaitForGroupedAcceptanceParticipants(context, 1),
            "Grouped hard-boundary test should enter the collection window"))
    {
        RequestGroupedDeferredAcceptanceFinish(&context);
        WaitForGroupedFutureOrExit(grouped, "Grouped hard-boundary cleanup should finish promptly");
        return false;
    }

    NTSTATUS boundary_status = STATUS_UNSUCCESSFUL;
    bool finalized = false;
    {
        MutationCallbackScope boundary_scope(&context);
        boundary_status = DrainNativeMutationsByPolicy(&context, L"Flush");
        finalized = NT_SUCCESS(boundary_status) &&
            FinalizeMutationJournalBestEffort(&context, L"Flush");
    }

    const bool completed_before_window =
        grouped.wait_for(std::chrono::milliseconds(750)) == std::future_status::ready;
    if (!completed_before_window)
    {
        RequestGroupedDeferredAcceptanceFinish(&context);
    }
    const auto result = grouped.get();
    bool deferred_requested = false;
    {
        std::lock_guard<std::mutex> lock(context.deferred_commit_mutex);
        deferred_requested = context.deferred_commit_requested;
    }
    const auto watermarks = context.tx_manager->Watermarks();

    return Require(NT_SUCCESS(boundary_status) && finalized, "Hard boundary should durably finalize grouped work") &&
           Require(completed_before_window, "Hard boundary should seal grouped acceptance without waiting for its timer") &&
           Require(result.accepted && result.request_handled, "Grouped participant should observe hard-boundary absorption") &&
           Require(!deferred_requested, "Absorbed grouped work should not schedule a duplicate deferred commit") &&
           Require(
               watermarks.accepted_sequence == result.accepted_sequence &&
                   watermarks.apfs_durable_sequence == result.accepted_sequence &&
                   watermarks.cleanup_sequence == result.accepted_sequence,
               "Hard boundary should converge all durability watermarks through the grouped target");
#else
    return true;
#endif
}

bool TestShutdownDrainFinishesGroupedDeferredAcceptance()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
    SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", L"1");
    SetEnvironmentVariableW(L"APFSACCESS_ENABLE_GROUPED_DEFERRED_ACCEPTANCE", L"1");
    SetEnvironmentVariableW(L"APFSACCESS_DISABLE_GROUPED_DEFERRED_ACCEPTANCE", nullptr);
    SetEnvironmentVariableW(L"APFSACCESS_DISABLE_DEFERRED_INDEX_PERSISTENCE", nullptr);
    ScopeExit clear_grouped_env{[]()
    {
        SetEnvironmentVariableW(L"APFSACCESS_DISABLE_CONTENT_WRITEBACK", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_DEFER_CLOSE_COMMITS", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_ENABLE_GROUPED_DEFERRED_ACCEPTANCE", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_DISABLE_GROUPED_DEFERRED_ACCEPTANCE", nullptr);
        SetEnvironmentVariableW(L"APFSACCESS_DISABLE_DEFERRED_INDEX_PERSISTENCE", nullptr);
    }};

    std::error_code ec;
    const auto run_root = std::filesystem::temp_directory_path(ec) /
        "ApfsAccess" /
        "fs-host-semantics" /
        (L"grouped-shutdown-" + std::to_wstring(GetTickCount64()));
    std::filesystem::create_directories(run_root, ec);
    if (!Require(!ec, "Grouped shutdown test should create temp directory"))
    {
        return false;
    }

    MountContext context{};
    ConfigureGroupedAcceptanceTestContext(
        context,
        run_root,
        "grouped-shutdown-volume",
        1,
        5000);
    context.args.write_commit_timeout_seconds = 2;
    context.test_forced_native_commit_status =
        apfsaccess::rw::MetadataStore::CommitStatus::Committed;
    ScopeExit cleanup{[&]()
    {
        RequestGroupedDeferredAcceptanceFinish(&context);
        StopDeferredCommitWorker(&context);
        context.tx_manager.reset();
        context.payload_spool.reset();
        std::filesystem::remove_all(run_root, ec);
    }};

    if (!Require(
            StageGroupedAcceptancePayloadForTest(
                context,
                L"\\grouped-shutdown.bin",
                7301,
                std::byte{0x41}),
            "Grouped shutdown test should stage payload"))
    {
        return false;
    }

    auto grouped = std::async(std::launch::async, [&]()
    {
        return RunGroupedAcceptanceForTest(context);
    });
    if (!Require(
            WaitForGroupedAcceptanceParticipants(context, 1),
            "Grouped shutdown test should enter the collection window"))
    {
        RequestGroupedDeferredAcceptanceFinish(&context);
        WaitForGroupedFutureOrExit(grouped, "Grouped shutdown cleanup should finish promptly");
        return false;
    }

    const auto drain_started = std::chrono::steady_clock::now();
    const bool callback_drain_ok = BeginMutationShutdownDrain(&context);
    const auto drain_elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(
        std::chrono::steady_clock::now() - drain_started);
    const bool completed_during_drain =
        grouped.wait_for(std::chrono::milliseconds(750)) == std::future_status::ready;
    if (!completed_during_drain)
    {
        RequestGroupedDeferredAcceptanceFinish(&context);
    }
    const auto result = grouped.get();

    StopDeferredCommitWorker(&context);
    const auto shutdown_status = DrainNativeMutationsByPolicy(&context, L"Shutdown");
    const bool finalized = NT_SUCCESS(shutdown_status) &&
        FinalizeMutationJournalBestEffort(&context, L"Shutdown");
    const auto watermarks = context.tx_manager->Watermarks();

    return Require(callback_drain_ok, "Shutdown callback drain should finish a grouped close") &&
           Require(completed_during_drain, "Shutdown should seal grouped acceptance instead of waiting for its timer") &&
           Require(drain_elapsed < std::chrono::seconds(1), "Grouped shutdown drain should finish promptly") &&
           Require(result.accepted && result.request_handled, "Grouped close should publish durable acceptance before shutdown continues") &&
           Require(
               context.active_foreground_mutation_callbacks.load(std::memory_order_acquire) == 0,
               "Shutdown callback drain should leave no grouped foreground callback active") &&
           Require(NT_SUCCESS(shutdown_status) && finalized, "Shutdown should checkpoint and clean accepted grouped work") &&
           Require(
               watermarks.accepted_sequence == result.accepted_sequence &&
                   watermarks.apfs_durable_sequence == result.accepted_sequence &&
                   watermarks.cleanup_sequence == result.accepted_sequence,
               "Shutdown should converge grouped acceptance through cleanup");
#else
    return true;
#endif
}

