bool TestRecoveryMarkerCacheRejectsReplacedPathObject()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    std::error_code ec;
    const auto run_root = (std::filesystem::temp_directory_path() / L"ApfsAccessRecoveryMarkerTests") /
        (L"replaced-path-cache-" + std::to_wstring(GetCurrentProcessId()) + L"-" + std::to_wstring(GetTickCount64()));
    std::filesystem::create_directories(run_root, ec);
    if (!Require(!ec, "Replaced marker-path cache test should create its D-drive scratch root"))
    {
        return false;
    }
    ScopeExit cleanup{[&]() { std::filesystem::remove_all(run_root, ec); }};

    const auto load_file_id = [](const std::filesystem::path& path, FILE_ID_INFO& id) -> bool
    {
        HANDLE handle = CreateFileW(
            path.wstring().c_str(),
            FILE_READ_ATTRIBUTES,
            FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
            nullptr,
            OPEN_EXISTING,
            FILE_ATTRIBUTE_NORMAL,
            nullptr);
        if (handle == INVALID_HANDLE_VALUE)
        {
            return false;
        }
        const auto loaded = GetFileInformationByHandleEx(handle, FileIdInfo, &id, sizeof(id)) != FALSE;
        CloseHandle(handle);
        return loaded;
    };
    const auto same_file_id = [](const FILE_ID_INFO& left, const FILE_ID_INFO& right) -> bool
    {
        return left.VolumeSerialNumber == right.VolumeSerialNumber &&
               std::memcmp(left.FileId.Identifier, right.FileId.Identifier, sizeof(left.FileId.Identifier)) == 0;
    };

    MountContext context{};
    const auto marker_path = run_root / "recovery.marker";
    const auto renamed_path = run_root / "recovery.original";
    RecoveryMarkerState dirty{};
    dirty.dirty = true;
    dirty.last_commit_xid = 29;
    if (!Require(PersistRecoveryMarkerState(&context, marker_path, dirty),
            "Replaced marker-path cache test should persist its initial marker") ||
        !Require(MoveFileExW(marker_path.wstring().c_str(), renamed_path.wstring().c_str(), 0) != FALSE,
            "Replaced marker-path cache test should rename the cached marker away"))
    {
        return false;
    }

    {
        std::ofstream replacement(marker_path, std::ios::binary | std::ios::trunc);
        replacement << "dirty=1\nlastCommitXid=29\n";
        if (!Require(replacement.good(),
                "Replaced marker-path cache test should create a same-content replacement"))
        {
            return false;
        }
    }

    FILE_ID_INFO replacement_id{};
    if (!Require(load_file_id(marker_path, replacement_id),
            "Replaced marker-path cache test should identify the replacement object"))
    {
        return false;
    }

    FILE_ID_INFO repaired_id{};
    RecoveryMarkerState repaired{};
    return Require(PersistRecoveryMarkerState(&context, marker_path, dirty),
               "A matching cache entry must repair a replaced marker path") &&
           Require(load_file_id(marker_path, repaired_id),
               "The repaired marker path should expose a file identity") &&
           Require(!same_file_id(replacement_id, repaired_id),
               "Repeated persistence must replace the different file object at the marker path") &&
           Require(RecoveryMarkerCacheIsValid(&context, marker_path),
               "Repeated persistence must refresh the cache to the repaired marker object") &&
           Require(TryLoadRecoveryMarkerState(marker_path, repaired) &&
                       repaired.dirty &&
                       repaired.last_commit_xid == dirty.last_commit_xid,
               "The repaired marker path must retain the requested state");
#else
    return true;
#endif
}

