struct AdmissionPauseHookState
{
    inline static std::mutex started_mutex{};
    inline static std::condition_variable started_cv{};
    inline static bool started = false;
    inline static std::mutex release_mutex{};
    inline static std::condition_variable release_cv{};
    inline static bool release_flag = false;

    static void WaitForRelease(MountContext*)
    {
        {
            std::lock_guard<std::mutex> lock(started_mutex);
            started = true;
        }
        started_cv.notify_all();
        std::unique_lock<std::mutex> lock(release_mutex);
        release_cv.wait(lock, [] { return release_flag; });
    }
};

struct AdmissionPauseFirstHookState
{
    inline static std::mutex mutex{};
    inline static std::condition_variable cv{};
    inline static bool paused = false;
    inline static bool release_allowed = false;
    inline static std::size_t pause_count = 0;

    static void Reset()
    {
        std::lock_guard<std::mutex> lock(mutex);
        paused = false;
        release_allowed = false;
        pause_count = 0;
    }

    static void PauseFirstOnly(MountContext*)
    {
        {
            std::lock_guard<std::mutex> lock(mutex);
            ++pause_count;
            if (pause_count > 1)
            {
                return;
            }
            paused = true;
        }
        cv.notify_all();
        std::unique_lock<std::mutex> lock(mutex);
        cv.wait(lock, [] { return release_allowed; });
    }

    static void Release()
    {
        {
            std::lock_guard<std::mutex> lock(mutex);
            release_allowed = true;
        }
        cv.notify_all();
    }
};

bool TestShutdownDrainWaitsForAdmissionMidFlight()
{
    MountContext context{};
    context.mutation_admission_state.store(0, std::memory_order_release);
    context.active_foreground_mutation_callbacks.store(0, std::memory_order_release);

    AdmissionPauseHookState::started = false;
    AdmissionPauseHookState::release_flag = false;
    g_mutation_admission_pause_hook = &AdmissionPauseHookState::WaitForRelease;

    bool scope_acquired = false;
    std::atomic<bool> admission_completed = false;
    std::thread admission_thread([&]()
    {
        ExternalMutationRequestScope scope(&context);
        scope_acquired = scope.Acquired();
        admission_completed.store(true, std::memory_order_release);
    });

    bool admitted_into_pause = false;
    {
        std::unique_lock<std::mutex> lock(AdmissionPauseHookState::started_mutex);
        admitted_into_pause = AdmissionPauseHookState::started_cv.wait_for(
            lock, std::chrono::seconds(5), [] { return AdmissionPauseHookState::started; });
    }
    g_mutation_admission_pause_hook = nullptr;
    if (!Require(
            admitted_into_pause,
            "Shutdown drain admission test should reach the pause point"))
    {
        {
            std::lock_guard<std::mutex> lock(AdmissionPauseHookState::release_mutex);
            AdmissionPauseHookState::release_flag = true;
        }
        AdmissionPauseHookState::release_cv.notify_all();
        admission_thread.join();
        return false;
    }

    std::atomic<bool> drain_completed = false;
    bool drain_ok = false;
    std::thread drain_thread([&]()
    {
        drain_ok = BeginMutationShutdownDrain(&context);
        drain_completed.store(true, std::memory_order_release);
    });

    std::this_thread::sleep_for(std::chrono::milliseconds(250));
    const auto drain_returned_while_admission_pending =
        drain_completed.load(std::memory_order_acquire);
    {
        std::lock_guard<std::mutex> lock(AdmissionPauseHookState::release_mutex);
        AdmissionPauseHookState::release_flag = true;
    }
    AdmissionPauseHookState::release_cv.notify_all();

    admission_thread.join();
    drain_thread.join();

    if (!Require(
            !drain_returned_while_admission_pending,
            "Shutdown drain must not complete while a mutation admission is mid-flight"))
    {
        return false;
    }
    if (!Require(
            drain_completed.load(std::memory_order_acquire),
            "Shutdown drain should complete after the admitted callback finishes"))
    {
        return false;
    }
    if (!Require(
            drain_ok,
            "Shutdown drain should succeed after the admitted callback finishes"))
    {
        return false;
    }
    if (!Require(
            scope_acquired,
            "Mutation admission linearized before the drain flag must be acquired"))
    {
        return false;
    }
    if (!Require(
            admission_completed.load(std::memory_order_acquire),
            "Admission thread should complete"))
    {
        return false;
    }
    return Require(
        MutationAdmissionCount(context.mutation_admission_state.load(std::memory_order_acquire)) == 0,
        "External mutation counter should return to zero after drain");
}

