bool TestCleanHydratedReadSkipsPayloadSpoolProbe()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    SetEnvironmentVariableW(L"APFSACCESS_PERF_COUNTERS", L"1");
    ScopeExit clear_perf_env{[]()
    {
        SetEnvironmentVariableW(L"APFSACCESS_PERF_COUNTERS", nullptr);
    }};

    std::error_code ec;
    const auto run_root = std::filesystem::temp_directory_path(ec) /
        "ApfsAccess" /
        "fs-host-semantics" /
        (L"clean-read-bypass-" + std::to_wstring(GetTickCount64()));
    std::filesystem::create_directories(run_root, ec);
    if (!Require(!ec, "Clean-read bypass test should create its temp directory"))
    {
        return false;
    }
    ScopeExit cleanup{[&]() { std::filesystem::remove_all(run_root, ec); }};

    MountContext context{};
    context.args.volume = L"Main";
    context.owned_metadata_store = std::make_unique<apfsaccess::rw::MetadataStore>(
        apfsaccess::rw::MetadataStore::VolumeContext{
            (run_root / "unused.apfs.img").wstring(),
            L"Main"});
    context.metadata_store = context.owned_metadata_store.get();
    context.payload_spool_volume_identity = "unit-clean-read-bypass";
    context.payload_spool = std::make_unique<apfsaccess::rw::PayloadSpool>(
        apfsaccess::rw::PayloadSpool::Options{
            run_root / "payload-spool",
            context.payload_spool_volume_identity,
            1024 * 1024});

    auto file = MakeNode(L"\\clean.bin", false, false);
    file->file_size = 4;
    const std::vector<std::byte> expected{
        std::byte{'C'}, std::byte{'L'}, std::byte{'E'}, std::byte{'N'}};
    const auto file_path = run_root / "clean.bin";
    if (!Require(WriteFileBytes(file_path, expected), "Clean-read bypass test should seed the hydrated file"))
    {
        return false;
    }

    OpenContext open_context{};
    open_context.node = file;
    open_context.allow_read_data = true;
    open_context.file = CreateFileW(
        file_path.wstring().c_str(),
        GENERIC_READ,
        FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
        nullptr,
        OPEN_EXISTING,
        FILE_ATTRIBUTE_NORMAL,
        nullptr);
    if (!Require(open_context.file != INVALID_HANDLE_VALUE, "Clean-read bypass test should open the hydrated file"))
    {
        return false;
    }
    ScopeExit close_handle{[&]()
    {
        if (open_context.file != INVALID_HANDLE_VALUE)
        {
            CloseHandle(open_context.file);
            open_context.file = INVALID_HANDLE_VALUE;
        }
    }};

    context.pending_native_writes = false;
    context.recovery_active = false;
    context.write_degraded = false;
    context.perf_metadata_mutex_wait.count.store(0, std::memory_order_relaxed);

    auto fs = BuildFileSystem(&context);
    std::array<std::byte, 4> read_buffer{};
    ULONG read_done = 0;
    const auto read_status = CB_Read(
        &fs,
        &open_context,
        read_buffer.data(),
        0,
        static_cast<ULONG>(read_buffer.size()),
        &read_done);

    return Require(read_status == STATUS_SUCCESS, "Clean-read bypass test should read successfully") &&
           Require(read_done == read_buffer.size(), "Clean-read bypass test should report the full read") &&
           Require(
               std::equal(read_buffer.begin(), read_buffer.end(), expected.begin()),
               "Clean-read bypass test should preserve hydrated bytes") &&
           Require(
               context.perf_metadata_mutex_wait.count.load(std::memory_order_relaxed) == 0,
               "Clean hydrated reads should not probe the payload spool identity");
#else
    return true;
#endif
}

bool TestHydratedRangeReadZeroFillsOnlyEofTail()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    MountContext context{};
    context.args.volume = L"Main";
    SeedRoot(context);
    if (!Require(PrepareUnitHydrationRoot(context, L"hydrated-range-zero-tail"), "Hydrated range test should prepare cache root"))
    {
        return false;
    }

    std::error_code ec;
    auto file = MakeNode(L"\\payload.bin", false, false);
    file->file_size = 8;
    context.nodes.emplace(Key(file->path), file);
    AddChildName(context.nodes.at(Key(L"\\"))->children, L"payload.bin");
    const std::vector<std::byte> payload{
        std::byte{'0'}, std::byte{'1'}, std::byte{'2'}, std::byte{'3'},
        std::byte{'4'}, std::byte{'5'}, std::byte{'6'}, std::byte{'7'}};
    if (!Require(WriteFileBytes(HydrationPath(&context, *file), payload), "Hydrated range test should seed the cache"))
    {
        std::filesystem::remove_all(context.session_root, ec);
        return false;
    }

    g_hydrated_range_zero_fill_bytes_for_test = 0;
    std::array<std::byte, 4> fully_backed{};
    const auto fully_backed_ok = ReadHydratedPayloadRangeForPath(
        &context,
        file->path,
        2,
        std::span<std::byte>(fully_backed.data(), fully_backed.size()));
    if (!Require(fully_backed_ok, "Hydrated range test should read a fully backed range") ||
        !Require(
            std::equal(fully_backed.begin(), fully_backed.end(), payload.begin() + 2),
            "Hydrated range test should preserve fully backed bytes") ||
        !Require(
            g_hydrated_range_zero_fill_bytes_for_test == 0,
            "Fully backed hydration reads should not clear the destination first"))
    {
        std::filesystem::remove_all(context.session_root, ec);
        return false;
    }

    g_hydrated_range_zero_fill_bytes_for_test = 0;
    std::array<std::byte, 6> eof_tail{};
    eof_tail.fill(std::byte{0x7f});
    const auto eof_tail_ok = ReadHydratedPayloadRangeForPath(
        &context,
        file->path,
        6,
        std::span<std::byte>(eof_tail.data(), eof_tail.size()));
    const std::array<std::byte, 6> expected_tail{
        std::byte{'6'}, std::byte{'7'}, std::byte{0}, std::byte{0}, std::byte{0}, std::byte{0}};
    std::filesystem::remove_all(context.session_root, ec);
    return Require(eof_tail_ok, "Hydrated range test should read an EOF-overrun range") &&
           Require(eof_tail == expected_tail, "Hydrated range test should zero only the EOF tail") &&
           Require(
               g_hydrated_range_zero_fill_bytes_for_test == 4,
               "Hydrated range test should account only for EOF-tail zero filling");
#else
    return true;
#endif
}

bool TestPreWalCrashOrphanedPayloadRecoversCleanReadWrite()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    MountContext context{};
    context.args.volume = L"Main";
    context.args.readwrite = true;
    context.args.write_backend = L"Native";
    context.args.write_recovery_policy = L"FailClosed";
    context.native_write_enabled = true;
    context.overlay_write_enabled = false;
    SeedRoot(context);
    std::array<std::byte, 16> security{};
    SeedSecurity(context, security);
    if (!Require(
            PrepareUnitHydrationRoot(context, L"pre-wal-orphan-recovery"),
            "Pre-WAL orphan test should prepare its scratch root") ||
        !Require(
            ConfigureUnitRecoveryMarker(context, L"pre-wal-orphan-recovery"),
            "Pre-WAL orphan test should configure its recovery marker"))
    {
        return false;
    }

    std::error_code ec;
    ScopeExit cleanup{[&]()
    {
        context.payload_spool.reset();
        context.tx_manager.reset();
        std::filesystem::remove_all(context.session_root, ec);
        std::filesystem::remove(context.recovery_marker_file, ec);
    }};

    const auto image_path = context.session_root / "pre-wal-orphan-recovery.apfs.img";
    if (!Require(
            CreateSyntheticApfsContainerForTest(image_path),
            "Pre-WAL orphan test should create a synthetic APFS image"))
    {
        return false;
    }
    context.args.device = image_path.wstring();

    apfsaccess::rw::MetadataStore::VolumeContext rw_context
    {
        image_path.wstring(),
        L"Main",
    };
    context.owned_metadata_store = std::make_unique<apfsaccess::rw::MetadataStore>(std::move(rw_context));
    context.metadata_store = context.owned_metadata_store.get();
    {
        std::lock_guard<std::mutex> metadata_lock(context.metadata_mutex);
        if (!Require(
                context.metadata_store->LoadContainerSuperblocks(),
                "Pre-WAL orphan test should load container superblocks") ||
            !Require(
                context.metadata_store->LoadObjectMap(),
                "Pre-WAL orphan test should load the object map") ||
            !Require(
                context.metadata_store->LoadSpacemanState(),
                "Pre-WAL orphan test should load spaceman state") ||
            !Require(
                context.metadata_store->PrepareNativeWritePath(),
                "Pre-WAL orphan test should prepare the clean native write path"))
        {
            return false;
        }
    }

    const auto clean_checkpoint_xid = ResolveCleanRecoveryCheckpointXid(*context.metadata_store);
    if (!Require(
            clean_checkpoint_xid.has_value(),
            "Pre-WAL orphan test should resolve a clean checkpoint xid"))
    {
        return false;
    }
    context.runtime_last_commit_xid = clean_checkpoint_xid;
    context.pending_native_writes = true;
    context.recovery_active = true;
    if (!Require(
            UpdateRecoveryMarkerBestEffort(&context, true),
            "Pre-WAL orphan test should persist the interrupted-session marker"))
    {
        return false;
    }

    context.payload_spool_volume_identity = "unit-pre-wal-orphan-recovery";
    const auto spool_root = context.session_root / "payload-spool";
    context.tx_manager = std::make_unique<apfsaccess::rw::TransactionManager>(L"Conservative");
    context.tx_manager->SetVolumeIdentity(L"unit-pre-wal-orphan-recovery");
    context.tx_manager->SetJournalPath((spool_root / "write-ahead.wal").wstring());
    if (!Require(
            context.tx_manager->RecoveryStateValid() &&
                !context.tx_manager->HasUnappliedAcceptedWork() &&
                context.tx_manager->CanClearRecoveryState(),
            "Pre-WAL orphan test should begin with a valid empty WAL"))
    {
        return false;
    }

    {
        apfsaccess::rw::PayloadSpool interrupted({
            spool_root,
            context.payload_spool_volume_identity,
            1024 * 1024,
            1024 * 1024,
            1024,
        });
        const std::array<std::byte, 8> payload{
            std::byte{'o'}, std::byte{'r'}, std::byte{'p'}, std::byte{'h'},
            std::byte{'a'}, std::byte{'n'}, std::byte{'e'}, std::byte{'d'},
        };
        if (!Require(
                interrupted.Append({
                    context.payload_spool_volume_identity,
                    77,
                    1,
                    0,
                    1,
                    std::span<const std::byte>(payload.data(), payload.size()),
                }),
                "Pre-WAL orphan test should append payload before WAL acceptance"))
        {
            return false;
        }
    }

    context.payload_spool = std::make_unique<apfsaccess::rw::PayloadSpool>(
        apfsaccess::rw::PayloadSpool::Options{
            spool_root,
            context.payload_spool_volume_identity,
            1024 * 1024,
            1024 * 1024,
            1024,
        });
    const auto before = context.payload_spool->SnapshotCounters();
    ReconcilePayloadSpoolRecoveryAfterMetadataBootstrap(context, true);
    const auto after = context.payload_spool->SnapshotCounters();

    return Require(
               before.recovery_required && before.spool_bytes == 8 && before.dirty_range_count == 0,
               "Pre-WAL orphan test should reproduce unindexed payload recovery evidence") &&
           Require(
               !after.recovery_required && after.spool_bytes == 0 && after.dirty_range_count == 0,
               "Pre-WAL orphan test should discard only the unreferenced payload bytes") &&
           Require(
               !context.pending_native_writes && !context.recovery_active && !context.write_degraded,
               "Pre-WAL orphan test should clear the resolved recovery state") &&
           Require(
               context.native_write_enabled && !context.overlay_write_enabled,
               "Pre-WAL orphan test should preserve a healthy native RW mount");
#else
    return true;
#endif
}

