bool TestRecoveryRootOverrideSurvivesTempChange()
{
    const auto previous_recovery = _wgetenv(L"APFSACCESS_RECOVERY_ROOT");
    const auto previous_temp = _wgetenv(L"TEMP");
    const bool had_recovery = previous_recovery != nullptr;
    const bool had_temp = previous_temp != nullptr;
    const std::wstring saved_recovery = previous_recovery ? previous_recovery : L"";
    const std::wstring saved_temp = previous_temp ? previous_temp : L"";
    ScopeExit restore_environment{[&]()
    {
        SetEnvironmentVariableW(
            L"APFSACCESS_RECOVERY_ROOT",
            had_recovery ? saved_recovery.c_str() : nullptr);
        SetEnvironmentVariableW(
            L"TEMP",
            had_temp ? saved_temp.c_str() : nullptr);
    }};

    const std::wstring stable_root =
        (std::filesystem::temp_directory_path() /
         L"ApfsAccessUnitRecovery" /
         L"stable-root").wstring();
    if (!Require(
            SetEnvironmentVariableW(L"APFSACCESS_RECOVERY_ROOT", stable_root.c_str()) != 0,
            "Recovery-root test should set its explicit D-drive root") ||
        !Require(
            SetEnvironmentVariableW(L"TEMP", L"C:\\Temp\\apfs-test-a") != 0,
            "Recovery-root test should set its first temporary root"))
    {
        return false;
    }

    const auto first = ResolveRecoveryRoot();
    if (!Require(
            SetEnvironmentVariableW(L"TEMP", L"C:\\Temp\\apfs-test-b") != 0,
            "Recovery-root test should change its temporary root"))
    {
        return false;
    }
    const auto second = ResolveRecoveryRoot();
    return Require(first == stable_root, "Recovery-root override should take precedence over TEMP") &&
           Require(second == stable_root, "Recovery-root path should remain stable when TEMP changes");
}

bool TestBuildWinFspMountPointUsesGlobalDriveForExplorer()
{
    if (!Require(BuildWinFspMountPoint(L"E:") == L"\\\\.\\E:", "Drive-letter mounts should use Mount Manager syntax"))
    {
        return false;
    }

    if (!Require(BuildWinFspMountPoint(L"q:") == L"\\\\.\\Q:", "Drive-letter global mount syntax should normalize casing"))
    {
        return false;
    }

    if (!Require(BuildWinFspMountPoint(L"E:\\") == L"\\\\.\\E:", "Drive-root mounts should use Mount Manager syntax"))
    {
        return false;
    }

    if (!Require(BuildWinFspMountPoint(L"e:/") == L"\\\\.\\E:", "Slash-normalized drive roots should use Mount Manager syntax"))
    {
        return false;
    }

    return Require(
        BuildWinFspMountPoint(L"C:\\apfs-mount") == L"C:\\apfs-mount",
        "Directory mount points should not be rewritten as global drives");
}

bool TestVolumeParamsUseExplorerFriendlyCleanupFlags()
{
    MountContext context{};
    context.overlay_write_enabled = true;
    context.args.volume = L"Main";
    context.reported_allocation_unit_bytes = 4096;

    FSP_FSCTL_VOLUME_PARAMS params{};
    FILETIME now{};
    GetSystemTimeAsFileTime(&now);
    ConfigureVolumeParamsForExplorer(context, now, params);

    if (!Require(params.PostCleanupWhenModifiedOnly == 0, "Volume params should deliver cleanup for every user handle so Explorer/Office locks clear promptly"))
    {
        return false;
    }
    if (!Require(params.FlushAndPurgeOnCleanup != 0, "Volume params should purge cached file data on cleanup for Explorer/Office compatibility"))
    {
        return false;
    }
    if (!Require(
            params.PostDispositionWhenNecessaryOnly == 0,
            "Volume params should request all disposition callbacks so recursive directory deletes reach FsHost reliably"))
    {
        return false;
    }
    if (!Require(params.SupportsPosixUnlinkRename != 0, "Volume params should preserve POSIX-style unlink semantics for compatible shell handles"))
    {
        return false;
    }
    return Require(params.PersistentAcls == 0, "Volume params should not advertise persistent ACLs while APFS Access returns synthetic security descriptors");
}

bool TestVolumeParamsReflectSelectedApfsCaseMode()
{
    MountContext context{};
    context.overlay_write_enabled = true;
    context.args.volume = L"Main";
    context.reported_allocation_unit_bytes = 4096;
    FILETIME now{};
    GetSystemTimeAsFileTime(&now);

    FSP_FSCTL_VOLUME_PARAMS params{};
    context.args.incompatible_features = 0;
    ConfigureVolumeParamsForExplorer(context, now, params);
    if (!Require(
            params.CaseSensitiveSearch != 0,
            "Case-sensitive APFS volumes must be advertised as case-sensitive to WinFsp"))
    {
        return false;
    }

    context.args.incompatible_features = apfsaccess::catalog::kIncompatCaseInsensitive;
    ConfigureVolumeParamsForExplorer(context, now, params);
    return Require(
        params.CaseSensitiveSearch == 0,
        "Case-insensitive APFS volumes must be advertised as case-insensitive to WinFsp");
}

bool TestPathKeysReflectSelectedApfsNamePolicy()
{
    MountContext exact{};
    exact.args.incompatible_features = 0;
    if (!Require(
            Key(&exact, L"\\File.txt") != Key(&exact, L"\\file.txt"),
            "Case-sensitive APFS path keys must preserve case distinctions") ||
        !Require(
            Key(&exact, L"\\caf\u00e9.txt") !=
                Key(&exact, L"\\cafe\u0301.txt"),
            "Normalization-sensitive APFS path keys must preserve normalization distinctions"))
    {
        return false;
    }

    MountContext normalized{};
    normalized.args.incompatible_features =
        apfsaccess::catalog::kIncompatNormalizationInsensitive;
    if (!Require(
            Key(&normalized, L"\\File.txt") != Key(&normalized, L"\\file.txt"),
            "Normalization-only APFS path keys must remain case-sensitive") ||
        !Require(
            Key(&normalized, L"\\caf\u00e9.txt") ==
                Key(&normalized, L"\\cafe\u0301.txt"),
            "Normalization-insensitive APFS path keys must coalesce canonical equivalents"))
    {
        return false;
    }

    MountContext folded{};
    folded.args.incompatible_features =
        apfsaccess::catalog::kIncompatCaseInsensitive;
    Node exact_directory{};
    exact_directory.is_directory = true;
    exact_directory.incompatible_features = 0;
    AddChildName(exact_directory, L"File.txt");
    AddChildName(exact_directory, L"file.txt");
    Node folded_directory{};
    folded_directory.is_directory = true;
    folded_directory.incompatible_features =
        apfsaccess::catalog::kIncompatCaseInsensitive;
    AddChildName(folded_directory, L"File.txt");
    AddChildName(folded_directory, L"file.txt");

    return Require(
               Key(&folded, L"\\File.txt") == Key(&folded, L"\\file.txt"),
               "Case-insensitive APFS path keys must coalesce case variants") &&
           Require(
               Key(&folded, L"\\caf\u00e9.txt") ==
               Key(&folded, L"\\cafe\u0301.txt"),
               "Case-insensitive APFS path keys must also normalize canonical equivalents") &&
           Require(
               exact_directory.children.size() == 2,
               "Case-sensitive APFS directories must retain case-distinct children") &&
           Require(
               folded_directory.children.size() == 1,
               "Case-insensitive APFS directories must coalesce case-equivalent children");
}

bool TestCallbacksRoundTripCaseSensitiveApfsNames()
{
    MountContext context{};
    context.overlay_write_enabled = true;
    context.args.incompatible_features = 0;
    std::array<std::byte, 16> security{};
    SeedSecurity(context, security);

    auto root = std::make_shared<Node>();
    SetNodePath(&context, *root, L"\\");
    root->hydration_key = root->path_key;
    root->is_directory = true;
    root->loaded = true;
    root->timestamp = UtcNow();
    context.nodes.emplace(Key(&context, root->path), root);

    auto fs = BuildFileSystem(&context);
    const auto create = [&](const wchar_t* path) -> bool
    {
        PVOID open_context = nullptr;
        FSP_FSCTL_FILE_INFO info{};
        const auto status = CB_Create(
            &fs,
            const_cast<PWSTR>(path),
            FILE_NON_DIRECTORY_FILE,
            FILE_READ_DATA | FILE_WRITE_DATA | DELETE,
            0,
            nullptr,
            0,
            &open_context,
            &info);
        if (open_context != nullptr)
        {
            CB_Close(&fs, open_context);
        }
        return status == STATUS_SUCCESS;
    };

    if (!Require(create(L"\\File.txt"),
            "Case-sensitive callback create must accept the first case variant") ||
        !Require(create(L"\\file.txt"),
            "Case-sensitive callback create must accept a distinct case variant"))
    {
        return false;
    }

    PVOID rename_context = nullptr;
    FSP_FSCTL_FILE_INFO info{};
    if (!Require(
            CB_Open(
                &fs,
                const_cast<PWSTR>(L"\\File.txt"),
                FILE_NON_DIRECTORY_FILE,
                DELETE,
                &rename_context,
                &info) == STATUS_SUCCESS && rename_context != nullptr,
            "Case-sensitive callback rename must open the exact source"))
    {
        return false;
    }
    const auto rename_status = CB_Rename(
        &fs,
        rename_context,
        const_cast<PWSTR>(L"\\File.txt"),
        const_cast<PWSTR>(L"\\caf\u00e9.txt"),
        FALSE);
    CB_Close(&fs, rename_context);
    if (!Require(rename_status == STATUS_SUCCESS,
            "Case-sensitive callback rename must preserve the Unicode target") ||
        !Require(context.nodes.find(Key(&context, L"\\caf\u00e9.txt")) != context.nodes.end(),
            "Renamed Unicode target must remain addressable by its exact spelling") ||
        !Require(context.nodes.find(Key(&context, L"\\cafe\u0301.txt")) == context.nodes.end(),
            "Normalization-sensitive lookup must not alias a decomposed spelling") ||
        !Require(context.nodes.find(Key(&context, L"\\file.txt")) != context.nodes.end(),
            "Case-distinct sibling must survive the other sibling's rename"))
    {
        return false;
    }

    const auto remove = [&](const wchar_t* path) -> bool
    {
        PVOID open_context = nullptr;
        FSP_FSCTL_FILE_INFO delete_info{};
        if (CB_Open(
                &fs,
                const_cast<PWSTR>(path),
                FILE_NON_DIRECTORY_FILE,
                DELETE,
                &open_context,
                &delete_info) != STATUS_SUCCESS ||
            open_context == nullptr)
        {
            return false;
        }
        const auto status = CB_SetDelete(
            &fs, open_context, const_cast<PWSTR>(path), TRUE);
        if (status == STATUS_SUCCESS)
        {
            CB_Cleanup(
                &fs, open_context, const_cast<PWSTR>(path), FspCleanupDelete);
        }
        CB_Close(&fs, open_context);
        return status == STATUS_SUCCESS;
    };

    return Require(remove(L"\\caf\u00e9.txt"),
               "Case-sensitive callback delete must remove the renamed Unicode target") &&
           Require(remove(L"\\file.txt"),
               "Case-sensitive callback delete must remove the remaining case variant") &&
           Require(context.nodes.size() == 1 && root->children.empty(),
               "Case-sensitive create/rename/delete round trip must leave only the root");
}

bool TestNamedStreamCopyCompatibility()
{
    MountContext context{};
    context.overlay_write_enabled = true;
    context.args.volume = L"Main";
    context.reported_allocation_unit_bytes = 4096;
    SeedRoot(context);

    auto file = MakeNode(L"\\Antigravity-x64.exe", false, false);
    file->file_size = 143772040;
    context.nodes.emplace(Key(file->path), file);

    OpenContext open_context{};
    open_context.node = file;
    auto fs = BuildFileSystem(&context);

    std::array<std::byte, 256> buffer{};
    ULONG transferred = 0;
    const auto status = CB_GetStreamInfo(
        &fs,
        &open_context,
        buffer.data(),
        static_cast<ULONG>(buffer.size()),
        &transferred);
    if (!Require(status == STATUS_SUCCESS, "GetStreamInfo should succeed so Explorer can copy files with source metadata streams without warning"))
    {
        return false;
    }
    if (!Require(transferred > 0, "GetStreamInfo should report at least the default data stream"))
    {
        return false;
    }

    const auto* stream_info = reinterpret_cast<const FSP_FSCTL_STREAM_INFO*>(buffer.data());
    if (!Require(stream_info->StreamSize == file->file_size, "Default stream info should report file size"))
    {
        return false;
    }

    const auto stream_name_chars = (stream_info->Size - sizeof(FSP_FSCTL_STREAM_INFO)) / sizeof(WCHAR);
    const std::wstring stream_name(stream_info->StreamNameBuf, stream_name_chars);
    if (!Require(stream_name.empty(), "WinFsp requires an empty name for the default data stream"))
    {
        return false;
    }

    FSP_FSCTL_VOLUME_PARAMS volume_params{};
    FILETIME now{};
    GetSystemTimeAsFileTime(&now);
    ConfigureVolumeParamsForExplorer(context, now, volume_params);
    return Require(volume_params.NamedStreams == 1, "Volume params should advertise named stream compatibility to Explorer");
}

bool TestNamedStreamDeleteIsolation(bool concurrent_only = false)
{
    // Real local NTFS ADS and callbacks, with no mount or native staging mock.
    // The runner selects the scratch volume through TEMP/TMP.
    const auto run = [](unsigned scenario) -> bool
    {
        MountContext context{};
        context.overlay_write_enabled = true;
        context.args.volume = L"Main";
        context.reported_allocation_unit_bytes = 4096;
        context.session_root = std::filesystem::temp_directory_path() /
            (L"named-stream-delete-isolation-" + std::to_wstring(GetCurrentProcessId()) + L"-" +
                std::to_wstring(GetTickCount64()) + L"-" + std::to_wstring(scenario));
        context.cache_root = context.session_root / L"hydrate";
        std::error_code ec;
        std::filesystem::create_directories(context.cache_root, ec);
        if (!Require(!ec, "Stream delete fixture should create its D: cache")) return false;
        ScopeExit remove_fixture{[&]() {
            std::error_code ignored;
            std::filesystem::remove_all(context.session_root, ignored);
        }};
        SeedRoot(context);
        auto root = context.nodes.at(Key(L"\\"));
        auto file = MakeNode(L"\\stream-owner.bin", false, false);
        const auto base_bytes = BuildPatternPayloadForTest(97, 0x21);
        const auto alpha_bytes = BuildPatternPayloadForTest(31, 0x62);
        const auto beta_bytes = BuildPatternPayloadForTest(53, 0xb3);
        file->file_size = base_bytes.size();
        AddChildName(root->children, L"stream-owner.bin");
        context.nodes.emplace(Key(file->path), file);
        const auto base_storage = HydrationPath(&context, *file);
        if (!Require(WriteFileBytes(base_storage, base_bytes), "Seed distinct nonempty base data")) return false;
        ScopeExit restore_attributes{[&]() { SetFileAttributesW(base_storage.c_str(), FILE_ATTRIBUTE_NORMAL); }};
        auto fs = BuildFileSystem(&context);
        constexpr auto alpha_path = L"\\stream-owner.bin:alpha";
        constexpr auto beta_path = L"\\stream-owner.bin:beta";
        FSP_FSCTL_FILE_INFO info{};
        PVOID target = nullptr;
        PVOID retained = nullptr;
        PVOID extra = nullptr;
        ScopeExit close_handles{[&]() {
            if (target) CB_Close(&fs, target);
            if (retained) CB_Close(&fs, retained);
            if (extra) CB_Close(&fs, extra);
        }};
        const auto close = [&](PVOID& handle) { CB_Close(&fs, handle); handle = nullptr; };
        const auto open = [&](const wchar_t* path, UINT32 access, PVOID& handle,
                              UINT32 options = FILE_NON_DIRECTORY_FILE) {
            return CB_Open(&fs, const_cast<PWSTR>(path), options, access, &handle, &info);
        };
        const auto seed = [&](const wchar_t* path, const std::vector<std::byte>& bytes) {
            PVOID handle = nullptr;
            const auto status = CB_Create(&fs, const_cast<PWSTR>(path), FILE_NON_DIRECTORY_FILE,
                FILE_READ_DATA | FILE_WRITE_DATA | DELETE, 0, nullptr, 0, &handle, &info);
            if (!Require(status == STATUS_SUCCESS && handle, "Create the real local ADS")) return false;
            ScopeExit release{[&]() { CB_Close(&fs, handle); }};
            ULONG done = 0;
            return Require(CB_Write(&fs, handle, const_cast<std::byte*>(bytes.data()), 0,
                static_cast<ULONG>(bytes.size()), FALSE, FALSE, &done, &info) == STATUS_SUCCESS &&
                done == bytes.size(), "Seed distinct nonempty ADS bytes through Write");
        };
        if (!seed(alpha_path, alpha_bytes) || !seed(beta_path, beta_bytes)) return false;
        const auto read = [&](PVOID handle, const std::vector<std::byte>& expected) {
            std::vector<std::byte> bytes(expected.size() + 8);
            ULONG done = 0;
            const auto status = CB_Read(&fs, handle, bytes.data(), 0, static_cast<ULONG>(bytes.size()), &done);
            bytes.resize(done);
            return Require(status == STATUS_SUCCESS && bytes == expected, "Callback read must preserve exact bytes");
        };
        const auto read_path = [&](const wchar_t* path, const std::vector<std::byte>& expected) {
            PVOID handle = nullptr;
            const auto status = open(path, FILE_READ_DATA, handle);
            ScopeExit release{[&]() { if (handle) CB_Close(&fs, handle); }};
            return Require(status == STATUS_SUCCESS && handle, "Surviving path must reopen") && read(handle, expected);
        };
        const auto invariants = [&](bool alpha_visible) {
            if (!Require(context.nodes.size() == 2 && FindNode(&context, file->path) == file &&
                    root->children == std::vector<std::wstring>{L"stream-owner.bin"} &&
                    file->file_size == base_bytes.size() && !file->namespace_detached &&
                    !file->delete_pending && !file->delete_latched && file->delete_intent_count == 0 &&
                    !file->delete_requested_after_children && !file->caller_delete_retry_required,
                    "Stream lifecycle must never mark or remove the base inode/namespace")) return false;
            const auto local_base = CreateFileW(base_storage.c_str(), GENERIC_READ,
                FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE, nullptr, OPEN_EXISTING,
                FILE_ATTRIBUTE_NORMAL, nullptr);
            const auto physical_bytes = ReadHandleBytes(local_base, static_cast<DWORD>(base_bytes.size() + 8));
            if (local_base != INVALID_HANDLE_VALUE) CloseHandle(local_base);
            if (!Require(physical_bytes == base_bytes, "Physical default stream bytes must remain exact") ||
                !read_path(file->path.c_str(), base_bytes) || !read_path(beta_path, beta_bytes)) return false;
            OpenContext base_open{};
            base_open.node = file;
            std::array<std::byte, 1024> storage{};
            ULONG transferred = 0;
            if (!Require(CB_GetStreamInfo(&fs, &base_open, storage.data(), static_cast<ULONG>(storage.size()),
                    &transferred) == STATUS_SUCCESS, "Enumerate surviving streams")) return false;
            bool alpha_found = false, beta_found = false, base_found = false;
            for (ULONG cursor = 0; cursor < transferred;)
            {
                const auto* entry = reinterpret_cast<const FSP_FSCTL_STREAM_INFO*>(storage.data() + cursor);
                if (!Require(entry->Size >= sizeof(FSP_FSCTL_STREAM_INFO) && entry->Size <= transferred - cursor,
                        "Stream enumeration must have valid entries")) return false;
                const std::wstring name(entry->StreamNameBuf,
                    (entry->Size - sizeof(FSP_FSCTL_STREAM_INFO)) / sizeof(WCHAR));
                if (name == L"alpha") alpha_found = entry->StreamSize == alpha_bytes.size();
                if (name == L"beta") beta_found = entry->StreamSize == beta_bytes.size();
                if (name.empty()) base_found = entry->StreamSize == base_bytes.size();
                cursor += entry->Size;
            }
            return Require(base_found && beta_found && alpha_found == alpha_visible,
                "Enumeration must retain base/beta and must not resurrect deleted alpha");
        };
        const auto missing_alpha = [&]() {
            PVOID handle = nullptr;
            const auto status = open(alpha_path, FILE_READ_DATA, handle);
            if (handle) CB_Close(&fs, handle);
            const auto local = CreateFileW(HydrationStreamPath(&context, *file, L":alpha:$DATA").c_str(),
                GENERIC_READ, FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE, nullptr,
                OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, nullptr);
            const auto error = GetLastError();
            if (local != INVALID_HANDLE_VALUE) CloseHandle(local);
            return Require(status == STATUS_OBJECT_NAME_NOT_FOUND && !handle &&
                local == INVALID_HANDLE_VALUE && error == ERROR_FILE_NOT_FOUND,
                "Final Close must actually remove alpha from Win32 storage and callback opens");
        };
        if (scenario >= 29)
        {
            // Six schedules: ADS/ADS, base/ADS, ADS/base, base/base,
            // then fast base Close followed by a newly latched deletion with
            // an ADS or ordinary final context. No timing-dependent sleeps.
            const auto variant = scenario - 29;
            const bool drain_overlap = variant >= 6;
            const auto kinds = drain_overlap ? variant - 6 : variant;
            const bool first_ads = kinds == 0 || kinds == 2;
            const bool second_ads = kinds == 0 || kinds == 1 || kinds == 4;
            const bool late_latch = variant == 4 || variant == 5;
            if (!Require(open(first_ads ? alpha_path : file->path.c_str(), FILE_READ_DATA, retained) == STATUS_SUCCESS &&
                    open(second_ads ? beta_path : file->path.c_str(), FILE_READ_DATA, extra) == STATUS_SUCCESS,
                    "Open the two concurrent contexts") ||
                !invariants(true) || !read(retained, first_ads ? alpha_bytes : base_bytes) ||
                !read(extra, second_ads ? beta_bytes : base_bytes)) return false;
            CB_Cleanup(&fs, retained, nullptr, 0);
            CB_Cleanup(&fs, extra, nullptr, 0);
            if (!late_latch)
            {
                if (!Require(open(file->path.c_str(), DELETE, target,
                        FILE_NON_DIRECTORY_FILE | FILE_DELETE_ON_CLOSE) == STATUS_SUCCESS,
                        "Open the independent base delete owner")) return false;
                CB_Cleanup(&fs, target, nullptr, 0);
                close(target);
            }

            std::promise<void> paused_promise, release_promise;
            auto paused = paused_promise.get_future();
            auto release = release_promise.get_future().share();
            const auto first = static_cast<OpenContext*>(retained);
            g_close_retirement_test_hook = [&](OpenContext* closing) {
                if (closing != first) return;
                paused_promise.set_value();
                release.wait();
            };
            ScopeExit clear_hook{[&]() { g_close_retirement_test_hook = {}; }};
            std::thread closer([&]() { CB_Close(&fs, first); });
            retained = nullptr;
            ScopeExit join_close{[&]() { release_promise.set_value(); closer.join(); }};
            // Timeout is only a deadlock diagnostic; successful ordering comes
            // entirely from the explicit hook rendezvous.
            if (!Require(paused.wait_for(std::chrono::seconds(10)) == std::future_status::ready,
                    "First Close must reach the unlocked retirement decision")) return false;
            if (late_latch)
            {
                if (!Require(open(file->path.c_str(), DELETE, target,
                        FILE_NON_DIRECTORY_FILE | FILE_DELETE_ON_CLOSE) == STATUS_SUCCESS,
                        "Open base delete owner after the first fast-close decision")) return false;
                CB_Cleanup(&fs, target, nullptr, 0);
                close(target);
            }
            if (!Require(file->delete_latched && context.nodes.contains(Key(file->path)),
                    "Retained second context preserves the independent base latch") ||
                !read(extra, second_ads ? beta_bytes : base_bytes)) return false;
            const auto physical = CreateFileW(base_storage.c_str(), GENERIC_READ,
                FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE, nullptr, OPEN_EXISTING,
                FILE_ATTRIBUTE_NORMAL, nullptr);
            const auto actual = ReadHandleBytes(physical, static_cast<DWORD>(base_bytes.size() + 8));
            if (physical != INVALID_HANDLE_VALUE) CloseHandle(physical);
            if (!Require(actual == base_bytes && file->file_size == base_bytes.size(),
                    "Paused close preserves base bytes and stream isolation")) return false;
            if (drain_overlap)
                context.mutation_admission_state.store(kMutationAdmissionDrainFlag, std::memory_order_release);
            close(extra);
            // Unblock/join before inspecting final counts, including the payload
            // pins held through completion of both callbacks.
            release_promise.set_value();
            closer.join();
            join_close.callback = {};
            // Subsequent opens may reuse the first context's address.
            g_close_retirement_test_hook = {};
            if (drain_overlap)
            {
                context.mutation_admission_state.store(0, std::memory_order_release);
                return Require(file->live_context_count == 0 && file->open_handle_count == 0 &&
                    file->closing_context_count == 0 && !file->cancel_delete_after_closes &&
                    context.open_write_handle_count == 0,
                    "Final retirement resolves drain cancellation after all closer pins disappear") &&
                    invariants(true) && read_path(alpha_path, alpha_bytes);
            }
            PVOID missing = nullptr;
            const auto status = open(file->path.c_str(), FILE_READ_DATA, missing);
            if (missing) CB_Close(&fs, missing);
            return Require(context.nodes.size() == 1 && !context.nodes.contains(Key(file->path)) &&
                !HasChildName(root->children, L"stream-owner.bin") && file->namespace_detached &&
                !file->delete_latched && !file->delete_pending && file->delete_intent_count == 0 &&
                file->live_context_count == 0 && file->open_handle_count == 0 &&
                file->closing_context_count == 0 && context.open_write_handle_count == 0 &&
                !std::filesystem::exists(base_storage) && !context.named_stream_sizes.contains(Key(file->path)) &&
                status == STATUS_OBJECT_NAME_NOT_FOUND && !missing,
                "Concurrent final closes must complete the base unlink and retire all accounting");
        }
        if (scenario >= 20)
        {
            if (!Require(open(alpha_path, FILE_READ_DATA, retained) == STATUS_SUCCESS && retained,
                    "Retain ADS before authorizing base deletion")) return false;
            if (scenario == 28)
            {
                if (!Require(open(beta_path, FILE_READ_DATA, extra) == STATUS_SUCCESS && extra &&
                        open(file->path.c_str(), DELETE, target, FILE_NON_DIRECTORY_FILE | FILE_DELETE_ON_CLOSE) == STATUS_SUCCESS && target,
                        "Retain two ADS handles before opening the independent base deletion owner")) return false;
                CB_Cleanup(&fs, target, const_cast<PWSTR>(file->path.c_str()), 0);
                CB_Cleanup(&fs, retained, const_cast<PWSTR>(alpha_path), 0);
                CB_Cleanup(&fs, extra, const_cast<PWSTR>(beta_path), 0);
                close(target);
                if (!Require(file->delete_latched && file->open_handle_count == 0 && file->live_context_count == 2,
                        "Both ADS contexts have released Cleanup accounting but remain actually live")) return false;
                close(retained);
                if (!Require(context.nodes.at(Key(file->path)) == file && file->delete_latched &&
                        file->live_context_count == 1 && std::filesystem::exists(base_storage),
                        "First cleaned ADS Close must retain base unlink for the last actual context") ||
                    !read(extra, beta_bytes)) return false;
                close(extra);
                return Require(!context.nodes.contains(Key(file->path)) && file->namespace_detached &&
                        file->live_context_count == 0 && !std::filesystem::exists(base_storage),
                        "Last actual ADS Close completes only the previously latched base unlink");
            }
            if (scenario == 22 || scenario == 23)
                if (!Require(open(scenario == 22 ? beta_path : file->path.c_str(), FILE_READ_DATA, extra) ==
                        STATUS_SUCCESS && extra, "Retain an additional stream/base reader")) return false;
            const bool explicit_disposition = scenario == 24 || scenario == 27;
            if (!Require(open(file->path.c_str(), DELETE, target, FILE_NON_DIRECTORY_FILE |
                    (explicit_disposition ? 0 : FILE_DELETE_ON_CLOSE)) == STATUS_SUCCESS && target,
                    "Open base deletion owner after retaining ADS")) return false;
            if (explicit_disposition)
            {
                if (!Require(CB_SetDelete(&fs, target, const_cast<PWSTR>(file->path.c_str()), TRUE) == STATUS_SUCCESS,
                        "Authorize base disposition independently of ADS")) return false;
                if (scenario == 24 && !Require(CB_SetDelete(&fs, target,
                        const_cast<PWSTR>(file->path.c_str()), FALSE) == STATUS_SUCCESS,
                        "Cancel base disposition before Cleanup latches it")) return false;
            }
            CB_Cleanup(&fs, target, const_cast<PWSTR>(file->path.c_str()), 0);
            if (scenario == 27)
            {
                // Pending intent alone is owned by the still-live base context.
                // ADS Close must not turn it into a latch or run base planning.
                if (!Require(file->delete_pending && !file->delete_latched && file->delete_intent_count == 1,
                        "Unlatched base intent must remain distinct from accepted Cleanup deletion")) return false;
                const auto planning_visits = g_can_remove_node_visit_count_for_test;
                close(retained);
                if (!Require(context.nodes.at(Key(file->path)) == file && !file->namespace_detached &&
                        file->delete_pending && !file->delete_latched && file->delete_intent_count == 1 &&
                        std::filesystem::exists(base_storage) && g_can_remove_node_visit_count_for_test == planning_visits,
                        "ADS Close must not complete another context's unlatched intent")) return false;
                close(target);
            }
            else
            {
                close(target);
                if (scenario == 24)
                {
                    CB_Cleanup(&fs, retained, const_cast<PWSTR>(file->path.c_str()), 0);
                    close(retained);
                    return Require(file->open_handle_count == 0 && file->live_context_count == 0,
                        "Cancelled mixed deletion must release all accounting") &&
                        invariants(true) && read_path(alpha_path, alpha_bytes);
                }
                if (!Require(context.nodes.at(Key(file->path)) == file && file->delete_latched &&
                        file->delete_pending && file->delete_intent_count == 0 &&
                        file->open_handle_count == (extra ? 2u : 1u) && std::filesystem::exists(base_storage),
                        "Base Close must retain latched deletion while ADS readers remain") ||
                    !read(retained, alpha_bytes)) return false;
                if (scenario == 26)
                {
                    // Model namespace replacement while the old ADS context is
                    // retained. A same-path lookup cannot authorize its successor.
                    auto replacement = MakeNode(file->path, false, false);
                    replacement->file_size = file->file_size;
                    replacement->delete_latched = true;
                    replacement->delete_pending = true;
                    file->namespace_detached = true;
                    context.nodes[Key(file->path)] = replacement;
                    const auto parent_children = root->children;
                    const auto planning_visits = g_can_remove_node_visit_count_for_test;
                    CB_Cleanup(&fs, retained, const_cast<PWSTR>(file->path.c_str()), 0);
                    close(retained);
                    return Require(context.nodes.at(Key(file->path)) == replacement &&
                        replacement->delete_latched && replacement->delete_pending && !replacement->namespace_detached &&
                        root->children == parent_children && std::filesystem::exists(base_storage) &&
                        g_can_remove_node_visit_count_for_test == planning_visits &&
                        file->open_handle_count == 0 && file->live_context_count == 0,
                        "Stale ADS context must not complete deletion of a same-path replacement");
                }
                if (scenario == 25)
                {
                    auto* stream = static_cast<OpenContext*>(retained);
                    CloseHandle(stream->file.exchange(INVALID_HANDLE_VALUE));
                    if (!Require(CB_SetDelete(&fs, retained, nullptr, TRUE) == STATUS_INVALID_HANDLE,
                            "Invalid ADS backing handle cannot authorize deletion")) return false;
                }
                if (scenario != 21 && scenario != 25)
                {
                    CB_Cleanup(&fs, retained, const_cast<PWSTR>(alpha_path), 0);
                    if (!Require(context.nodes.at(Key(file->path)) == file && file->delete_latched &&
                            file->open_handle_count == (extra ? 1u : 0u),
                            "Ordinary ADS Cleanup releases accounting without originating base deletion") ||
                        !read(retained, alpha_bytes)) return false;
                }
                close(retained); // Also exercise Close without any stream Cleanup.
                if (extra)
                {
                    if (!Require(context.nodes.at(Key(file->path)) == file && file->delete_latched &&
                            file->delete_pending && file->open_handle_count == 1 && std::filesystem::exists(base_storage),
                            "First ADS Close must preserve deletion until the additional reader releases") ||
                        !read(extra, scenario == 22 ? beta_bytes : base_bytes)) return false;
                    close(extra);
                }
            }
            PVOID missing = nullptr;
            const auto status = open(file->path.c_str(), FILE_READ_DATA, missing);
            if (missing) CB_Close(&fs, missing);
            return Require(context.nodes.size() == 1 && !context.nodes.contains(Key(file->path)) &&
                !HasChildName(root->children, L"stream-owner.bin") && file->namespace_detached &&
                !file->delete_pending && !file->delete_latched && file->delete_intent_count == 0 &&
                file->open_handle_count == 0 && file->live_context_count == 0 &&
                !std::filesystem::exists(base_storage) && !context.named_stream_sizes.contains(Key(file->path)) &&
                status == STATUS_OBJECT_NAME_NOT_FOUND && !missing,
                "Final retained Close must complete authorized base deletion, removing namespace, data and ADS cache");
        }
        const bool delete_on_close = scenario == 2 || scenario == 3 || scenario == 10;
        if (scenario == 3 && !Require(open(alpha_path, FILE_READ_DATA, retained) == STATUS_SUCCESS,
                "Retain independent reader before delete-on-close open")) return false;
        if (!Require(open(alpha_path, FILE_READ_DATA | DELETE, target,
                FILE_NON_DIRECTORY_FILE | (delete_on_close ? FILE_DELETE_ON_CLOSE : 0)) == STATUS_SUCCESS && target,
                "Open deletion target")) return false;
        auto* stream = static_cast<OpenContext*>(target);
        if (!Require(!stream->delete_on_cleanup && !stream->delete_on_close_requested,
                "ADS open must never use base deletion flags")) return false;

        if (scenario == 0 || scenario == 10)
        {
            if (scenario == 0 &&
                (!Require(CB_CanDelete(&fs, target, const_cast<PWSTR>(alpha_path)) == STATUS_SUCCESS,
                     "CanDelete alone must succeed without arming deletion") ||
                 !invariants(true) || !read_path(alpha_path, alpha_bytes))) return false;
            if (!Require(CB_CanDelete(&fs, target, const_cast<PWSTR>(alpha_path)) == STATUS_SUCCESS,
                    "CanDelete must resolve a colon-qualified opened stream") ||
                !Require(CB_SetDelete(&fs, target, const_cast<PWSTR>(alpha_path), TRUE) == STATUS_SUCCESS,
                    "SetDelete TRUE must arm only alpha") || !invariants(false)) return false;
            // Cancellation must remain available after mutation admission is disabled.
            context.overlay_write_enabled = false;
            const auto cancelled = CB_SetDelete(&fs, target, const_cast<PWSTR>(beta_path), FALSE);
            context.overlay_write_enabled = true;
            if (!Require(cancelled == STATUS_SUCCESS, "Cancel exact handle, even with wrong callback path/read-only mount") ||
                !invariants(true)) return false;
            CB_Cleanup(&fs, target, const_cast<PWSTR>(file->path.c_str()), FspCleanupDelete);
            CB_Cleanup(&fs, target, const_cast<PWSTR>(alpha_path), FspCleanupDelete);
            if (!read(target, alpha_bytes)) return false;
            close(target);
            return invariants(true) && read_path(alpha_path, alpha_bytes);
        }
        if (scenario == 1 || scenario == 3 || scenario == 9)
        {
            if (scenario != 3)
            {
                if (!Require(open(alpha_path, FILE_READ_DATA, retained) == STATUS_SUCCESS,
                        "Retain another real callback reader")) return false;
            }
            if (scenario == 1 &&
                (!Require(CB_CanDelete(&fs, target, const_cast<PWSTR>(alpha_path)) == STATUS_SUCCESS, "CanDelete alpha") ||
                 !Require(CB_SetDelete(&fs, target, const_cast<PWSTR>(beta_path), TRUE) == STATUS_SUCCESS,
                     "Wrong FileName must still delete only the opened alpha"))) return false;
            // Adversarial Cleanup names the BASE and repeats after handle accounting
            // is released. Before the fix this latches deletion on the base Node.
            CB_Cleanup(&fs, target, const_cast<PWSTR>(file->path.c_str()), FspCleanupDelete);
            CB_Cleanup(&fs, target, const_cast<PWSTR>(beta_path), FspCleanupDelete);
            if (!invariants(false) || !read(target, alpha_bytes) || !read(retained, alpha_bytes)) return false;
            close(target);
            if (!read(retained, alpha_bytes)) return false;
            CB_Cleanup(&fs, retained, const_cast<PWSTR>(file->path.c_str()), 0);
            if (!read(retained, alpha_bytes) || !invariants(false)) return false;
            close(retained);
            return missing_alpha() && invariants(false);
        }
        if (scenario == 2)
        {
            close(target); // Safe final Close even when Cleanup was never delivered.
            return missing_alpha() && invariants(false);
        }
        if (scenario == 13)
        {
            close(target);
            const auto blocker = CreateFileW(HydrationStreamPath(&context, *file, L":alpha:$DATA").c_str(),
                GENERIC_READ, FILE_SHARE_READ | FILE_SHARE_WRITE, nullptr, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, nullptr);
            if (!Require(blocker != INVALID_HANDLE_VALUE, "Open real stream sharing blocker")) return false;
            const auto status = open(alpha_path, FILE_READ_DATA | DELETE, target,
                FILE_NON_DIRECTORY_FILE | FILE_DELETE_ON_CLOSE);
            CloseHandle(blocker);
            return Require(status == STATUS_SHARING_VIOLATION && !target,
                "Delete-on-close Open must propagate real sharing failure") &&
                invariants(true) && read_path(alpha_path, alpha_bytes);
        }
        if (scenario == 14)
        {
            close(target);
            const auto status = open(L"\\stream-owner.bin:absent", DELETE, target,
                FILE_NON_DIRECTORY_FILE | FILE_DELETE_ON_CLOSE);
            return Require(status == STATUS_OBJECT_NAME_NOT_FOUND && !target,
                "Delete-only Open must not fabricate a missing stream") && invariants(true);
        }
        if (scenario == 15)
        {
            close(target);
            const auto status = open(alpha_path, FILE_READ_DATA, target,
                FILE_NON_DIRECTORY_FILE | FILE_DELETE_ON_CLOSE);
            return Require(status == STATUS_ACCESS_DENIED && !target,
                "Delete-on-close requires DELETE access before any disposition") &&
                invariants(true) && read_path(alpha_path, alpha_bytes);
        }
        if (scenario == 16)
        {
            close(target);
            if (!Require(CB_Create(&fs, const_cast<PWSTR>(alpha_path), FILE_NON_DIRECTORY_FILE | FILE_DELETE_ON_CLOSE,
                    FILE_READ_DATA | FILE_WRITE_DATA | DELETE, 0, nullptr, 0, &target, &info) == STATUS_SUCCESS && target,
                    "Create adapter must also arm stream-specific delete-on-close")) return false;
            if (!read(target, alpha_bytes)) return false;
            CB_Cleanup(&fs, target, const_cast<PWSTR>(file->path.c_str()), FspCleanupDelete);
            close(target);
            return missing_alpha() && invariants(false);
        }
        if (scenario == 17)
        {
            if (!Require(CB_SetDelete(&fs, target, nullptr, TRUE) == STATUS_SUCCESS &&
                    CB_SetDelete(&fs, target, nullptr, FALSE) == STATUS_SUCCESS &&
                    CB_SetDelete(&fs, target, nullptr, TRUE) == STATUS_SUCCESS,
                    "A later explicit TRUE must rearm a cancelled stream disposition")) return false;
            close(target);
            return missing_alpha() && invariants(false);
        }
        if (scenario == 18)
        {
            close(target);
            if (!Require(open(file->path.c_str(), DELETE, target) == STATUS_SUCCESS && target,
                    "Open base context for adversarial colon-path callbacks")) return false;
            if (!Require(CB_CanDelete(&fs, target, const_cast<PWSTR>(alpha_path)) == STATUS_INVALID_HANDLE &&
                    CB_SetDelete(&fs, target, const_cast<PWSTR>(alpha_path), TRUE) == STATUS_INVALID_HANDLE &&
                    CB_SetDelete(&fs, nullptr, const_cast<PWSTR>(alpha_path), FALSE) == STATUS_INVALID_HANDLE,
                    "Colon-qualified deletes require an actual stream context")) return false;
            CB_Cleanup(&fs, target, const_cast<PWSTR>(alpha_path), FspCleanupDelete);
            close(target);
            return invariants(true) && read_path(alpha_path, alpha_bytes);
        }
        if (scenario == 19)
        {
            file->windows_attributes = FILE_ATTRIBUTE_READONLY;
            const auto status = CB_SetDelete(&fs, target, const_cast<PWSTR>(alpha_path), TRUE);
            file->windows_attributes.reset();
            if (!Require(status == STATUS_CANNOT_DELETE, "Reject read-only stream deletion")) return false;
            CB_Cleanup(&fs, target, const_cast<PWSTR>(file->path.c_str()), FspCleanupDelete);
            close(target);
            return invariants(true) && read_path(alpha_path, alpha_bytes);
        }

        NTSTATUS expected = STATUS_ACCESS_DENIED;
        if (scenario == 4) InitializeOpenAccess(stream, FILE_READ_DATA); // callback permission denied
        if (scenario == 5) { file->windows_attributes = FILE_ATTRIBUTE_READONLY; expected = STATUS_CANNOT_DELETE; }
        if (scenario == 6) { context.overlay_write_enabled = false; expected = STATUS_MEDIA_WRITE_PROTECTED; }
        if (scenario == 12)
        {
            if (!Require(SetFileAttributesW(base_storage.c_str(), FILE_ATTRIBUTE_READONLY),
                    "Set real Win32 read-only owner attribute")) return false;
            expected = STATUS_CANNOT_DELETE;
        }
        if (scenario == 7)
        {
            CloseHandle(stream->file.exchange(INVALID_HANDLE_VALUE));
            expected = STATUS_INVALID_HANDLE;
        }
        if (scenario == 8 || scenario == 11)
        {
            const auto replacement_path = scenario == 8
                ? std::filesystem::path(HydrationStreamPath(&context, *file, stream->stream_name)) : base_storage;
            const auto replacement = CreateFileW(replacement_path.c_str(),
                GENERIC_READ | (scenario == 11 ? DELETE : 0), FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
                nullptr, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, nullptr);
            if (!Require(replacement != INVALID_HANDLE_VALUE, "Open real denied/incorrect underlying handle")) return false;
            CloseHandle(stream->file.exchange(replacement));
            if (scenario == 11) expected = STATUS_INVALID_HANDLE;
        }
        const auto can_delete = CB_CanDelete(&fs, target, const_cast<PWSTR>(alpha_path));
        if (scenario != 8 && !Require(can_delete == expected, "CanDelete must propagate eligibility/invalid-handle failure")) return false;
        if (!Require(CB_SetDelete(&fs, target, const_cast<PWSTR>(alpha_path), TRUE) == expected,
                "SetDelete must propagate actual permission/filesystem failure") ||
            !Require(!stream->stream_delete_pending, "Failed disposition must not arm deletion")) return false;
        if (scenario == 7 || scenario == 8 || scenario == 11)
            if (!Require(CB_SetDelete(&fs, target, nullptr, FALSE) == expected,
                    "Cancellation must propagate invalid/denied backing-handle errors")) return false;
        CB_Cleanup(&fs, target, const_cast<PWSTR>(file->path.c_str()), FspCleanupDelete);
        CB_Cleanup(&fs, target, const_cast<PWSTR>(beta_path), FspCleanupDelete);
        close(target);
        context.overlay_write_enabled = true;
        file->windows_attributes.reset();
        if (scenario == 12) SetFileAttributesW(base_storage.c_str(), FILE_ATTRIBUTE_NORMAL);
        return invariants(true) && read_path(alpha_path, alpha_bytes);
    };
    bool ok = true;
    if (concurrent_only)
    {
        for (unsigned scenario = 29; scenario != 39; ++scenario)
            if (!run(scenario))
            {
                std::cerr << "[DETAIL] concurrent-close scenario " << scenario << std::endl;
                ok = false;
            }
        return ok;
    }
    for (unsigned scenario = 0; scenario != 28; ++scenario)
        if (!run(scenario))
        {
            std::cerr << "[DETAIL] named-stream-delete-isolation scenario " << scenario << std::endl;
            ok = false;
        }
    if (!run(28))
    {
        std::cerr << "[DETAIL] named-stream-delete-isolation cleaned-but-live ADS pair" << std::endl;
        ok = false;
    }
    return ok;
}

bool TestNamedStreamCreateDoesNotCreateVisibleApfsFile()
{
    MountContext context{};
    context.overlay_write_enabled = true;
    context.args.volume = L"Main";
    context.reported_allocation_unit_bytes = 4096;
    SeedRoot(context);

    auto root = context.nodes.at(Key(L"\\"));
    AddChildName(root->children, L"Antigravity-x64.exe");
    auto file = MakeNode(L"\\Antigravity-x64.exe", false, false);
    file->file_size = 12;
    context.nodes.emplace(Key(file->path), file);

    auto fs = BuildFileSystem(&context);
    PVOID out_ctx = nullptr;
    FSP_FSCTL_FILE_INFO info{};
    const auto create_status = CB_Create(
        &fs,
        const_cast<PWSTR>(L"\\Antigravity-x64.exe:LH.Identifier"),
        FILE_NON_DIRECTORY_FILE,
        FILE_WRITE_DATA | FILE_READ_DATA | FILE_WRITE_ATTRIBUTES,
        0,
        nullptr,
        0,
        &out_ctx,
        &info);
    if (!Require(create_status == STATUS_SUCCESS, "Named stream create should succeed for Explorer metadata copy compatibility"))
    {
        return false;
    }
    if (!Require(out_ctx != nullptr, "Named stream create should return an open context"))
    {
        return false;
    }

    const std::array<char, 11> payload{ 'p', 'r', 'o', 'b', 'e', '-', 's', 't', 'r', 'e', 'a' };
    ULONG done = 0;
    const auto write_status = CB_Write(
        &fs,
        out_ctx,
        const_cast<char*>(payload.data()),
        0,
        static_cast<ULONG>(payload.size()),
        FALSE,
        FALSE,
        &done,
        &info);
    if (!Require(write_status == STATUS_SUCCESS, "Named stream write should succeed"))
    {
        return false;
    }
    if (!Require(done == payload.size(), "Named stream write should report all bytes written"))
    {
        return false;
    }

    {
        std::lock_guard<std::mutex> lock(context.mutex);
        if (!Require(TryGetNodeLocked(&context, L"\\Antigravity-x64.exe:LH.Identifier") == nullptr, "Named stream writes must not create visible APFS colon-named files"))
        {
            return false;
        }
        if (!Require(std::find(root->children.begin(), root->children.end(), L"Antigravity-x64.exe:LH.Identifier") == root->children.end(), "Named stream writes must not add colon-named directory entries"))
        {
            return false;
        }
        if (!Require(file->file_size == 12, "Named stream writes must not change the base file size"))
        {
            return false;
        }
    }

    CB_Close(&fs, out_ctx);

    PVOID stream_read_ctx = nullptr;
    FSP_FSCTL_FILE_INFO read_info{};
    const auto open_status = CB_Open(
        &fs,
        const_cast<PWSTR>(L"\\Antigravity-x64.exe:LH.Identifier"),
        FILE_NON_DIRECTORY_FILE,
        FILE_READ_DATA,
        &stream_read_ctx,
        &read_info);
    if (!Require(open_status == STATUS_SUCCESS, "Named stream reopen should succeed for Explorer metadata copy round-trips"))
    {
        return false;
    }

    std::array<char, 16> read_payload{};
    ULONG read_done = 0;
    const auto read_status = CB_Read(
        &fs,
        stream_read_ctx,
        read_payload.data(),
        0,
        static_cast<ULONG>(payload.size()),
        &read_done);
    if (!Require(read_status == STATUS_SUCCESS, "Named stream read should succeed after reopen"))
    {
        CB_Close(&fs, stream_read_ctx);
        return false;
    }
    if (!Require(read_done == payload.size(), "Named stream read should return all bytes written"))
    {
        CB_Close(&fs, stream_read_ctx);
        return false;
    }
    if (!Require(std::equal(payload.begin(), payload.end(), read_payload.begin()), "Named stream payload should round-trip through the hydration sidecar"))
    {
        CB_Close(&fs, stream_read_ctx);
        return false;
    }
    CB_Close(&fs, stream_read_ctx);

    OpenContext base_open{};
    base_open.node = file;
    std::array<std::byte, 512> stream_buffer{};
    ULONG transferred = 0;
    const auto stream_status = CB_GetStreamInfo(
        &fs,
        &base_open,
        stream_buffer.data(),
        static_cast<ULONG>(stream_buffer.size()),
        &transferred);
    if (!Require(stream_status == STATUS_SUCCESS, "GetStreamInfo should succeed after writing a named stream"))
    {
        return false;
    }

    bool found_named_stream = false;
    ULONG cursor = 0;
    while (cursor < transferred)
    {
        const auto* stream_info = reinterpret_cast<const FSP_FSCTL_STREAM_INFO*>(stream_buffer.data() + cursor);
        if (stream_info->Size < sizeof(FSP_FSCTL_STREAM_INFO) ||
            stream_info->Size > transferred - cursor)
        {
            return Require(false, "Stream info entries should be packed with valid sizes");
        }

        const auto name_chars = (stream_info->Size - sizeof(FSP_FSCTL_STREAM_INFO)) / sizeof(WCHAR);
        const std::wstring stream_name(stream_info->StreamNameBuf, name_chars);
        if (stream_name == L"LH.Identifier")
        {
            found_named_stream = stream_info->StreamSize == payload.size();
        }
        cursor += stream_info->Size;
    }

    if (!Require(found_named_stream, "GetStreamInfo should enumerate the named metadata stream attached to the base file")) return false;
    PVOID overwrite_ctx = nullptr;
    if (!Require(CB_Open(&fs, const_cast<PWSTR>(L"\\Antigravity-x64.exe:LH.Identifier"),
            FILE_NON_DIRECTORY_FILE, FILE_READ_DATA | FILE_WRITE_DATA, &overwrite_ctx, &info) == STATUS_SUCCESS && overwrite_ctx,
            "named stream opens for an actual nonempty overwrite")) return false;
    ScopeExit close_overwrite{[&]() { CB_Close(&fs, overwrite_ctx); }};
    const auto* stream = static_cast<OpenContext*>(overwrite_ctx);
    LARGE_INTEGER physical_size{};
    if (!Require(GetFileSizeEx(stream->file, &physical_size) && physical_size.QuadPart == payload.size(),
            "named stream overwrite starts from independently measured nonempty bytes")) return false;
    if (!Require(CB_Overwrite(&fs, overwrite_ctx, 0, FALSE, 65536, &info) == STATUS_SUCCESS &&
            GetFileSizeEx(stream->file, &physical_size) && physical_size.QuadPart == 0 &&
            stream->stream_size == 0 &&
            context.named_stream_sizes.at(NodePathKey(&context, *file)).at(stream->stream_name) == 0 &&
            info.FileSize == 0 && info.AllocationSize == 0 && file->file_size == 12,
            "nonzero allocation does not become named-stream EOF or change the base stream")) return false;
    read_done = 99;
    return Require(CB_Read(&fs, overwrite_ctx, read_payload.data(), 0,
            static_cast<ULONG>(read_payload.size()), &read_done) == STATUS_SUCCESS && read_done == 0,
        "the overwritten named stream exposes no old payload bytes");
}

bool TestNamedStreamCreateOnStaleSpoolBackedFileKeepsPayloadReadable()
{
    MountContext context{};
    context.overlay_write_enabled = true;
    context.args.volume = L"Main";
    if (!Require(PrepareUnitHydrationRoot(context, L"stale-spool-named-stream"), "Stale spool ADS test should prepare cache root"))
    {
        return false;
    }
    SeedRoot(context);

    auto root = context.nodes.at(Key(L"\\"));
    AddChildName(root->children, L"image.png");
    auto file = MakeNode(L"\\image.png", false, false);
    const auto stale_payload = BuildPatternPayloadForTest(32, 0x31);
    file->file_size = stale_payload.size();
    context.nodes.emplace(Key(file->path), file);
    if (!Require(WriteFileBytes(HydrationPath(&context, *file), stale_payload), "Stale spool ADS test should create a local payload sidecar"))
    {
        std::error_code ec;
        std::filesystem::remove_all(context.session_root, ec);
        return false;
    }

    {
        std::lock_guard<std::mutex> lock(context.mutex);
        MarkHydrationStaleLocked(&context, file);
    }

    auto fs = BuildFileSystem(&context);
    PVOID stream_ctx = nullptr;
    FSP_FSCTL_FILE_INFO info{};
    const auto create_status = CB_Create(
        &fs,
        const_cast<PWSTR>(L"\\image.png:Zone.Identifier"),
        FILE_NON_DIRECTORY_FILE,
        FILE_WRITE_DATA | FILE_READ_DATA | FILE_WRITE_ATTRIBUTES,
        0,
        nullptr,
        0,
        &stream_ctx,
        &info);
    if (!Require(create_status == STATUS_SUCCESS, "Named stream create should succeed on a stale spool-backed base file"))
    {
        std::error_code ec;
        std::filesystem::remove_all(context.session_root, ec);
        return false;
    }

    const std::array<char, 24> zone_payload{
        '[', 'Z', 'o', 'n', 'e', 'T', 'r', 'a', 'n', 's', 'f', 'e', 'r', ']',
        '\r', '\n',
        'Z', 'o', 'n', 'e', 'I', 'd', '=', '3'
    };
    ULONG written = 0;
    const auto write_status = CB_Write(
        &fs,
        stream_ctx,
        const_cast<char*>(zone_payload.data()),
        0,
        static_cast<ULONG>(zone_payload.size()),
        FALSE,
        FALSE,
        &written,
        &info);
    if (!Require(write_status == STATUS_SUCCESS, "Named stream write should succeed on stale spool-backed base file") ||
        !Require(written == zone_payload.size(), "Named stream write should report all Zone.Identifier bytes"))
    {
        CB_Close(&fs, stream_ctx);
        std::error_code ec;
        std::filesystem::remove_all(context.session_root, ec);
        return false;
    }
    CB_Close(&fs, stream_ctx);

    bool still_stale = false;
    {
        std::lock_guard<std::mutex> lock(context.mutex);
        still_stale = IsHydrationStaleLocked(&context, file);
    }

    PVOID reopen_ctx = nullptr;
    const auto reopen_status = CB_Open(
        &fs,
        const_cast<PWSTR>(L"\\image.png:Zone.Identifier"),
        FILE_NON_DIRECTORY_FILE,
        FILE_READ_DATA,
        &reopen_ctx,
        &info);
    if (!Require(reopen_status == STATUS_SUCCESS, "Named stream should reopen after stale-base creation"))
    {
        std::error_code ec;
        std::filesystem::remove_all(context.session_root, ec);
        return false;
    }

    std::array<char, zone_payload.size()> read_payload{};
    ULONG read_done = 0;
    const auto read_status = CB_Read(
        &fs,
        reopen_ctx,
        read_payload.data(),
        0,
        static_cast<ULONG>(read_payload.size()),
        &read_done);
    CB_Close(&fs, reopen_ctx);

    std::error_code ec;
    std::filesystem::remove_all(context.session_root, ec);
    return Require(still_stale, "Named stream creation must not clear stale base-payload state") &&
           Require(read_status == STATUS_SUCCESS, "Named stream should read after reopen") &&
           Require(read_done == read_payload.size(), "Named stream read should return the full payload") &&
           Require(std::equal(zone_payload.begin(), zone_payload.end(), read_payload.begin()), "Named stream payload should round-trip while base payload remains stale");
}

bool TestLegacyNamedStreamArtifactsAreHidden()
{
    MountContext context{};
    context.overlay_write_enabled = true;
    context.args.volume = L"Main";
    SeedRoot(context);

    auto root = context.nodes.at(Key(L"\\"));
    const std::wstring artifact_name = L"ANTIGRAVITY.EXE:LH.Identifier";
    AddChildName(root->children, artifact_name);
    auto artifact = MakeNode(L"\\" + artifact_name, false, false);
    artifact->file_size = 108;
    context.nodes.emplace(Key(artifact->path), artifact);

    {
        std::lock_guard<std::mutex> lock(context.mutex);
        if (!Require(TryGetVisibleNodeLocked(&context, artifact->path) == nullptr, "Legacy colon-named stream artifacts should not resolve as visible APFS files"))
        {
            return false;
        }
    }

    OpenContext dir_context{};
    dir_context.node = root;
    dir_context.allow_list_directory = true;
    auto fs = BuildFileSystem(&context);
    context.api.AddDir = [](FSP_FSCTL_DIR_INFO* dir_info, PVOID, ULONG, PULONG done) -> BOOLEAN
    {
        if (!dir_info)
        {
            return TRUE;
        }

        if (done)
        {
            *done += dir_info->Size;
        }
        return TRUE;
    };

    std::array<std::byte, 512> buffer{};
    ULONG transferred = 0;
    const auto read_status = CB_ReadDirectory(
        &fs,
        &dir_context,
        nullptr,
        nullptr,
        buffer.data(),
        static_cast<ULONG>(buffer.size()),
        &transferred);
    if (!Require(read_status == STATUS_SUCCESS, "Directory enumeration should succeed when legacy stream artifacts are present"))
    {
        return false;
    }

    return Require(transferred == 0, "Directory enumeration should hide legacy colon-named stream artifact files");
}

bool TestMissingNamedStreamOpenFailsCleanlyWithoutBaseBytes()
{
    MountContext context{};
    context.overlay_write_enabled = true;
    context.args.volume = L"Main";
    if (!Require(PrepareUnitHydrationRoot(context, L"missing-named-stream"), "Missing named stream test should prepare cache root"))
    {
        return false;
    }
    SeedRoot(context);

    auto root = context.nodes.at(Key(L"\\"));
    AddChildName(root->children, L"document.docx");
    auto file = MakeNode(L"\\document.docx", false, false);
    const auto base_payload = BuildPatternPayloadForTest(64, 0x41);
    file->file_size = base_payload.size();
    context.nodes.emplace(Key(file->path), file);
    if (!Require(WriteFileBytes(HydrationPath(&context, *file), base_payload), "Missing named stream test should seed base file bytes"))
    {
        std::error_code ec;
        std::filesystem::remove_all(context.session_root, ec);
        return false;
    }

    auto fs = BuildFileSystem(&context);
    const std::array<const wchar_t*, 3> missing_streams
    {
        L"\\document.docx:Zone.Identifier",
        L"\\document.docx:LH.Identifier",
        L"\\document.docx:AFP_AfpInfo"
    };

    for (const auto* stream_path : missing_streams)
    {
        PVOID out_ctx = nullptr;
        FSP_FSCTL_FILE_INFO info{};
        const auto status = CB_Open(
            &fs,
            const_cast<PWSTR>(stream_path),
            FILE_NON_DIRECTORY_FILE,
            FILE_READ_DATA,
            &out_ctx,
            &info);
        if (!Require(status == STATUS_OBJECT_NAME_NOT_FOUND, "Missing ADS read-only open should report object-not-found, not device failure"))
        {
            if (out_ctx)
            {
                CB_Close(&fs, out_ctx);
            }
            std::error_code ec;
            std::filesystem::remove_all(context.session_root, ec);
            return false;
        }
        if (!Require(out_ctx == nullptr, "Missing ADS read-only open should not allocate an open context"))
        {
            std::error_code ec;
            std::filesystem::remove_all(context.session_root, ec);
            return false;
        }
        if (!Require(file->open_handle_count == 0, "Missing ADS read-only probes should not leak base-file open handles"))
        {
            std::error_code ec;
            std::filesystem::remove_all(context.session_root, ec);
            return false;
        }
    }

    PVOID base_ctx = nullptr;
    FSP_FSCTL_FILE_INFO info{};
    const auto base_open = CB_Open(
        &fs,
        const_cast<PWSTR>(L"\\document.docx"),
        FILE_NON_DIRECTORY_FILE,
        FILE_READ_DATA,
        &base_ctx,
        &info);
    if (!Require(base_open == STATUS_SUCCESS, "Base file should still open after missing ADS probes") ||
        !Require(base_ctx != nullptr, "Base file open should return a context"))
    {
        std::error_code ec;
        std::filesystem::remove_all(context.session_root, ec);
        return false;
    }

    std::array<char, 64> read_buffer{};
    ULONG read_done = 0;
    const auto read_status = CB_Read(
        &fs,
        base_ctx,
        read_buffer.data(),
        0,
        static_cast<ULONG>(read_buffer.size()),
        &read_done);
    CB_Close(&fs, base_ctx);

    bool base_bytes_match = read_done == base_payload.size();
    for (std::size_t index = 0; base_bytes_match && index < base_payload.size(); ++index)
    {
        base_bytes_match = static_cast<std::byte>(static_cast<unsigned char>(read_buffer[index])) == base_payload[index];
    }

    std::error_code ec;
    std::filesystem::remove_all(context.session_root, ec);
    return Require(read_status == STATUS_SUCCESS && base_bytes_match, "Missing ADS probes must not corrupt or consume base-file bytes");
}

bool TestDuplicateCaseNamedStreamsCoalesceMetadata()
{
    MountContext context{};
    context.overlay_write_enabled = true;
    context.args.volume = L"Main";
    if (!Require(PrepareUnitHydrationRoot(context, L"duplicate-case-stream"), "Duplicate-case stream test should prepare cache root"))
    {
        return false;
    }
    SeedRoot(context);

    auto root = context.nodes.at(Key(L"\\"));
    AddChildName(root->children, L"installer.exe");
    auto file = MakeNode(L"\\installer.exe", false, false);
    file->file_size = 12;
    context.nodes.emplace(Key(file->path), file);
    if (!Require(WriteFileBytes(HydrationPath(&context, *file), BuildPatternPayloadForTest(12, 0x18)), "Duplicate-case stream test should seed base file"))
    {
        std::error_code ec;
        std::filesystem::remove_all(context.session_root, ec);
        return false;
    }

    auto fs = BuildFileSystem(&context);
    PVOID lower_ctx = nullptr;
    FSP_FSCTL_FILE_INFO info{};
    const auto create_status = CB_Create(
        &fs,
        const_cast<PWSTR>(L"\\installer.exe:lh.identifier"),
        FILE_NON_DIRECTORY_FILE,
        FILE_WRITE_DATA | FILE_READ_DATA,
        0,
        nullptr,
        0,
        &lower_ctx,
        &info);
    if (!Require(create_status == STATUS_SUCCESS && lower_ctx != nullptr, "Lowercase named stream create should succeed"))
    {
        std::error_code ec;
        std::filesystem::remove_all(context.session_root, ec);
        return false;
    }

    const std::array<char, 4> payload{ 'A', 'D', 'S', '1' };
    ULONG done = 0;
    const auto write_status = CB_Write(
        &fs,
        lower_ctx,
        const_cast<char*>(payload.data()),
        0,
        static_cast<ULONG>(payload.size()),
        FALSE,
        FALSE,
        &done,
        &info);
    CB_Close(&fs, lower_ctx);
    if (!Require(write_status == STATUS_SUCCESS && done == payload.size(), "Lowercase named stream write should persist payload"))
    {
        std::error_code ec;
        std::filesystem::remove_all(context.session_root, ec);
        return false;
    }

    PVOID upper_ctx = nullptr;
    const auto upper_open = CB_Open(
        &fs,
        const_cast<PWSTR>(L"\\installer.exe:LH.IDENTIFIER"),
        FILE_NON_DIRECTORY_FILE,
        FILE_READ_DATA,
        &upper_ctx,
        &info);
    if (!Require(upper_open == STATUS_SUCCESS && upper_ctx != nullptr, "Duplicate-case named stream reopen should resolve the same stream"))
    {
        std::error_code ec;
        std::filesystem::remove_all(context.session_root, ec);
        return false;
    }

    std::array<char, 8> read_payload{};
    ULONG read_done = 0;
    const auto read_status = CB_Read(
        &fs,
        upper_ctx,
        read_payload.data(),
        0,
        static_cast<ULONG>(payload.size()),
        &read_done);
    CB_Close(&fs, upper_ctx);
    if (!Require(read_status == STATUS_SUCCESS && read_done == payload.size(), "Duplicate-case named stream read should return the existing payload") ||
        !Require(std::equal(payload.begin(), payload.end(), read_payload.begin()), "Duplicate-case named stream should read bytes from the original stream"))
    {
        std::error_code ec;
        std::filesystem::remove_all(context.session_root, ec);
        return false;
    }

    OpenContext base_open{};
    base_open.node = file;
    std::array<std::byte, 512> stream_buffer{};
    ULONG transferred = 0;
    const auto stream_status = CB_GetStreamInfo(
        &fs,
        &base_open,
        stream_buffer.data(),
        static_cast<ULONG>(stream_buffer.size()),
        &transferred);
    if (!Require(stream_status == STATUS_SUCCESS, "GetStreamInfo should succeed after duplicate-case stream opens"))
    {
        std::error_code ec;
        std::filesystem::remove_all(context.session_root, ec);
        return false;
    }

    int metadata_stream_count = 0;
    ULONG cursor = 0;
    while (cursor < transferred)
    {
        const auto* stream_info = reinterpret_cast<const FSP_FSCTL_STREAM_INFO*>(stream_buffer.data() + cursor);
        if (stream_info->Size < sizeof(FSP_FSCTL_STREAM_INFO) ||
            stream_info->Size > transferred - cursor)
        {
            std::error_code ec;
            std::filesystem::remove_all(context.session_root, ec);
            return Require(false, "Duplicate-case stream info should contain valid packed entries");
        }

        const auto name_chars = (stream_info->Size - sizeof(FSP_FSCTL_STREAM_INFO)) / sizeof(WCHAR);
        const std::wstring stream_name(stream_info->StreamNameBuf, name_chars);
        if (ToLowerInvariant(stream_name) == L"lh.identifier")
        {
            ++metadata_stream_count;
        }
        cursor += stream_info->Size;
    }

    std::error_code ec;
    std::filesystem::remove_all(context.session_root, ec);
    return Require(metadata_stream_count == 1, "Duplicate-case named streams should coalesce to one metadata stream entry");
}

bool TestOfficeTempRenameReplaceWorkflow()
{
    MountContext context{};
    context.overlay_write_enabled = true;
    context.args.volume = L"Main";
    if (!Require(PrepareUnitHydrationRoot(context, L"office-temp-rename"), "Office workflow test should prepare cache root"))
    {
        return false;
    }
    SeedRoot(context);

    auto root = context.nodes.at(Key(L"\\"));
    AddChildName(root->children, L"office");
    auto office_dir = MakeNode(L"\\office", true, false);
    context.nodes.emplace(Key(office_dir->path), office_dir);

    AddChildName(office_dir->children, L"document.docx");
    auto original = MakeNode(L"\\office\\document.docx", false, false);
    const auto original_payload = BuildPatternPayloadForTest(96, 0x21);
    original->file_size = original_payload.size();
    context.nodes.emplace(Key(original->path), original);
    if (!Require(WriteFileBytes(HydrationPath(&context, *original), original_payload), "Office workflow test should seed original document"))
    {
        std::error_code ec;
        std::filesystem::remove_all(context.session_root, ec);
        return false;
    }

    auto fs = BuildFileSystem(&context);
    PVOID lock_ctx = nullptr;
    FSP_FSCTL_FILE_INFO lock_info{};
    const auto lock_create = CB_Create(
        &fs,
        const_cast<PWSTR>(L"\\office\\~$document.docx"),
        FILE_NON_DIRECTORY_FILE,
        FILE_WRITE_DATA | DELETE,
        0,
        nullptr,
        0,
        &lock_ctx,
        &lock_info);
    if (!Require(lock_create == STATUS_SUCCESS && lock_ctx != nullptr, "Office lock file create should succeed"))
    {
        std::error_code ec;
        std::filesystem::remove_all(context.session_root, ec);
        return false;
    }
    auto* lock_open = static_cast<OpenContext*>(lock_ctx);
    lock_open->allow_delete = true;
    CB_Cleanup(&fs, lock_ctx, const_cast<PWSTR>(L"\\office\\~$document.docx"), FspCleanupDelete);
    CB_Close(&fs, lock_ctx);
    if (!Require(context.nodes.find(Key(L"\\office\\~$document.docx")) == context.nodes.end(), "Office lock file delete-on-close should remove the temp lock node"))
    {
        std::error_code ec;
        std::filesystem::remove_all(context.session_root, ec);
        return false;
    }

    PVOID temp_ctx = nullptr;
    FSP_FSCTL_FILE_INFO temp_info{};
    const auto temp_create = CB_Create(
        &fs,
        const_cast<PWSTR>(L"\\office\\document.tmp"),
        FILE_NON_DIRECTORY_FILE,
        FILE_WRITE_DATA | FILE_READ_DATA | DELETE,
        0,
        nullptr,
        0,
        &temp_ctx,
        &temp_info);
    if (!Require(temp_create == STATUS_SUCCESS && temp_ctx != nullptr, "Office save temp file create should succeed"))
    {
        std::error_code ec;
        std::filesystem::remove_all(context.session_root, ec);
        return false;
    }

    const auto saved_payload = BuildPatternPayloadForTest(128, 0x63);
    ULONG temp_written = 0;
    const auto temp_write = CB_Write(
        &fs,
        temp_ctx,
        const_cast<std::byte*>(saved_payload.data()),
        0,
        static_cast<ULONG>(saved_payload.size()),
        FALSE,
        FALSE,
        &temp_written,
        &temp_info);
    CB_Close(&fs, temp_ctx);
    if (!Require(temp_write == STATUS_SUCCESS && temp_written == saved_payload.size(), "Office save temp file write should persist all bytes"))
    {
        std::error_code ec;
        std::filesystem::remove_all(context.session_root, ec);
        return false;
    }

    const auto rename_status = CB_Rename(
        &fs,
        nullptr,
        const_cast<PWSTR>(L"\\office\\document.tmp"),
        const_cast<PWSTR>(L"\\office\\document.docx"),
        TRUE);
    if (!Require(rename_status == STATUS_SUCCESS, "Office temp save should rename-replace the original document"))
    {
        std::error_code ec;
        std::filesystem::remove_all(context.session_root, ec);
        return false;
    }

    auto saved_node = FindNode(&context, L"\\office\\document.docx");
    if (!Require(saved_node != nullptr, "Office temp save should leave the final document visible") ||
        !Require(context.nodes.find(Key(L"\\office\\document.tmp")) == context.nodes.end(), "Office temp save should remove the temp source path") ||
        !Require(saved_node->file_size == saved_payload.size(), "Office temp save should expose the saved document size"))
    {
        std::error_code ec;
        std::filesystem::remove_all(context.session_root, ec);
        return false;
    }

    const auto saved_bytes = ReadFileBytes(HydrationPath(&context, *saved_node));
    std::error_code ec;
    std::filesystem::remove_all(context.session_root, ec);
    return Require(saved_bytes == saved_payload, "Office temp save should preserve the exact replacement bytes");
}

bool TestRecycleBinMetadataPairWorkflow()
{
    MountContext context{};
    context.overlay_write_enabled = true;
    context.args.volume = L"Main";
    if (!Require(PrepareUnitHydrationRoot(context, L"recycle-metadata-pair"), "Recycle workflow test should prepare cache root"))
    {
        return false;
    }
    SeedRoot(context);

    auto root = context.nodes.at(Key(L"\\"));
    AddChildName(root->children, L"$RECYCLE.BIN");
    auto recycle = MakeNode(L"\\$RECYCLE.BIN", true, false);
    context.nodes.emplace(Key(recycle->path), recycle);
    AddChildName(recycle->children, L"S-1-5-21-1000-1000-1000-1001");
    auto sid = MakeNode(L"\\$RECYCLE.BIN\\S-1-5-21-1000-1000-1000-1001", true, false);
    context.nodes.emplace(Key(sid->path), sid);
    AddChildName(root->children, L"files");
    auto files = MakeNode(L"\\files", true, false);
    context.nodes.emplace(Key(files->path), files);
    AddChildName(files->children, L"delete-me.bin");
    auto source = MakeNode(L"\\files\\delete-me.bin", false, false);
    const auto payload = BuildPatternPayloadForTest(256, 0x77);
    source->file_size = payload.size();
    context.nodes.emplace(Key(source->path), source);
    if (!Require(WriteFileBytes(HydrationPath(&context, *source), payload), "Recycle workflow test should seed source payload"))
    {
        std::error_code ec;
        std::filesystem::remove_all(context.session_root, ec);
        return false;
    }

    auto fs = BuildFileSystem(&context);
    const auto move_to_bin = CB_Rename(
        &fs,
        nullptr,
        const_cast<PWSTR>(L"\\files\\delete-me.bin"),
        const_cast<PWSTR>(L"\\$RECYCLE.BIN\\S-1-5-21-1000-1000-1000-1001\\$RCODEX01.bin"),
        FALSE);
    if (!Require(move_to_bin == STATUS_SUCCESS, "Recycle workflow should move payload to $R entry"))
    {
        std::error_code ec;
        std::filesystem::remove_all(context.session_root, ec);
        return false;
    }

    PVOID info_ctx = nullptr;
    FSP_FSCTL_FILE_INFO info{};
    const auto info_create = CB_Create(
        &fs,
        const_cast<PWSTR>(L"\\$RECYCLE.BIN\\S-1-5-21-1000-1000-1000-1001\\$ICODEX01.bin"),
        FILE_NON_DIRECTORY_FILE,
        FILE_WRITE_DATA | DELETE,
        0,
        nullptr,
        0,
        &info_ctx,
        &info);
    if (!Require(info_create == STATUS_SUCCESS && info_ctx != nullptr, "Recycle workflow should create $I metadata entry"))
    {
        std::error_code ec;
        std::filesystem::remove_all(context.session_root, ec);
        return false;
    }
    const std::array<char, 9> info_payload{ 'm', 'e', 't', 'a', 'd', 'a', 't', 'a', '\n' };
    ULONG info_written = 0;
    const auto info_write = CB_Write(
        &fs,
        info_ctx,
        const_cast<char*>(info_payload.data()),
        0,
        static_cast<ULONG>(info_payload.size()),
        FALSE,
        FALSE,
        &info_written,
        &info);
    if (!Require(info_write == STATUS_SUCCESS && info_written == info_payload.size(), "Recycle workflow should write $I metadata bytes"))
    {
        CB_Close(&fs, info_ctx);
        std::error_code ec;
        std::filesystem::remove_all(context.session_root, ec);
        return false;
    }

    const auto restore_status = CB_Rename(
        &fs,
        nullptr,
        const_cast<PWSTR>(L"\\$RECYCLE.BIN\\S-1-5-21-1000-1000-1000-1001\\$RCODEX01.bin"),
        const_cast<PWSTR>(L"\\files\\restored.bin"),
        FALSE);
    if (!Require(restore_status == STATUS_SUCCESS, "Recycle workflow should restore $R payload by rename"))
    {
        CB_Close(&fs, info_ctx);
        std::error_code ec;
        std::filesystem::remove_all(context.session_root, ec);
        return false;
    }

    auto* info_open = static_cast<OpenContext*>(info_ctx);
    info_open->allow_delete = true;
    const auto delete_info = CB_SetDelete(
        &fs,
        info_ctx,
        const_cast<PWSTR>(L"\\$RECYCLE.BIN\\S-1-5-21-1000-1000-1000-1001\\$ICODEX01.bin"),
        TRUE);
    if (!Require(delete_info == STATUS_SUCCESS, "Recycle workflow should mark $I metadata for deletion"))
    {
        CB_Close(&fs, info_ctx);
        std::error_code ec;
        std::filesystem::remove_all(context.session_root, ec);
        return false;
    }
    CB_Cleanup(&fs, info_ctx, const_cast<PWSTR>(L"\\$RECYCLE.BIN\\S-1-5-21-1000-1000-1000-1001\\$ICODEX01.bin"), FspCleanupDelete);
    CB_Close(&fs, info_ctx);

    auto restored = FindNode(&context, L"\\files\\restored.bin");
    if (!Require(restored != nullptr, "Recycle workflow should leave restored payload visible") ||
        !Require(context.nodes.find(Key(L"\\$RECYCLE.BIN\\S-1-5-21-1000-1000-1000-1001\\$ICODEX01.bin")) == context.nodes.end(), "Recycle workflow should delete $I metadata node") ||
        !Require(context.nodes.find(Key(L"\\$RECYCLE.BIN\\S-1-5-21-1000-1000-1000-1001\\$RCODEX01.bin")) == context.nodes.end(), "Recycle workflow should remove $R payload from recycle folder"))
    {
        std::error_code ec;
        std::filesystem::remove_all(context.session_root, ec);
        return false;
    }

    const auto restored_bytes = ReadFileBytes(HydrationPath(&context, *restored));
    std::error_code ec;
    std::filesystem::remove_all(context.session_root, ec);
    return Require(restored_bytes == payload, "Recycle workflow should preserve restored payload bytes");
}

bool TestPathNormalizationMatrixRejectsRiskyWin32Names()
{
    MountContext context{};
    context.overlay_write_enabled = true;
    context.args.volume = L"Main";
    SeedRoot(context);
    std::array<std::byte, 16> security{};
    SeedSecurity(context, security);

    auto fs = BuildFileSystem(&context);
    const std::wstring long_component = L"\\" + std::wstring(256, L'n') + L".txt";
    const std::array<std::wstring, 6> invalid_paths
    {
        L"\\CON",
        L"\\AUX.txt",
        L"\\trailing-space ",
        L"\\trailing-dot.",
        L"\\bad<name>.txt",
        long_component
    };

    for (const auto& path : invalid_paths)
    {
        PVOID out_ctx = nullptr;
        FSP_FSCTL_FILE_INFO info{};
        const auto status = CB_Create(
            &fs,
            const_cast<PWSTR>(path.c_str()),
            FILE_NON_DIRECTORY_FILE,
            FILE_WRITE_DATA,
            0,
            nullptr,
            0,
            &out_ctx,
            &info);
        if (!Require(status == STATUS_OBJECT_NAME_INVALID, "Risky Win32 path create should fail before mutation"))
        {
            if (out_ctx)
            {
                CB_Close(&fs, out_ctx);
            }
            return false;
        }
        if (!Require(context.nodes.find(Key(path)) == context.nodes.end(), "Rejected risky Win32 path should not create a node"))
        {
            return false;
        }
    }

    auto root = context.nodes.at(Key(L"\\"));
    const std::wstring valid_unicode_path = L"\\文件-" + std::wstring(L"\xD83D\xDE80") + L"-I-\x0130-\x0131.txt";
    PVOID valid_ctx = nullptr;
    FSP_FSCTL_FILE_INFO valid_info{};
    const auto valid_create = CB_Create(
        &fs,
        const_cast<PWSTR>(valid_unicode_path.c_str()),
        FILE_NON_DIRECTORY_FILE,
        FILE_WRITE_DATA | DELETE,
        0,
        nullptr,
        0,
        &valid_ctx,
        &valid_info);
    if (!Require(valid_create == STATUS_SUCCESS && valid_ctx != nullptr, "Unicode path matrix should allow normal Chinese, emoji, and Turkish I names"))
    {
        return false;
    }
    CB_Close(&fs, valid_ctx);

    const auto case_rename = CB_Rename(
        &fs,
        nullptr,
        const_cast<PWSTR>(valid_unicode_path.c_str()),
        const_cast<PWSTR>(L"\\文件-\xD83D\xDE80-i-\x0130-\x0131.txt"),
        FALSE);
    if (!Require(case_rename == STATUS_SUCCESS, "Path matrix should allow case-only rename of a valid Unicode name"))
    {
        return false;
    }
    return Require(
        HasChildName(root->children, L"文件-\xD83D\xDE80-i-\x0130-\x0131.txt") &&
            context.nodes.find(Key(L"\\文件-\xD83D\xDE80-i-\x0130-\x0131.txt")) != context.nodes.end(),
        "Case-only Unicode rename should update the visible directory entry");
}

bool TestNormalizePathStripsDriveQualifiedRoot()
{
    if (!Require(NormalizePath(L"E:") == L"\\", "NormalizePath should treat drive-qualified current-directory roots as volume root"))
    {
        return false;
    }
    if (!Require(NormalizePath(L"E:\\") == L"\\", "NormalizePath should treat drive-qualified slash roots as volume root"))
    {
        return false;
    }
    if (!Require(NormalizePath(L"E:\\folder\\file.txt") == L"\\folder\\file.txt", "NormalizePath should strip drive prefixes from absolute child paths"))
    {
        return false;
    }

    return Require(NormalizePath(L"folder\\file.txt") == L"\\folder\\file.txt", "NormalizePath should preserve relative child path behavior");
}

bool TestVisibleLookupReusesNormalizedPathWithoutExtraNormalization()
{
#ifdef APFSACCESS_FSHOST_UNIT_TEST
    MountContext context{};
    SeedRoot(context);
    auto parent = MakeNode(L"\\parent", true, false);
    auto child = MakeNode(L"\\parent\\child.txt", false, false);
    AddChildName(*parent, L"child.txt");
    context.nodes.emplace(Key(parent->path), parent);
    context.nodes.emplace(Key(child->path), child);

    ResetChildNameDebugCountersForTest();
    const auto before = g_normalize_path_call_count_for_test;

    auto visible = FindNode(&context, L"\\parent\\child.txt");
    if (!Require(visible == child, "Visible lookup should find the child node"))
    {
        return false;
    }

    const auto after = g_normalize_path_call_count_for_test;
    return Require(
        after == before + 1,
        "Visible lookup should normalize the path only once for the full lookup chain");
#else
    return true;
#endif
}

bool TestChildTraversalUsesCachedPathKeys()
{
#ifdef APFSACCESS_FSHOST_UNIT_TEST
    MountContext context{};
    context.overlay_write_enabled = true;
    context.args.volume = L"Main";
    SeedRoot(context);

    auto root = context.nodes.at(Key(L"\\"));
    auto parent = MakeNode(L"\\parent", true, false);
    auto child_dir = MakeNode(L"\\parent\\ChildDir", true, false);
    auto leaf = MakeNode(L"\\parent\\ChildDir\\Leaf.TXT", false, false);
    leaf->file_size = 1;
    AddChildName(*root, L"parent");
    AddChildName(*parent, L"ChildDir");
    AddChildName(*child_dir, L"Leaf.TXT");
    context.nodes.emplace(Key(parent->path), parent);
    context.nodes.emplace(Key(child_dir->path), child_dir);
    context.nodes.emplace(Key(leaf->path), leaf);

    OpenContext dir_context{};
    dir_context.node = parent;
    dir_context.allow_list_directory = true;
    auto fs = BuildFileSystem(&context);
    context.api.AddDir = [](FSP_FSCTL_DIR_INFO*, PVOID, ULONG, PULONG done) -> BOOLEAN
    {
        if (done)
        {
            ++*done;
        }
        return TRUE;
    };

    std::array<std::byte, 2048> buffer{};
    ULONG transferred = 0;
    ResetChildNameDebugCountersForTest();
    const auto before = g_normalize_path_call_count_for_test;
    const auto read_status = CB_ReadDirectory(
        &fs,
        &dir_context,
        nullptr,
        nullptr,
        buffer.data(),
        static_cast<ULONG>(buffer.size()),
        &transferred);
    if (!Require(read_status == STATUS_SUCCESS, "Cached child traversal should keep directory enumeration working"))
    {
        return false;
    }

    bool removable = false;
    {
        std::lock_guard<std::mutex> lock(context.mutex);
        removable = CanRemoveNodeRecursiveLocked(&context, parent);
    }
    if (!Require(removable, "Cached child traversal should keep recursive readiness checks working"))
    {
        return false;
    }

    const auto after = g_normalize_path_call_count_for_test;
    return Require(
               after == before,
               "Cached child traversal should not normalize child paths in indexed live-tree walks") &&
           Require(
               DebugChildNodeCachedLookupCountForTest() >= 3,
               "Cached child traversal should use path-key child lookup for directory and subtree walks") &&
           Require(
               DebugChildNodeCachedLookupFallbackCountForTest() == 0,
               "Cached child traversal should not fall back when node path keys are current");
#else
    return true;
#endif
}

bool TestOpenAndSecurityReuseNormalizedStreamPath()
{
#ifdef APFSACCESS_FSHOST_UNIT_TEST
    MountContext context{};
    SeedRoot(context);
    std::array<std::byte, 16> security{};
    SeedSecurity(context, security);

    auto parent = MakeNode(L"\\parent", true, false);
    auto child = MakeNode(L"\\parent\\childdir", true, false);
    AddChildName(*parent, L"childdir");
    context.nodes.emplace(Key(parent->path), parent);
    context.nodes.emplace(Key(child->path), child);

    auto fs = BuildFileSystem(&context);
    UINT32 attrs = 0;
    std::array<std::byte, 16> output_security{};
    SIZE_T security_size = output_security.size();
    PVOID out_ctx = nullptr;
    FSP_FSCTL_FILE_INFO info{};

    ResetChildNameDebugCountersForTest();
    const auto before = g_normalize_path_call_count_for_test;

    const auto security_status = CB_GetSecurityByName(
        &fs,
        const_cast<PWSTR>(L"\\parent\\childdir"),
        &attrs,
        reinterpret_cast<PSECURITY_DESCRIPTOR>(output_security.data()),
        &security_size);
    if (!Require(security_status == STATUS_SUCCESS, "GetSecurityByName should succeed for indexed directory"))
    {
        return false;
    }

    const auto open_status = CB_Open(
        &fs,
        const_cast<PWSTR>(L"\\parent\\childdir"),
        FILE_DIRECTORY_FILE,
        FILE_LIST_DIRECTORY,
        &out_ctx,
        &info);
    if (!Require(open_status == STATUS_SUCCESS && out_ctx != nullptr, "Open should succeed for indexed directory"))
    {
        if (out_ctx)
        {
            CB_Close(&fs, out_ctx);
        }
        return false;
    }
    const auto after = g_normalize_path_call_count_for_test;
    CB_Close(&fs, out_ctx);

    return Require(
        after == before + 2,
        "Open and GetSecurityByName should each normalize only the incoming callback path");
#else
    return true;
#endif
}

bool TestStableVolumeSerialDependsOnVolumeIdentityNotProcessUptime()
{
    Arguments first{};
    first.device = L"\\\\.\\PhysicalDrive2";
    first.volume = L"Main";
    first.device_offset_bytes = 4096;

    Arguments same = first;
    Arguments other = first;
    other.volume = L"Other";

    const auto serial = BuildStableVolumeSerial(first);
    if (!Require(serial != 0, "Stable volume serial should never be zero"))
    {
        return false;
    }
    if (!Require(serial == BuildStableVolumeSerial(same), "Stable volume serial should be deterministic for the same APFS volume identity"))
    {
        return false;
    }
    return Require(serial != BuildStableVolumeSerial(other), "Stable volume serial should change when the APFS volume identity changes");
}

constexpr wchar_t kRecoveryIdentityA[] =
    L"apfs-recovery-v1-47DEQpj8HBSa-_TImW-5JCeuQeRkm5NMpJWZG3hSuFU";
constexpr wchar_t kRecoveryIdentityB[] =
    L"apfs-recovery-v1-LXEWQrcmsEQBYnyp-6wy9chTD7GQPMTb_AZ4XfJjSBg";

bool TestImmutableRecoveryIdentitySurvivesDeviceRenumbering()
{
    Arguments first{};
    first.device = L"\\\\.\\PhysicalDrive2";
    first.volume = L"Main";
    first.device_offset_bytes = 4096;
    first.write_backend = L"Native";
    first.recovery_identity = kRecoveryIdentityA;

    Arguments renumbered = first;
    renumbered.device = L"\\\\.\\PhysicalDrive9";

    const std::filesystem::path base =
        std::filesystem::temp_directory_path() / L"ApfsAccessUnitSpool";
    return Require(
               BuildWalVolumeIdentity(first) == BuildWalVolumeIdentity(renumbered),
               "Immutable WAL identity should survive PhysicalDrive renumbering") &&
           Require(
               BuildPayloadSpoolSessionRoot(first, base) ==
                   BuildPayloadSpoolSessionRoot(renumbered, base),
               "Immutable spool root should survive PhysicalDrive renumbering") &&
           Require(
               BuildRecoveryMarkerPath(first) == BuildRecoveryMarkerPath(renumbered),
               "Immutable recovery marker should survive PhysicalDrive renumbering") &&
           Require(
               BuildStableVolumeSerial(first) == BuildStableVolumeSerial(renumbered),
               "Explorer volume serial should survive PhysicalDrive renumbering");
}

