bool TestParseArgsAcceptsImmutableRecoveryIdentity()
{
    const std::wstring expected = kRecoveryIdentityA;
    std::vector<std::wstring> raw_args
    {
        L"ApfsAccess.FsHost.exe",
        L"--device", L"\\\\.\\PhysicalDrive3",
        L"--device-offset", L"4096",
        L"--volume", L"Main",
        L"--mount", L"P:",
        L"--readwrite",
        L"--parent-pid", std::to_wstring(GetCurrentProcessId()),
        L"--lifetime-file", L"parent.alive",
        L"--startup-gate-file", L"parent.gate",
        L"--startup-gate-token", L"authorized-token",
        L"--recovery-identity", expected,
    };
    std::vector<wchar_t*> argv;
    argv.reserve(raw_args.size());
    for (auto& token : raw_args)
    {
        argv.push_back(token.data());
    }

    Arguments parsed{};
    return Require(
               ParseArgs(static_cast<int>(argv.size()), argv.data(), parsed),
               "ParseArgs should accept immutable recovery identity") &&
           Require(
               parsed.recovery_identity == expected,
               "ParseArgs should preserve immutable recovery identity exactly");
}

