bool TestImmutableRecoveryIdentityValidatesBackendFormat()
{
    auto invalid_character = std::wstring(kRecoveryIdentityA);
    invalid_character[invalid_character.size() - 2] = L'+';
    auto noncanonical_tail = std::wstring(kRecoveryIdentityA);
    noncanonical_tail.back() = L'B';

    return Require(
               IsValidRecoveryIdentity(kRecoveryIdentityA),
               "FsHost should accept the backend's versioned SHA-256 base64url identity") &&
           Require(
               !IsValidRecoveryIdentity(L"apfs-recovery-v1|partition=legacy"),
               "FsHost should reject the legacy descriptive identity shape") &&
           Require(
               !IsValidRecoveryIdentity(std::wstring(kRecoveryIdentityA).substr(0, std::wcslen(kRecoveryIdentityA) - 1)),
               "FsHost should reject a truncated recovery digest") &&
           Require(
               !IsValidRecoveryIdentity(std::wstring(kRecoveryIdentityA) + L"="),
               "FsHost should reject padded base64 identities") &&
           Require(
               !IsValidRecoveryIdentity(invalid_character),
               "FsHost should reject non-base64url identity characters") &&
           Require(
               !IsValidRecoveryIdentity(noncanonical_tail),
               "FsHost should reject noncanonical SHA-256 base64url tails");
}

bool TestWrongImmutableRecoveryIdentityRejectsWalReplay()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    std::error_code ec;
    const auto run_root = std::filesystem::temp_directory_path(ec) /
        "ApfsAccess" /
        "fs-host-semantics" /
        "wrong-immutable-recovery-identity";
    if (!Require(!ec, "Wrong-media WAL test should resolve the D-drive temp root"))
    {
        return false;
    }
    std::filesystem::remove_all(run_root, ec);
    ec.clear();
    std::filesystem::create_directories(run_root, ec);
    if (!Require(!ec, "Wrong-media WAL test should create its temp root"))
    {
        return false;
    }

    const auto first_identity = WideToUtf8(kRecoveryIdentityA);
    const auto other_identity = WideToUtf8(kRecoveryIdentityB);
    const auto wal_path = run_root / "write-ahead.wal";
    {
        apfsaccess::rw::WriteAheadLog wal({wal_path, first_identity, 1024 * 1024});
        apfsaccess::rw::WriteAheadLog::Record record{};
        record.transaction_id = 1;
        record.sequence = 1;
        record.operation = apfsaccess::rw::WriteAheadLog::OperationKind::CreateFile;
        record.state = apfsaccess::rw::WriteAheadLog::RecordState::Prepared;
        record.object_id = 42;
        record.path_utf8 = "\\\\probe.bin";
        if (!Require(wal.Append(record), "Wrong-media WAL test should persist source evidence"))
        {
            std::filesystem::remove_all(run_root, ec);
            return false;
        }
    }

    const auto wrong_media =
        apfsaccess::rw::WriteAheadLog::ReadAll(wal_path, other_identity);
    std::filesystem::remove_all(run_root, ec);
    return Require(
        wrong_media.status == apfsaccess::rw::WriteAheadLog::ReadStatus::VolumeMismatch,
        "WAL replay should reject evidence from a different immutable recovery identity");
#else
    return true;
#endif
}

bool TestPhysicalNativeWriteRequiresImmutableRecoveryIdentity()
{
    Arguments physical{};
    physical.device = L"\\\\.\\PhysicalDrive3";
    physical.readwrite = true;
    physical.write_backend = L"Native";

    if (!Require(
            !HasRequiredRecoveryIdentityForNativeWrite(physical),
            "Raw physical native write should fail closed without immutable recovery identity"))
    {
        return false;
    }

    physical.recovery_identity = L"apfs-recovery-v1|partition=legacy";
    if (!Require(
            !HasRequiredRecoveryIdentityForNativeWrite(physical),
            "Raw physical native write should reject malformed recovery identity"))
    {
        return false;
    }

    physical.recovery_identity = kRecoveryIdentityA;
    if (!Require(
            HasRequiredRecoveryIdentityForNativeWrite(physical),
            "Raw physical native write should accept an immutable recovery identity"))
    {
        return false;
    }

    Arguments fixture = physical;
    fixture.device =
        (std::filesystem::temp_directory_path() / L"apfsaccess-fixture.apfs.img").wstring();
    fixture.recovery_identity.clear();
    return Require(
        HasRequiredRecoveryIdentityForNativeWrite(fixture),
        "Image-backed fixtures may retain legacy path identity compatibility");
}

bool TestRecoveryIdentityStartupPolicyFailsPhysicalNativeWriteClosed()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    const auto run_root = std::filesystem::temp_directory_path() /
        "ApfsAccess" /
        "fs-host-semantics" /
        "recovery-identity-startup-policy";
    MountContext context{};
    context.args.device = L"\\\\.\\PhysicalDrive3";
    context.args.volume = L"Main";
    context.args.readwrite = true;
    context.args.write_backend = L"Native";
    context.native_write_enabled = true;

    const auto allowed = EnforceRecoveryIdentityStartupPolicy(
        context,
        run_root / "spool",
        run_root / "recovery");
    return Require(!allowed, "Missing immutable identity should block physical native RW startup") &&
           Require(context.recovery_identity_blocked, "Missing immutable identity should latch the startup policy") &&
           Require(!context.native_write_enabled, "Missing immutable identity should leave the mounted volume read-only") &&
           Require(context.write_degraded, "Missing immutable identity should report degraded write state") &&
           Require(context.recovery_active, "Missing immutable identity should expose a recovery signal") &&
           Require(
               context.runtime_recovery_reason == L"ImmutableRecoveryIdentityMissing",
               "Missing immutable identity should preserve its status reason");
#else
    return true;
#endif
}

