bool TestRecoveryMarkerBlockPreservesBootstrapFailureAndReplayState()
{
#ifdef APFSACCESS_HAS_RW_ENGINE
    MountContext context{};
    context.args.readwrite = true;
    context.args.write_backend = L"Native";
    context.native_write_enabled = false;
    context.recovery_marker_blocked = true;
    context.pending_native_writes = true;
    context.recovery_active = true;
    context.write_degraded = true;
    context.runtime_recovery_reason = L"RecoveryMarkerInvalid";
    context.runtime_last_recovery_action = L"RecoveryMarkerInvalidAtStartup";

    RecordVolumeStateBootstrapFailure(context);
    const auto bootstrap_reason = context.runtime_recovery_reason;
    const auto bootstrap_action = context.runtime_last_recovery_action;
    const auto replay_result = ReplayAcceptedWriteAheadLogAfterMetadataBootstrap(context);

    return Require(
               context.runtime_recovery_reason == L"RecoveryMarkerInvalid" &&
                   context.runtime_recovery_reason == bootstrap_reason,
               "Marker-blocked volume-state failure must preserve RecoveryMarkerInvalid reason") &&
           Require(
               context.runtime_last_recovery_action == L"RecoveryMarkerInvalidAtStartup" &&
                   context.runtime_last_recovery_action == bootstrap_action,
               "Marker-blocked volume-state failure must preserve RecoveryMarkerInvalid action") &&
           Require(
               context.recovery_marker_blocked && context.pending_native_writes &&
                   context.recovery_active && context.write_degraded &&
                   !context.native_write_enabled,
               "Marker-blocked volume-state failure must preserve degraded recovery state") &&
           Require(!replay_result,
               "Marker-blocked accepted-write replay must be a no-op failure") &&
           Require(
               context.runtime_recovery_reason == bootstrap_reason &&
                   context.runtime_last_recovery_action == bootstrap_action,
               "Marker-blocked accepted-write replay must not overwrite recovery state");
#else
    return true;
#endif
}

