{
    MountContext context{};
    context.label = BuildExplorerVolumeLabel(L"Main");
    std::array<std::byte, 16> security{};
    SeedSecurity(context, security);
    SeedRoot(context);

    auto fs = BuildFileSystem(&context);
    FSP_FSCTL_VOLUME_INFO volume_info{};
    const auto empty_status = CB_GetVolumeInfo(&fs, &volume_info);
    if (!Require(empty_status == STATUS_SUCCESS, "GetVolumeInfo should succeed without metadata store"))
    {
        return false;
    }
    if (!Require(volume_info.TotalSize == 0 && volume_info.FreeSize == 0, "GetVolumeInfo should fall back to zero values when metadata is unavailable"))
    {
        return false;
    }
    if (!Require(volume_info.VolumeLabelLength == 4 * sizeof(WCHAR), "GetVolumeInfo should expose the APFS volume label without debug suffixes"))
    {
        return false;
    }
    if (!Require(std::wstring(volume_info.VolumeLabel, volume_info.VolumeLabelLength / sizeof(WCHAR)) == L"Main", "GetVolumeInfo should report the native volume label"))
    {
        return false;
    }

    context.reported_total_size_bytes = 1000;
    context.reported_free_size_bytes.reset();
    context.reported_allocation_unit_bytes = 128;
    const auto fallback_status = CB_GetVolumeInfo(&fs, &volume_info);
    if (!Require(fallback_status == STATUS_SUCCESS, "GetVolumeInfo should succeed with reported fallback capacity"))
    {
        return false;
    }
    if (!Require(volume_info.TotalSize == 896 && volume_info.FreeSize == 0, "GetVolumeInfo preserves aligned capacity while unavailable free space stays conservative"))
    {
        return false;
    }
    context.reported_total_size_bytes.reset();
    context.reported_free_size_bytes.reset();
    context.reported_allocation_unit_bytes = 4096;

#ifdef APFSACCESS_HAS_RW_ENGINE
    context.reported_total_size_bytes = 1024 * 1024;
    context.reported_free_size_bytes = 512 * 1024;
    apfsaccess::rw::MetadataStore unavailable(apfsaccess::rw::MetadataStore::VolumeContext{});
    context.metadata_store = &unavailable;
    RefreshReportedVolumeInfoFromMetadata(context);
    context.metadata_store = nullptr;
    if (!Require(CB_GetVolumeInfo(&fs, &volume_info) == STATUS_SUCCESS &&
            volume_info.TotalSize == 0 && volume_info.FreeSize == 0,
            "unavailable current metadata clears earlier cached capacity claims")) return false;
#endif
    return true;
}

bool TestVolumeInfoDoesNotWaitOnMetadataMutex()
{
    MountContext context{};
    context.label = BuildExplorerVolumeLabel(L"Main");
    context.reported_total_size_bytes = 1024 * 1024;
    context.reported_free_size_bytes = 512 * 1024;
    context.reported_allocation_unit_bytes = 4096;
    std::array<std::byte, 16> security{};
    SeedSecurity(context, security);
    SeedRoot(context);

    auto fs = BuildFileSystem(&context);
    FSP_FSCTL_VOLUME_INFO volume_info{};
    std::unique_lock<std::mutex> metadata_lock(context.metadata_mutex);
    auto result = std::async(std::launch::async, [&]()
    {
        return CB_GetVolumeInfo(&fs, &volume_info);
    });
    if (!Require(
            result.wait_for(std::chrono::milliseconds(100)) == std::future_status::ready,
            "GetVolumeInfo should not wait on the metadata mutex"))
    {
        metadata_lock.unlock();
        (void)result.wait();
        return false;
    }
    metadata_lock.unlock();

    return Require(result.get() == STATUS_SUCCESS, "Cached GetVolumeInfo should succeed") &&
           Require(volume_info.TotalSize == 1024 * 1024, "GetVolumeInfo should use the cached total size") &&
           Require(volume_info.FreeSize == 512 * 1024, "GetVolumeInfo should use the cached free size");
}

bool TestMetadataOnlyRootDoesNotWaitOnCommit()
{
    MountContext context{};
    context.native_write_enabled = true;
    context.api.AddDir = [](FSP_FSCTL_DIR_INFO*, PVOID, ULONG, PULONG) -> BOOLEAN { return TRUE; };
    std::array<std::byte, 16> security{};
    SeedSecurity(context, security);
    SeedRoot(context);
    auto fs = BuildFileSystem(&context);
    std::unique_lock<std::mutex> commit_lock(context.metadata_mutex);
    std::atomic<const char*> step{"security"};
    auto result = std::async(std::launch::async, [&]()
    {
        UINT32 attributes = 0;
        SIZE_T size = security.size();
        std::array<std::byte, 16> descriptor{};
        if (CB_GetSecurityByName(&fs, const_cast<PWSTR>(L"\\"), &attributes,
                descriptor.data(), &size) != STATUS_SUCCESS) return false;
        PVOID opened = nullptr;
        FSP_FSCTL_FILE_INFO info{};
        step = "open";
        if (CB_Open(&fs, const_cast<PWSTR>(L"\\"), (FILE_OPEN << 24) | FILE_DIRECTORY_FILE,
                FILE_READ_ATTRIBUTES | SYNCHRONIZE, &opened, &info) != STATUS_SUCCESS) return false;
        step = "query";
        const auto status = CB_GetFileInfo(&fs, opened, &info);
        step = "cleanup";
        CB_Cleanup(&fs, opened, nullptr, FspCleanupSetLastAccessTime);
        step = "close";
        CB_Close(&fs, opened);
        if (status != STATUS_SUCCESS) return false;
        step = "directory-open";
        if (CB_Open(&fs, const_cast<PWSTR>(L"\\"), (FILE_OPEN << 24) | FILE_DIRECTORY_FILE,
                FILE_READ_ATTRIBUTES | FILE_LIST_DIRECTORY, &opened, &info) != STATUS_SUCCESS) return false;
        std::array<std::byte, 1024> entries{};
        ULONG transferred = 0;
        step = "directory-query";
        const auto listing = CB_ReadDirectory(&fs, opened, nullptr, nullptr,
            entries.data(), static_cast<ULONG>(entries.size()), &transferred);
        step = "directory-cleanup-close";
        CB_Cleanup(&fs, opened, nullptr, 0);
        CB_Close(&fs, opened);
        return listing == STATUS_SUCCESS;
    });
    const bool responsive = result.wait_for(std::chrono::milliseconds(200)) == std::future_status::ready;
    if (!responsive) std::cerr << "[INFO] root query blocked at " << step.load() << '\n';
    commit_lock.unlock();
    const bool succeeded = result.get();
    if (!Require(responsive && succeeded,
            "Root security/open/query/cleanup/close must finish while the commit mutex is held")) return false;
    context.recovery_active = true;
    if (!Require(ReportsReadOnly(&context), "Recovery is reported read only immediately")) return false;
    context.recovery_active = false;
    context.write_degraded = true;
    return Require(ReportsReadOnly(&context), "Degraded state is reported read only immediately");
}

